INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(1, 1, 1, '爱', 'ài', 'yêu, thích', '我爱你。', 'Wǒ ài nǐ.', 'Tôi yêu bạn.'),
(2, 1, 2, '八', 'bā', 'số tám', '他有八个苹果。', 'Tā yǒu bā gè píngguǒ.', 'Anh ấy có tám quả táo.'),
(3, 1, 3, '爸爸', 'bàba', 'bố, ba', '我的爸爸很高。', 'Wǒ de bàba hěn gāo.', 'Bố của tôi rất cao.'),
(4, 1, 4, '杯子', 'bēizi', 'cốc, ly', '这是我的杯子。', 'Zhè shì wǒ de bēizi.', 'Đây là cốc của tôi.'),
(5, 1, 5, '北京', 'Běijīng', 'Bắc Kinh', '北京很大。', 'Běijīng hěn dà.', 'Bắc Kinh rất lớn.'),
(6, 1, 6, '本', 'běn', 'quyển, cuốn (lượng từ)', '桌子上有一本书。', 'Zhuōzi shàng yǒu yī běn shū.', 'Trên bàn có một quyển sách.'),
(7, 1, 7, '不客气', 'bù kèqi', 'đừng khách sáo', '不客气，这是我应该做的。', 'Bù kèqi, zhè shì wǒ yīnggāi zuò de.', 'Đừng khách sáo, đây là việc tôi nên làm.'),
(8, 1, 8, '不', 'bù', 'không', '我不喝茶。', 'Wǒ bù hē chá.', 'Tôi không uống trà.'),
(9, 1, 9, '菜', 'cài', 'món ăn, rau', '妈妈做的菜很好吃。', 'Māma zuò de cài hěn hǎochī.', 'Món ăn mẹ nấu rất ngon.'),
(10, 1, 10, '茶', 'chá', 'trà', '请喝一杯茶。', 'Qǐng hē yī bēi chá.', 'Mời uống một tách trà.'),
(11, 1, 11, '吃', 'chī', 'ăn', '你想吃什么？', 'Nǐ xiǎng chī shénme?', 'Bạn muốn ăn gì?'),
(12, 1, 12, '出租车', 'chūzūchē', 'xe taxi', '我们坐出租车去机场吧。', 'Wǒmen zuò chūzūchē qù jīchǎng ba.', 'Chúng ta đi taxi ra sân bay nhé.'),
(13, 1, 13, '打电话', 'dǎ diànhuà', 'gọi điện thoại', '他在给朋友打电话。', 'Tā zài gěi péngyou dǎ diànhuà.', 'Anh ấy đang gọi điện thoại cho bạn.'),
(14, 1, 14, '大', 'dà', 'to, lớn', '这个房间很大。', 'Zhège fángjiān hěn dà.', 'Căn phòng này rất lớn.'),
(15, 1, 15, '的', 'de', 'của (trợ từ kết cấu)', '这是我的书。', 'Zhè shì wǒ de shū.', 'Đây là sách của tôi.'),
(16, 1, 16, '点', 'diǎn', 'giờ, chút, điểm', '现在是下午三点。', 'Xiànzài shì xiàwǔ sān diǎn.', 'Bây giờ là ba giờ chiều.'),
(17, 1, 17, '电脑', 'diànnǎo', 'máy tính', '我买了一台新电脑。', 'Wǒ mǎi le yī tái xīn diànnǎo.', 'Tôi đã mua một chiếc máy tính mới.'),
(18, 1, 18, '电视', 'diànshì', 'ti vi, truyền hình', '爸爸在看电视。', 'Bàba zài kàn diànshì.', 'Bố đang xem ti vi.'),
(19, 1, 19, '电影', 'diànyǐng', 'phim điện ảnh', '我喜欢看中国电影。', 'Wǒ xǐhuan kàn Zhōngguó diànyǐng.', 'Tôi thích xem phim Trung Quốc.'),
(20, 1, 20, '东西', 'dōngxi', 'đồ đạc, thứ, vật', '我去商店买一点东西。', 'Wǒ qù shāngdiàn mǎi yīdiǎn dōngxi.', 'Tôi đi cửa hàng mua một ít đồ.'),
(21, 1, 21, '都', 'dōu', 'đều', '我们都是学生。', 'Wǒmen dōu shì xuésheng.', 'Chúng tôi đều là học sinh.'),
(22, 1, 22, '读', 'dú', 'đọc', '请读一下这个句子。', 'Qǐng dú yīxià zhège jùzi.', 'Xin hãy đọc một lượt câu này.'),
(23, 1, 23, '对不起', 'duìbuqǐ', 'xin lỗi', '对不起，我来晚了。', 'Duìbuqǐ, wǒ lái wǎn le.', 'Xin lỗi, tôi đến muộn.'),
(24, 1, 24, '多', 'duō', 'nhiều, bao nhiêu', '这里的人很多。', 'Zhèlǐ de rén hěn duō.', 'Người ở đây rất nhiều.'),
(25, 1, 25, '多少', 'duōshao', 'bao nhiêu', '这个杯子多少钱？', 'Zhège bēizi duōshao qián?', 'Chiếc cốc này bao nhiêu tiền?'),
(26, 1, 26, '儿子', 'érzi', 'con trai', '他的儿子今年五岁。', 'Tā de érzi jīnnián wǔ suì.', 'Con trai của anh ấy năm nay năm tuổi.'),
(27, 1, 27, '二', 'èr', 'số hai', '今天是二月二日。', 'Jīntiān shì èr yuè èr rì.', 'Hôm nay là ngày 2 tháng 2.'),
(28, 1, 28, '饭馆', 'fànguǎn', 'nhà hàng, quán ăn', '这家饭馆的菜很好吃。', 'Zhè jiā fànguǎn de cài hěn hǎochī.', 'Món ăn của quán này rất ngon.'),
(29, 1, 29, '飞机', 'fēijī', 'máy bay', '我明天坐飞机去北京。', 'Wǒ míngtiān zuò fēijī qù Běijīng.', 'Ngày mai tôi đi máy bay đến Bắc Kinh.'),
(30, 1, 30, '分钟', 'fēnzhōng', 'phút', '请等我五分钟。', 'Qǐng děng wǒ wǔ fēnzhōng.', 'Xin đợi tôi năm phút.'),
(31, 1, 31, '高兴', 'gāoxìng', 'vui vẻ, phấn khởi', '认识你我很高兴。', 'Rènshi nǐ wǒ hěn gāoxìng.', 'Rất vui được làm quen với bạn.'),
(32, 1, 32, '个', 'gè', 'cái, chiếc, người (lượng từ)', '我有一个姐姐。', 'Wǒ yǒu yī gè jiějie.', 'Tôi có một người chị gái.'),
(33, 1, 33, '工作', 'gōngzuò', 'công việc, làm việc', '他在医院工作。', 'Tā zài yīyuàn gōngzuò.', 'Anh ấy làm việc ở bệnh viện.'),
(34, 1, 34, '狗', 'gǒu', 'con chó', '这只小狗很可爱。', 'Zhè zhī xiǎogǒu hěn kě''ài.', 'Chú chó nhỏ này rất đáng yêu.'),
(35, 1, 35, '汉语', 'Hànyǔ', 'tiếng Hán, tiếng Trung', '他在学习汉语。', 'Tā zài xuéxí Hànyǔ.', 'Anh ấy đang học tiếng Trung.'),
(36, 1, 36, '好', 'hǎo', 'tốt, khỏe, được', '今天天气很好。', 'Jīntiān tiānqì hěn hǎo.', 'Hôm nay thời tiết rất tốt.'),
(37, 1, 37, '喝', 'hē', 'uống', '我想喝水。', 'Wǒ xiǎng hē shuǐ.', 'Tôi muốn uống nước.'),
(38, 1, 38, '和', 'hé', 'và, với', '我和他是好朋友。', 'Wǒ hé tā shì hǎo péngyou.', 'Tôi và anh ấy là bạn tốt.'),
(39, 1, 39, '很', 'hěn', 'rất', '她很漂亮。', 'Tā hěn piàoliang.', 'Cô ấy rất xinh đẹp.'),
(40, 1, 40, '后面', 'hòumiàn', 'phía sau, đằng sau', '学校后面有一个公园。', 'Xuéxiào hòumiàn yǒu yī gè gōngyuán.', 'Phía sau trường học có một công viên.'),
(41, 1, 41, '回', 'huí', 'về, quay về', '我下午六点回家。', 'Wǒ xiàwǔ liù diǎn huí jiā.', 'Tôi về nhà lúc sáu giờ chiều.'),
(42, 1, 42, '会', 'huì', 'biết (kỹ năng), sẽ', '我会说一点儿汉语。', 'Wǒ huì shuō yīdiǎnr Hànyǔ.', 'Tôi biết nói một chút tiếng Trung.'),
(43, 1, 43, '火车站', 'huǒchēzhàn', 'nhà ga tàu hỏa', '请问火车站在哪儿？', 'Qǐngwèn huǒchēzhàn zài nǎr?', 'Xin hỏi ga tàu hỏa ở đâu?'),
(44, 1, 44, '几', 'jǐ', 'mấy, vài', '你有几本书？', 'Nǐ yǒu jǐ běn shū?', 'Bạn có mấy quyển sách?'),
(45, 1, 45, '家', 'jiā', 'nhà, gia đình', '我家有四口人。', 'Wǒ jiā yǒu sì kǒu rén.', 'Nhà tôi có bốn người.'),
(46, 1, 46, '叫', 'jiào', 'gọi, tên là', '你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?'),
(47, 1, 47, '今天', 'jīntiān', 'hôm nay', '今天是星期一。', 'Jīntiān shì xīngqīyī.', 'Hôm nay là thứ Hai.'),
(48, 1, 48, '九', 'jiǔ', 'số chín', '他九点去上班。', 'Tā jiǔ diǎn qù shàngbān.', 'Anh ấy đi làm lúc chín giờ.'),
(49, 1, 49, '开', 'kāi', 'mở, lái (xe)', '爸爸会开车。', 'Bàba huì kāi chē.', 'Bố biết lái xe.'),
(50, 1, 50, '看', 'kàn', 'nhìn, xem, đọc', '我在看书。', 'Wǒ zài kàn shū.', 'Tôi đang đọc sách.'),
(51, 1, 51, '看见', 'kànjiàn', 'nhìn thấy', '我看见他在那儿。', 'Wǒ kànjiàn tā zài nàr.', 'Tôi nhìn thấy anh ấy ở đằng kia.'),
(52, 1, 52, '块', 'kuài', 'đồng (tiền), miếng, cục', '这本书二十块钱。', 'Zhè běn shū èrshí kuài qián.', 'Quyển sách này hai mươi đồng.'),
(53, 1, 53, '来', 'lái', 'đến, tới', '他明天来中国。', 'Tā míngtiān lái Zhōngguó.', 'Ngày mai anh ấy đến Trung Quốc.'),
(54, 1, 54, '老师', 'lǎoshī', 'giáo viên, thầy cô', '王老师教我们汉语。', 'Wáng lǎoshī jiāo wǒmen Hànyǔ.', 'Thầy Vương dạy chúng tôi tiếng Trung.'),
(55, 1, 55, '了', 'le', 'rồi (trợ từ)', '我买了一件衣服。', 'Wǒ mǎi le yī jiàn yīfu.', 'Tôi đã mua một bộ quần áo.'),
(56, 1, 56, '冷', 'lěng', 'lạnh', '今天天气很冷。', 'Jīntiān tiānqì hěn lěng.', 'Thời tiết hôm nay rất lạnh.'),
(57, 1, 57, '里', 'lǐ', 'trong, bên trong', '房间里有人吗？', 'Fángjiān lǐ yǒu rén ma?', 'Trong phòng có ai không?'),
(58, 1, 58, '零', 'líng', 'số không', '今年是二零二六年。', 'Jīnnián shì èr líng èr liù nián.', 'Năm nay là năm 2026.'),
(59, 1, 59, '六', 'liù', 'số sáu', '一个星期有六天工作吗？', 'Yī gè xīngqī yǒu liù tiān gōngzuò ma?', 'Một tuần có sáu ngày làm việc phải không?'),
(60, 1, 60, '妈妈', 'māma', 'mẹ, má', '我妈妈是医生。', 'Wǒ māma shì yīshēng.', 'Mẹ tôi là bác sĩ.'),
(61, 1, 61, '吗', 'ma', 'không, à (trợ từ nghi vấn)', '你是中国人吗？', 'Nǐ shì Zhōngguórén ma?', 'Bạn là người Trung Quốc phải không?'),
(62, 1, 62, '买', 'mǎi', 'mua', '我去超市买水果。', 'Wǒ qù chāoshì mǎi shuǐguǒ.', 'Tôi đi siêu thị mua hoa quả.'),
(63, 1, 63, '猫', 'māo', 'con mèo', '小猫在睡觉。', 'Xiǎomāo zài shuìjiào.', 'Mèo con đang ngủ.'),
(64, 1, 64, '没关系', 'méi guānxi', 'không sao đâu', '没关系，不用担心。', 'Méi guānxi, bùyòng dānxīn.', 'Không sao đâu, đừng lo lắng.'),
(65, 1, 65, '米饭', 'mǐfàn', 'cơm', '我喜欢吃米饭。', 'Wǒ xǐhuan chī mǐfàn.', 'Tôi thích ăn cơm.'),
(66, 1, 66, '明天', 'míngtiān', 'ngày mai', '明天我们去公园吧。', 'Míngtiān wǒmen qù gōngyuán ba.', 'Ngày mai chúng ta đi công viên nhé.'),
(67, 1, 67, '名字', 'míngzi', 'tên', '他的名字叫李明。', 'Tā de míngzi jiào Lǐ Míng.', 'Tên của anh ấy là Lý Minh.'),
(68, 1, 68, '哪', 'nǎ', 'nào', '你是哪国人？', 'Nǐ shì nǎ guó rén?', 'Bạn là người nước nào?'),
(69, 1, 69, '那', 'nà', 'kia, đó, vậy', '那个人是谁？', 'Nàge rén shì shéi?', 'Người kia là ai?'),
(70, 1, 70, '呢', 'ne', 'thế, nhỉ (trợ từ nghi vấn)', '我很好，你呢？', 'Wǒ hěn hǎo, nǐ ne?', 'Tôi rất khỏe, còn bạn thì sao?'),
(71, 1, 71, '能', 'néng', 'có thể', '你能帮我一下吗？', 'Nǐ néng bāng wǒ yīxià ma?', 'Bạn có thể giúp tôi một chút không?'),
(72, 1, 72, '你', 'nǐ', 'bạn, anh, chị', '你好！', 'Nǐ hǎo!', 'Xin chào bạn!'),
(73, 1, 73, '年', 'nián', 'năm', '我在中国住了三年。', 'Wǒ zài Zhōngguó zhù le sān nián.', 'Tôi đã sống ở Trung Quốc ba năm.'),
(74, 1, 74, '女儿', 'nǚ''ér', 'con gái', '王老师的女儿很漂亮。', 'Wáng lǎoshī de nǚ''ér hěn piàoliang.', 'Con gái của thầy Vương rất xinh đẹp.'),
(75, 1, 75, '朋友', 'péngyou', 'bạn bè', '他是我的好朋友。', 'Tā shì wǒ de hǎo péngyou.', 'Anh ấy là bạn tốt của tôi.'),
(76, 1, 76, '漂亮', 'piàoliang', 'xinh đẹp, đẹp', '这件衣服很漂亮。', 'Zhè jiàn yīfu hěn piàoliang.', 'Bộ quần áo này rất đẹp.'),
(77, 1, 77, '苹果', 'píngguǒ', 'quả táo', '我想吃一个苹果。', 'Wǒ xiǎng chī yī gè píngguǒ.', 'Tôi muốn ăn một quả táo.'),
(78, 1, 78, '七', 'qī', 'số bảy', '一个星期有七天。', 'Yī gè xīngqī yǒu qī tiān.', 'Một tuần có bảy ngày.'),
(79, 1, 79, '钱', 'qián', 'tiền', '这件衣服多少钱？', 'Zhè jiàn yīfu duōshao qián?', 'Bộ quần áo này bao nhiêu tiền?'),
(80, 1, 80, '前面', 'qiánmiàn', 'phía trước, đằng trước', '前面有一家银行。', 'Qiánmiàn yǒu yī jiā yínháng.', 'Phía trước có một ngân hàng.'),
(81, 1, 81, '请', 'qǐng', 'mời, xin', '请坐，请喝茶。', 'Qǐng zuò, qǐng hē chá.', 'Mời ngồi, mời uống trà.'),
(82, 1, 82, '去', 'qù', 'đi', '我明天去学校。', 'Wǒ míngtiān qù xuéxiào.', 'Ngày mai tôi đi đến trường.'),
(83, 1, 83, '热', 'rè', 'nóng', '今天天气太热了。', 'Jīntiān tiānqì tài rè le.', 'Thời tiết hôm nay nóng quá.'),
(84, 1, 84, '人', 'rén', 'người', '商店里有很多人。', 'Shāngdiàn lǐ yǒu hěn duō rén.', 'Trong cửa hàng có rất nhiều người.'),
(85, 1, 85, '认识', 'rènshi', 'quen biết', '我认识他三年了。', 'Wǒ rènshi tā sān nián le.', 'Tôi quen biết anh ấy ba năm rồi.'),
(86, 1, 86, '日', 'rì', 'ngày, mặt trời', '明天是五月一日。', 'Míngtiān shì wǔ yuè yī rì.', 'Ngày mai là ngày 1 tháng 5.'),
(87, 1, 87, '三', 'sān', 'số ba', '我有三本书。', 'Wǒ yǒu sān běn shū.', 'Tôi có ba quyển sách.'),
(88, 1, 88, '商店', 'shāngdiàn', 'cửa hàng, tiệm', '我去商店买东西。', 'Wǒ qù shāngdiàn mǎi dōngxi.', 'Tôi đi cửa hàng mua đồ.'),
(89, 1, 89, '上', 'shàng', 'trên, lên, đi (học/làm)', '书在桌子上。', 'Shū zài zhuōzi shàng.', 'Sách ở trên bàn.'),
(90, 1, 90, '上午', 'shàngwǔ', 'buổi sáng', '上午我在家看书。', 'Shàngwǔ wǒ zài jiā kàn shū.', 'Buổi sáng tôi ở nhà đọc sách.'),
(91, 1, 91, '少', 'shǎo', 'ít, thiếu', '杯子里的水很少。', 'Bēizi lǐ de shuǐ hěn shǎo.', 'Nước trong cốc rất ít.'),
(92, 1, 92, '谁', 'shéi', 'ai', '那个人是谁？', 'Nàge rén shì shéi?', 'Người kia là ai?'),
(93, 1, 93, '什么', 'shénme', 'cái gì, gì', '你在看什么？', 'Nǐ zài kàn shénme?', 'Bạn đang xem gì vậy?'),
(94, 1, 94, '十', 'shí', 'số mười', '现在是十点十分。', 'Xiànzài shì shí diǎn shí fēn.', 'Bây giờ là mười giờ mười phút.'),
(95, 1, 95, '时候', 'shíhou', 'lúc, khi, thời gian', '你什么时候回家？', 'Nǐ shénme shíhou huí jiā?', 'Khi nào bạn về nhà?'),
(96, 1, 96, '是', 'shì', 'là, phải, vâng', '我是越南人。', 'Wǒ shì Yuènánrén.', 'Tôi là người Việt Nam.'),
(97, 1, 97, '书', 'shū', 'sách', '我喜欢读这本书。', 'Wǒ xǐhuan dú zhè běn shū.', 'Tôi thích đọc quyển sách này.'),
(98, 1, 98, '水', 'shuǐ', 'nước', '请给我一杯水。', 'Qǐng gěi wǒ yī bēi shuǐ.', 'Làm ơn cho tôi một cốc nước.'),
(99, 1, 99, '水果', 'shuǐguǒ', 'hoa quả, trái cây', '多吃水果对身体好。', 'Duō chī shuǐguǒ duì shēntǐ hǎo.', 'Ăn nhiều hoa quả tốt cho sức khỏe.'),
(100, 1, 100, '睡觉', 'shuìjiào', 'ngủ', '我每天晚上十一点睡觉。', 'Wǒ měitiān wǎnshang shíyī diǎn shuìjiào.', 'Tôi đi ngủ lúc 11 giờ tối mỗi ngày.'),
(101, 1, 101, '说话', 'shuōhuà', 'nói chuyện', '他们在说话。', 'Tāmen zài shuōhuà.', 'Họ đang nói chuyện.'),
(102, 1, 102, '四', 'sì', 'số bốn', '一年有四个季节。', 'Yī nián yǒu sì gè jìjié.', 'Một năm có bốn mùa.'),
(103, 1, 103, '岁', 'suì', 'tuổi', '你今年多大岁数？我二十岁。', 'Nǐ jīnnián duō dà suìshu? Wǒ èrshí suì.', 'Năm nay bạn bao nhiêu tuổi? Tôi hai mươi tuổi.'),
(104, 1, 104, '他', 'tā', 'anh ấy, ông ấy', '他是我的同学。', 'Tā shì wǒ de tóngxué.', 'Anh ấy là bạn học của tôi.'),
(105, 1, 105, '她', 'tā', 'cô ấy, bà ấy', '她是我的汉语老师。', 'Tā shì wǒ de Hànyǔ lǎoshī.', 'Cô ấy là giáo viên tiếng Trung của tôi.'),
(106, 1, 106, '太', 'tài', 'quá, lắm', '这个苹果太大了。', 'Zhège píngguǒ tài dà le.', 'Quả táo này to quá.'),
(107, 1, 107, '天气', 'tiānqì', 'thời tiết', '今天的天气真好。', 'Jīntiān de tiānqì zhēn hǎo.', 'Thời tiết hôm nay thật đẹp.'),
(108, 1, 108, '听', 'tīng', 'nghe', '我喜欢听音乐。', 'Wǒ xǐhuan tīng yīnyuè.', 'Tôi thích nghe nhạc.'),
(109, 1, 109, '同学', 'tóngxué', 'bạn học', '同学们都在教室里。', 'Tóngxuémen dōu zài jiàoshì lǐ.', 'Các bạn học đều ở trong lớp học.'),
(110, 1, 110, '喂', 'wèi', 'a lô, này', '喂，请问王老师在吗？', 'Wèi, qǐngwèn Wáng lǎoshī zài ma?', 'A lô, xin hỏi có thầy Vương ở đó không?'),
(111, 1, 111, '我', 'wǒ', 'tôi, mình', '我是一个学生。', 'Wǒ shì yī gè xuésheng.', 'Tôi là một học sinh.'),
(112, 1, 112, '我们', 'wǒmen', 'chúng tôi, chúng ta', '我们一起去吃饭吧。', 'Wǒmen yīqǐ qù chīfàn ba.', 'Chúng ta cùng đi ăn cơm nhé.'),
(113, 1, 113, '五', 'wǔ', 'số năm', '我有五个好朋友。', 'Wǒ yǒu wǔ gè hǎo péngyou.', 'Tôi có năm người bạn tốt.'),
(114, 1, 114, '喜欢', 'xǐhuan', 'thích', '你喜欢喝咖啡吗？', 'Nǐ xǐhuan hē kāfēi ma?', 'Bạn có thích uống cà phê không?'),
(115, 1, 115, '下', 'xià', 'dưới, xuống, sau', '小猫在桌子下。', 'Xiǎomāo zài zhuōzi xià.', 'Con mèo nhỏ ở dưới gầm bàn.'),
(116, 1, 116, '下午', 'xiàwǔ', 'buổi chiều', '今天下午我有课。', 'Jīntiān xiàwǔ wǒ yǒu kè.', 'Chiều nay tôi có tiết học.'),
(117, 1, 117, '下雨', 'xià yǔ', 'mưa, trời mưa', '外面下雨了。', 'Wàimiàn xià yǔ le.', 'Bên ngoài trời mưa rồi.'),
(118, 1, 118, '先生', 'xiānsheng', 'ông, ngài, chồng', '李先生在办公室吗？', 'Lǐ xiānsheng zài bàngōngshì ma?', 'Ông Lý có ở trong văn phòng không?'),
(119, 1, 119, '现在', 'xiànzài', 'bây giờ, hiện tại', '现在几点了？', 'Xiànzài jǐ diǎn le?', 'Bây giờ là mấy giờ rồi?'),
(120, 1, 120, '想', 'xiǎng', 'muốn, nhớ, nghĩ', '我想去北京旅游。', 'Wǒ xiǎng qù Běijīng lǚyóu.', 'Tôi muốn đi Bắc Kinh du lịch.'),
(121, 1, 121, '小', 'xiǎo', 'nhỏ, bé', '这件衣服太小了。', 'Zhè jiàn yīfu tài xiǎo le.', 'Bộ quần áo này nhỏ quá.'),
(122, 1, 122, '小姐', 'xiǎojiě', 'cô, tiểu thư', '王小姐，里面请。', 'Wáng xiǎojiě, lǐmiàn qǐng.', 'Cô Vương, mời vào bên trong.'),
(123, 1, 123, '些', 'xiē', 'một ít, một vài', '我买了一些水果。', 'Wǒ mǎi le yīxiē shuǐguǒ.', 'Tôi đã mua một ít hoa quả.'),
(124, 1, 124, '写', 'xiě', 'viết', '你会写这个汉字吗？', 'Nǐ huì xiě zhège Hànzì ma?', 'Bạn có biết viết chữ Hán này không?'),
(125, 1, 125, '谢谢', 'xièxie', 'cảm ơn', '谢谢你的帮助。', 'Xièxie nǐ de bāngzhù.', 'Cảm ơn sự giúp đỡ của bạn.'),
(126, 1, 126, '星期', 'xīngqī', 'tuần, thứ', '今天是星期六。', 'Jīntiān shì xīngqīliù.', 'Hôm nay là thứ Bảy.'),
(127, 1, 127, '学生', 'xuésheng', 'học sinh, sinh viên', '那所学校有很多学生。', 'Nà suǒ xuéxiào yǒu hěn duō xuésheng.', 'Ngôi trường đó có rất nhiều học sinh.'),
(128, 1, 128, '学习', 'xuéxí', 'học, học tập', '我们每天都学习汉语。', 'Wǒmen měitiān dōu xuéxí Hànyǔ.', 'Chúng tôi học tiếng Trung mỗi ngày.'),
(129, 1, 129, '学校', 'xuéxiào', 'trường học', '我们的学校很大。', 'Wǒmen de xuéxiào hěn dà.', 'Trường học của chúng tôi rất lớn.'),
(130, 1, 130, '一', 'yī', 'số một', '请给我一杯茶。', 'Qǐng gěi wǒ yī bēi chá.', 'Làm ơn cho tôi một cốc trà.'),
(131, 1, 131, '衣服', 'yīfu', 'quần áo', '妈妈在洗衣服。', 'Māma zài xǐ yīfu.', 'Mẹ đang giặt quần áo.'),
(132, 1, 132, '医生', 'yīshēng', 'bác sĩ', '他在医院当医生。', 'Tā zài yīyuàn dāng yīshēng.', 'Anh ấy làm bác sĩ ở bệnh viện.'),
(133, 1, 133, '医院', 'yīyuàn', 'bệnh viện', '医院离这儿不远。', 'Yīyuàn lí zhèr bù yuǎn.', 'Bệnh viện cách đây không xa.'),
(134, 1, 134, '椅子', 'yǐzi', 'cái ghế', '房间里有四把椅子。', 'Fángjiān lǐ yǒu sì bǎ yǐzi.', 'Trong phòng có bốn chiếc ghế.'),
(135, 1, 135, '一点儿', 'yīdiǎnr', 'một chút, một ít', '我会说一点儿汉语。', 'Wǒ huì shuō yīdiǎnr Hànyǔ.', 'Tôi biết nói một chút tiếng Trung.'),
(136, 1, 136, '有', 'yǒu', 'có', '我有一个弟弟。', 'Wǒ yǒu yī gè dìdi.', 'Tôi có một người em trai.'),
(137, 1, 137, '月', 'yuè', 'tháng, mặt trăng', '一年有十二个月。', 'Yī nián yǒu shí''èr gè yuè.', 'Một năm có mười hai tháng.'),
(138, 1, 138, '在', 'zài', 'ở, tại, đang', '爸爸在家休息。', 'Bàba zài jiā xiūxi.', 'Bố đang nghỉ ngơi ở nhà.'),
(139, 1, 139, '再见', 'zàijiàn', 'tạm biệt', '明天见，再见！', 'Míngtiān jiàn, zàijiàn!', 'Hẹn gặp lại ngày mai, tạm biệt!'),
(140, 1, 140, '怎么', 'zěnme', 'thế nào, làm sao', '这个字怎么读？', 'Zhège zì zěnme dú?', 'Chữ này đọc thế nào?'),
(141, 1, 141, '怎么样', 'zěnmeyàng', 'như thế nào', '今天天气怎么样？', 'Jīntiān tiānqì zěnmeyàng?', 'Thời tiết hôm nay như thế nào?'),
(142, 1, 142, '这', 'zhè', 'này, đây', '这是我的老师。', 'Zhè shì wǒ de lǎoshī.', 'Đây là thầy giáo của tôi.'),
(143, 1, 143, '中国', 'Zhōngguó', 'Trung Quốc', '我想去中国留学。', 'Wǒ xiǎng qù Zhōngguó liúxué.', 'Tôi muốn đi du học Trung Quốc.'),
(144, 1, 144, '中午', 'zhōngwǔ', 'buổi trưa', '中午你吃什么？', 'Zhōngwǔ nǐ chī shénme?', 'Buổi trưa bạn ăn gì?'),
(145, 1, 145, '住', 'zhù', 'ở, cư trú', '他住在北京。', 'Tā zhù zài Běijīng.', 'Anh ấy sống ở Bắc Kinh.'),
(146, 1, 146, '桌子', 'zhuōzi', 'cái bàn', '桌子上有一台电脑。', 'Zhuōzi shàng yǒu yī tái diànnǎo.', 'Trên bàn có một chiếc máy tính.'),
(147, 1, 147, '字', 'zì', 'chữ', '这个汉字很容易写。', 'Zhège Hànzì hěn róngyì xiě.', 'Chữ Hán này rất dễ viết.'),
(148, 1, 148, '昨天', 'zuótiān', 'hôm qua', '昨天我去商店了。', 'Zuótiān wǒ qù shāngdiàn le.', 'Hôm qua tôi đã đi cửa hàng.'),
(149, 1, 149, '坐', 'zuò', 'ngồi, đi (bằng phương tiện)', '请坐在这儿。', 'Qǐng zuò zài zhèr.', 'Mời ngồi ở đây.'),
(150, 1, 150, '做', 'zuò', 'làm, nấu', '妈妈在做晚饭。', 'Māma zài zuò wǎnfàn.', 'Mẹ đang nấu bữa tối.'),
(151, 2, 1, '吧', 'ba', 'đi, nhé, nhỉ (đứng cuối câu)', '请你帮我吧。', 'Qǐng nǐ bāng wǒ ba.', 'Xin bạn giúp tôi nhé.'),
(152, 2, 2, '白', 'bái', 'trắng', '他的白色衬衫很漂亮。', 'Tā de báisè chènshān hěn piàoliang.', 'Áo sơ mi trắng của anh ấy rất đẹp.'),
(153, 2, 3, '百', 'bǎi', 'trăm', '我们要买一百个苹果。', 'Wǒmen yào mǎi yī bǎi gè píngguǒ.', 'Chúng tôi muốn mua một trăm quả táo.'),
(154, 2, 4, '帮助', 'bāngzhù', 'giúp đỡ', '谢谢你的帮助。', 'Xièxie nǐ de bāngzhù.', 'Cảm ơn sự giúp đỡ của bạn.'),
(155, 2, 5, '报纸', 'bàozhǐ', 'báo', '我每天都看报纸。', 'Wǒ měitiān dōu kàn bàozhǐ.', 'Tôi đọc báo mỗi ngày.'),
(156, 2, 6, '比', 'bǐ', 'so sánh', '我的家比你的家大。', 'Wǒ de jiā bǐ nǐ de jiā dà.', 'Nhà của tôi lớn hơn nhà của bạn.'),
