(166, 2, 16, '打篮球', 'dǎ lánqiú', 'chơi bóng rổ', '他打篮球打得很好。', 'Tā dǎ lánqiú dǎ de hěn hǎo.', 'Anh ấy chơi bóng rổ rất giỏi.'),
(167, 2, 17, '大家', 'dàjiā', 'mọi người', '大家都很高兴。', 'Dàjiā dōu hěn gāoxìng.', 'Mọi người đều rất vui.'),
