(173, 2, 23, '第一', 'dì yī', 'đầu tiên', '他是第一名。', 'Tā shì dì yī míng.', 'Anh ấy là người đứng đầu.'),
(174, 2, 24, '懂', 'dǒng', 'hiểu', '我不懂这个问题。', 'Wǒ bù dǒng zhège wèntí.', 'Tôi không hiểu vấn đề này.'),
(175, 2, 25, '对', 'duì', 'đúng, đối với', '你对我很好。', 'Nǐ duì wǒ hěn hǎo.', 'Bạn đối xử tốt với tôi.'),
(176, 2, 26, '房间', 'fángjiān', 'phòng', '房间里很安静。', 'Fángjiān lǐ hěn ānjìng.', 'Trong phòng rất yên tĩnh.'),
(177, 2, 27, '非常', 'fēicháng', 'rất, cực kỳ', '这道菜非常好吃。', 'Zhè dào cài fēicháng hǎochī.', 'Món ăn này rất ngon.'),
(178, 2, 28, '服务员', 'fúwùyuán', 'nhân viên phục vụ', '服务员请帮忙。', 'Fúwùyuán qǐng bāngmáng.', 'Nhân viên phục vụ, xin giúp đỡ.'),
(179, 2, 29, '高', 'gāo', 'cao', '他很高。', 'Tā hěn gāo.', 'Anh ấy rất cao.'),
(180, 2, 30, '告诉', 'gàosù', 'nói cho, thông báo', '请告诉我答案。', 'Qǐng gàosù wǒ dá''àn.', 'Xin cho tôi biết đáp án.'),
(181, 2, 31, '哥哥', 'gēge', 'anh trai', '哥哥在家里。', 'Gēge zài jiālǐ.', 'Anh trai đang ở nhà.'),
