(184, 2, 34, '公斤', 'gōngjīn', 'kilogram (kg)', '这个包十公斤。', 'Zhège bāo shí gōngjīn.', 'Cái túi này mười kilogram.'),
(185, 2, 35, '公司', 'gōngsī', 'công ty', '我在公司工作。', 'Wǒ zài gōngsī gōngzuò.', 'Tôi làm việc ở công ty.'),
(186, 2, 36, '贵', 'guì', 'đắt, quý', '这件衣服很贵。', 'Zhè jiàn yīfú hěn guì.', 'Cái áo này rất đắt.'),
(187, 2, 37, '过', 'guò', 'qua, đi qua', '请过安检门。', 'Qǐng guò ānjiǎn mén.\\', 'Mời đi qua cửa an ninh.'),
(188, 2, 38, '还', 'hái', 'vẫn, còn', '我还想要一杯水。', 'Wǒ hái xiǎng yào yī bēi shuǐ.', 'Tôi còn muốn một cốc nước.'),
(189, 2, 39, '孩子', 'háizi', 'trẻ con', '孩子们都在玩。', 'Háizimen dōu zài wán.', 'Những đứa trẻ đang chơi.'),
(190, 2, 40, '好吃', 'hǎochī', 'ngon', '这道菜很好吃。', 'Zhè dào cài hěn hǎo chī.', 'Món ăn này rất ngon.'),
(191, 2, 41, '号', 'hào', 'số (như số điện thoại, số nhà)', '你的手机号是多少？', 'Nǐ de shǒujī hào shì duōshǎo?', 'Số điện thoại của bạn là bao nhiêu?'),
(192, 2, 42, '黑', 'hēi', 'đen', '我的车是黑色的。', 'Wǒ de chē shì hēisè de.', 'Xe của tôi màu đen.'),
(193, 2, 43, '红', 'hóng', 'đỏ', '她喜欢红色的衣服。', 'Tā xǐhuān hóngsè de yīfú.', 'Cô ấy thích quần áo màu đỏ.'),
