(195, 2, 45, '回答', 'huídá', 'trả lời', '请回答我的问题。', 'Qǐng huídá wǒ de wèntí.', 'Xin trả lời câu hỏi của tôi.'),
(196, 2, 46, '机场', 'jīchǎng', 'sân bay', '机场离这里很近。', 'Jīchǎng lí zhèlǐ hěn jìn.', 'Sân bay gần đây.'),
(197, 2, 47, '鸡蛋', 'jīdàn', 'trứng gà', '我喜欢吃鸡蛋。', 'Wǒ xǐhuān chī jīdàn.', 'Tôi thích ăn trứng.'),
(198, 2, 48, '件', 'jiàn', 'cái (dùng cho sự việc, quần áo)', '这件衣服很好看。', 'Zhè jiàn yīfú hěn hǎokàn.', 'Cái áo này rất đẹp.'),
(199, 2, 49, '教室', 'jiàoshì', 'lớp học', '学生们在教室里学习。', 'Xuéshēngmen zài jiàoshì lǐ xuéxí.', 'Học sinh đang học trong lớp học.'),
(200, 2, 50, '姐姐', 'jiějie', 'chị gái', '姐姐比我大三岁。', 'Jiějie bǐ wǒ dà sān suì.', 'Chị gái lớn hơn tôi ba tuổi.'),
