(498, 3, 198, '瘦', 'shòu', 'gầy', '我觉得他越来越瘦了。', 'Wǒ juéde tā yuè lái yuè shòu le.', 'Tôi cảm thấy anh ấy ngày càng gầy.'),
(499, 3, 199, '舒服', 'shūfu', 'thoải mái', '这张椅子很舒服。', 'Zhè zhāng yǐzi hěn shūfu.', 'Cái ghế này rất thoải mái.'),
(500, 3, 200, '叔叔', 'shūshu', 'chú', '我的叔叔很高。', 'Wǒ de shūshu hěn gāo.', 'Chú của tôi rất cao.');
INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(501, 3, 201, '树', 'shù', 'cây', '树上的鸟在唱歌。', 'Shù shàng de niǎo zài chànggē.', 'Con chim trên cây đang hót.'),
(502, 3, 202, '数学', 'shùxué', 'toán học', '他数学很好。', 'Tā shùxué hěn hǎo.', 'Anh ấy giỏi toán.'),
(503, 3, 203, '刷牙', 'shuāyá', 'đánh răng', '我每天刷两次牙。', 'Wǒ měitiān shuā liǎng cì yá .', 'Tôi đánh răng hai lần mỗi ngày.'),
(504, 3, 204, '双', 'shuāng', 'đôi', '我买了一双鞋。', 'Wǒ mǎi le yī shuāng xié.', 'Tôi đã mua một đôi giày.'),
(505, 3, 205, '水平', 'shuǐpíng', 'trình độ', '他的游泳水平很高。', 'Tā de yóuyǒng shuǐpíng hěn gāo.', 'Trình độ bơi của anh ấy rất cao.'),
(506, 3, 206, '司机', 'sījī', 'lái xe, tài xế', '他是我们的司机。', 'Tā shì wǒmen de sījī.', 'Anh ấy là tài xế của chúng tôi.'),
(507, 3, 207, '虽然', 'suīrán', 'tuy rằng', '虽然他很忙，但他还是来了。', 'Suīrán tā hěn máng, dàn tā háishì lái le.', 'Mặc dù anh ấy rất bận, nhưng anh ấy vẫn đến.'),
(508, 3, 208, '太阳', 'tàiyáng', 'mặt trời', '太阳出来了。', 'Tàiyáng chū lái le.', 'Mặt trời đã mọc.'),
(509, 3, 209, '糖', 'táng', 'kẹo, đường', '我不喜欢吃糖。', 'Wǒ bù xǐhuān chī táng.', 'Tôi không thích ăn kẹo.'),
(510, 3, 210, '特别', 'tèbié', 'đặc biệt', '他特别喜欢跑步。', 'Tā tèbié xǐhuān pǎobù.', 'Anh ấy đặc biệt thích chạy bộ.'),
(511, 3, 211, '疼', 'téng', 'đau', '我的头很疼。', 'Wǒ de tóu hěn téng.', 'Đầu tôi rất đau.'),
(512, 3, 212, '提高', 'tígāo', 'nâng cao', '我们要提高汉语水平。', 'Wǒmen yào tígāo hànyǔ shuǐpíng.', 'Chúng ta cần nâng cao trình độ tiếng Trung.'),
(513, 3, 213, '体育', 'tǐyù', 'thể dục, thể thao', '我喜欢体育运动。', 'Wǒ xǐhuān tǐyù yùndòng.', 'Tôi thích các hoạt động thể thao.'),
(514, 3, 214, '甜', 'tián', 'ngọt', '这个蛋糕很甜。', 'Zhège dàngāo hěn tián.', 'Cái bánh này rất ngọt.'),
(515, 3, 215, '条', 'tiáo', 'sợi, cái', '他买了一条裤子。', 'Tā mǎi le yī tiáo kùzi.', 'Anh ấy đã mua một chiếc quần.'),
(516, 3, 216, '同事', 'tóngshì', 'đồng nghiệp', '他是我的同事。', 'Tā shì wǒ de tóngshì.', 'Anh ấy là đồng nghiệp của tôi.'),
(517, 3, 217, '同意', 'tóngyì', 'đồng ý', '我同意你的看法。', 'Wǒ tóngyì nǐ de kànfǎ.', 'Tôi đồng ý với quan điểm của bạn.'),
(518, 3, 218, '头发', 'tóufa', 'tóc', '她的头发很长。', 'Tā de tóufa hěn cháng.', 'Tóc của cô ấy rất dài.'),
(519, 3, 219, '突然', 'tūrán', 'đột nhiên', '他突然离开了。', 'Tā tūrán líkāi le.', 'Anh ấy đột nhiên rời đi.'),
(520, 3, 220, '图书馆', 'túshūguǎn', 'thư viện', '我们去图书馆看书吧。', 'Wǒmen qù túshūguǎn kànshū ba.', 'Chúng ta đến thư viện đọc sách nhé.'),
(521, 3, 221, '腿', 'tuǐ', 'chân', '他的腿很长。', 'Tā de tuǐ hěn cháng.', 'Chân của anh ấy rất dài.'),
(522, 3, 222, '完成', 'wánchéng', 'hoàn thành', '我完成了作业。', 'Wǒ wánchéng le zuòyè.', 'Tôi đã hoàn thành bài tập.'),
(523, 3, 223, '碗', 'wǎn', 'bát', '他吃了三碗饭。', 'Tā chī le sān wǎn fàn.', 'Anh ấy đã ăn ba bát cơm.'),
(524, 3, 224, '万', 'wàn', 'vạn, mười nghìn', '一万个人参加了比赛。', 'Yī wàn gè rén cānjiā le bǐsài.', 'Mười nghìn người đã tham gia cuộc thi.'),
(525, 3, 225, '忘记', 'wàngjì', 'quên', '请不要忘记带书。', 'Qǐng bùyào wàngjì dài shū.', 'Vui lòng đừng quên mang sách.'),
(526, 3, 226, '位', 'wèi', 'vị, ngài', '请坐在这位先生旁边。', 'Qǐng zuò zài zhè wèi xiānshēng pángbiān.', 'Xin ngồi bên cạnh ông này.'),
(527, 3, 227, '为', 'wèi', 'vì', '我为你感到骄傲。', 'Wǒ wèi nǐ gǎndào jiāo''ào.', 'Tôi tự hào về bạn.'),
(528, 3, 228, '为了', 'wèile', 'để, vì', '我来中国是为了学习汉语。', 'Wǒ lái Zhōngguó shì wèile xuéxí hànyǔ .', 'Tôi đến Trung Quốc để học tiếng Trung.'),
(529, 3, 229, '文化', 'wénhuà', 'văn hóa', '他对中国文化很感兴趣。', 'Tā duì Zhōngguó wénhuà hěn gǎn xìngqù.', 'Anh ấy rất quan tâm đến văn hóa Trung Quốc.'),
(530, 3, 230, '西', 'xī', 'phía tây', '我住在西边。', 'Wǒ zhù zài xībiān.', 'Tôi sống ở phía tây.'),
(531, 3, 231, '习惯', 'xíguàn', 'thói quen', '他习惯早起。', 'Tā xíguàn zǎoqǐ.', 'Anh ấy quen dậy sớm.'),
(532, 3, 232, '洗手间', 'xǐshǒujiān', 'nhà vệ sinh', '洗手间在那边。', 'Xǐshǒujiān zài nà biān.', 'Nhà vệ sinh ở đằng kia.'),
(533, 3, 233, '洗澡', 'xǐzǎo', 'tắm', '我每天早上都洗澡。', 'Wǒ měitiān zǎoshang dōu xǐzǎo.', 'Tôi đều tắm vào mỗi buổi sáng.'),
(534, 3, 234, '喜欢', 'xǐhuān', 'thích', '我喜欢这个颜色。', 'Wǒ xǐhuān zhège yánsè.', 'Tôi thích màu này.'),
(535, 3, 235, '现在', 'xiànzài', 'hiện tại', '现在是八点。', 'Xiànzài shì bā diǎn.', 'Bây giờ là tám giờ.'),
(536, 3, 236, '香蕉', 'xiāngjiāo', 'chuối', '香蕉是黄色的。', 'Xiāngjiāo shì huángsè de.', 'Chuối có màu vàng.'),
(537, 3, 237, '相同', 'xiāngtóng', 'giống nhau', '我们的看法相同。', 'Wǒmen de kànfǎ xiāngtóng.', 'Quan điểm của chúng tôi giống nhau.'),
(538, 3, 238, '相信', 'xiāngxìn', 'tin tưởng', '我相信他的话。', 'Wǒ xiāngxìn tā de huà.', 'Tôi tin lời anh ấy.'),
(539, 3, 239, '像', 'xiàng', 'giống', '他像他爸爸一样高。', 'Tā xiàng tā bàba yīyàng gāo.', 'Anh ấy cao giống như bố của mình.'),
(540, 3, 240, '小心', 'xiǎoxīn', 'cẩn thận', '请小心地走路。', 'Qǐng xiǎoxīn de zǒulù.', 'Vui lòng đi bộ cẩn thận.'),
(541, 3, 241, '校长', 'xiàozhǎng', 'hiệu trưởng', '校长在办公室工作。', 'Xiàozhǎng zài bàngōngshì gōngzuò.', 'Hiệu trưởng làm việc trong văn phòng.'),
(542, 3, 242, '鞋', 'xié', 'giày', '我买了一双新鞋。', 'Wǒ mǎi le yī shuāng xīn xié.', 'Tôi đã mua một đôi giày mới.'),
(543, 3, 243, '新闻', 'xīnwén', 'tin tức', '我每天都看新闻。', 'Wǒ měitiān dōu kàn xīnwén.', 'Tôi xem tin tức mỗi ngày.'),
(544, 3, 244, '新鲜', 'xīnxiān', 'tươi mới', '这些水果很新鲜。', 'Zhèxiē shuǐguǒ hěn xīnxiān.', 'Những loại trái cây này rất tươi.'),
(545, 3, 245, '信', 'xìn', 'thư, tin tưởng', '我给你写了一封信。', 'Wǒ gěi nǐ xiě le yī fēng xìn.', 'Tôi đã viết cho bạn một bức thư.'),
(546, 3, 246, '行李箱', 'xínglǐxiāng', 'vali', '我的行李箱很重。', 'Wǒ de xínglǐxiāng hěn zhòng.', 'Vali của tôi rất nặng.'),
(547, 3, 247, '兴趣', 'xìngqù', 'hứng thú', '我对中国文化有兴趣。', 'Wǒ duì Zhōngguó wénhuà yǒu xìngqù.', 'Tôi có hứng thú với văn hóa Trung Quốc.'),
(548, 3, 248, '熊猫', 'xióngmāo', 'gấu trúc', '熊猫是中国的国宝。', 'Xióngmāo shì Zhōngguó de guóbǎo.', 'Gấu trúc là báu vật quốc gia của Trung Quốc.'),
(549, 3, 249, '需要', 'xūyào', 'cần', '我需要一杯水。', 'Wǒ xūyào yī bēi shuǐ.', 'Tôi cần một cốc nước.'),
(550, 3, 250, '选择', 'xuǎnzé', 'lựa chọn', '你可以选择一个礼物。', 'Nǐ kěyǐ xuǎnzé yī gè lǐwù.', 'Bạn có thể chọn một món quà.'),
(551, 3, 251, '眼镜', 'yǎnjìng', 'kính', '他戴着一副眼镜。', 'Tā dài zhe yī fù yǎnjìng.', 'Anh ấy đang đeo một chiếc kính.'),
(552, 3, 252, '要求', 'yāoqiú', 'yêu cầu', '老师对学生有很高的要求。', 'Lǎoshī duì xuéshēng yǒu hěn gāo de yāoqiú.', 'Giáo viên có yêu cầu rất cao đối với học sinh.'),
(553, 3, 253, '爷爷', 'yéye', 'ông nội', '我爷爷很喜欢看书。', 'Wǒ yéye hěn xǐhuān kàn shū.', 'Ông của tôi rất thích đọc sách.'),
(554, 3, 254, '一定', 'yīdìng', 'nhất định', '我一定会努力学习。', 'Wǒ yídìng huì nǔlì xuéxí.', 'Tôi chắc chắn sẽ học chăm chỉ.'),
(555, 3, 255, '一共', 'yīgòng', 'tổng cộng', '我们一共有五个人。', 'Wǒmen yígòng yǒu wǔ gè rén.', 'Chúng tôi có tổng cộng năm người.'),
(556, 3, 256, '一会儿', 'yīhuìr', 'một lát', '请等我一会儿。', 'Qǐng děng wǒ yíhuìr.', 'Xin hãy đợi tôi một lát.'),
(557, 3, 257, '一样', 'yīyàng', 'giống nhau', '他们和我们一样高。', 'Tāmen hé wǒmen yīyàng gāo.', 'Họ cao bằng chúng tôi.'),
(558, 3, 258, '以后', 'yǐhòu', 'sau này', '我以后再来。', 'Wǒ yǐhòu zài lái.', 'Tôi sẽ đến sau.'),
(559, 3, 259, '以前', 'yǐqián', 'trước đây', '我以前住在北京。', 'Wǒ yǐqián zhù zài Běijīng.', 'Tôi đã từng sống ở Bắc Kinh.'),
(560, 3, 260, '以为', 'yǐwéi', 'cho rằng', '我以为你不来了。', 'Wǒ yǐwéi nǐ bù lái le.', 'Tôi tưởng rằng bạn không đến.'),
(561, 3, 261, '一般', 'yībān', 'thông thường', '这个饭馆很一般。', 'Zhège fànguǎn hěn yībān.', 'Nhà hàng này rất bình thường.'),
(562, 3, 262, '一边', 'yībiān', 'vừa ... vừa ...', '他一边吃饭一边看电视。', 'Tā yìbiān chīfàn yìbiān kàn diànshì.', 'Anh ấy vừa ăn vừa xem TV.'),
(563, 3, 263, '一直', 'yīzhí', 'luôn luôn', '他一直在学习。', 'Tā yìzhí zài xuéxí.', 'Anh ấy luôn luôn học tập.'),
(564, 3, 264, '音乐', 'yīnyuè', 'âm nhạc', '我喜欢听音乐。', 'Wǒ xǐhuān tīng yīnyuè.', 'Tôi thích nghe nhạc.'),
(565, 3, 265, '银行', 'yínháng', 'ngân hàng', '我去银行取钱。', 'Wǒ qù yínháng qǔ qián.', 'Tôi đến ngân hàng rút tiền.'),
(566, 3, 266, '应该', 'yīnggāi', 'nên', '你应该多休息。', 'Nǐ yīnggāi duō xiūxí.', 'Bạn nên nghỉ ngơi nhiều hơn.'),
(567, 3, 267, '影响', 'yǐngxiǎng', 'ảnh hưởng', '这个电影对我影响很大。', 'Zhège diànyǐng duì wǒ yǐngxiǎng hěn dà.', 'Bộ phim này có ảnh hưởng lớn đối với tôi.'),
(568, 3, 268, '用', 'yòng', 'dùng', '请不要用手机。', 'Qǐng bùyào yòng shǒujī.', 'Vui lòng không sử dụng điện thoại.'),
(569, 3, 269, '游戏', 'yóuxì', 'trò chơi', '我喜欢玩游戏。', 'Wǒ xǐhuān wán yóuxì.', 'Tôi thích chơi trò chơi.'),
(570, 3, 270, '又', 'yòu', 'lại, vừa', '他又来了。', 'Tā yòu lái le.', 'Anh ấy lại đến.'),
(571, 3, 271, '有名', 'yǒumíng', 'nổi tiếng', '他是一个有名的歌手。', 'Tā shì yī gè yǒumíng de gēshǒu.', 'Anh ấy là một ca sĩ nổi tiếng.'),
(572, 3, 272, '遇到', 'yùdào', 'gặp phải', '我在路上遇到他了。', 'Wǒ zài lùshàng yùdào tā le.', 'Tôi đã gặp anh ấy trên đường.'),
(573, 3, 273, '月亮', 'yuèliàng', 'mặt trăng', '今天晚上的月亮很圆。', 'Jīntiān wǎnshang de yuèliàng hěn yuán.', 'Trăng tối nay rất tròn.'),
(574, 3, 274, '云', 'yún', 'mây', '天上的云很美。', 'Tiānshàng de yún hěn měi.', 'Mây trên trời rất đẹp.'),
(575, 3, 275, '站', 'zhàn', 'đứng, trạm', '请站在这儿。', 'Qǐng zhàn zài zhèr.', 'Xin hãy đứng ở đây.'),
(576, 3, 276, '长', 'zhǎng', 'dài', '他长得很高。', 'Tā zhǎng de hěn gāo.', 'Anh ấy cao.'),
(577, 3, 277, '着急', 'zhāojí', 'lo lắng', '他很着急。', 'Tā hěn zhāojí.', 'Anh ấy rất lo lắng.'),
(578, 3, 278, '照顾', 'zhàogu', 'chăm sóc', '我会照顾你。', 'Wǒ huì zhàogu nǐ.', 'Tôi sẽ chăm sóc bạn.'),
(579, 3, 279, '照片', 'zhàopiàn', 'bức ảnh', '这张照片很好看。', 'Zhè zhāng zhàopiàn hěn hǎokàn.', 'Bức ảnh này rất đẹp.'),
(580, 3, 280, '照相机', 'zhàoxiàngjī', 'máy ảnh', '我有一台新的照相机。', 'Wǒ yǒu yī tái xīn de zhàoxiàngjī.', 'Tôi có một chiếc máy ảnh mới.'),
(581, 3, 281, '只', 'zhǐ', 'chỉ', '我只吃了一点儿。', 'Wǒ zhǐ chī le yīdiǎnr.', 'Tôi chỉ ăn một chút.'),
(582, 3, 282, '中间', 'zhōngjiān', 'ở giữa', '他站在房间的中间。', 'Tā zhàn zài fángjiān de zhōngjiān.', 'Anh ấy đứng ở giữa phòng.'),
(583, 3, 283, '终于', 'zhōngyú', 'cuối cùng', '我终于完成了作业。', 'Wǒ zhōngyú wánchéng le zuòyè.', 'Cuối cùng tôi đã hoàn thành bài tập.'),
(584, 3, 284, '种', 'zhǒng', 'loại, hạt giống', '他喜欢这种花。', 'Tā xǐhuān zhè zhǒng huā.', 'Anh ấy thích loại hoa này.'),
(585, 3, 285, '重要', 'zhòngyào', 'quan trọng', '这件事很重要。', 'Zhè jiàn shì hěn zhòngyào.', 'Việc này rất quan trọng.'),
(586, 3, 286, '主要', 'zhǔyào', 'chủ yếu', '主要问题是时间不够。', 'Zhǔyào wèntí shì shíjiān bù gòu.', 'Vấn đề chính là không đủ thời gian.'),
(587, 3, 287, '周末', 'zhōumò', 'cuối tuần', '周末我去公园玩。', 'Zhōumò wǒ qù gōngyuán wán.', 'Cuối tuần tôi đi công viên chơi.'),
(588, 3, 288, '祝', 'zhù', 'chúc', '祝你生日快乐。', 'Zhù nǐ shēngrì kuàilè.', 'Chúc bạn sinh nhật vui vẻ.'),
(589, 3, 289, '注意', 'zhùyì', 'chú ý', '请注意安全。', 'Qǐng zhùyì ānquán.', 'Vui lòng chú ý an toàn.'),
(590, 3, 290, '字典', 'zìdiǎn', 'từ điển', '我需要一本字典。', 'Wǒ xūyào yī běn zìdiǎn.', 'Tôi cần một quyển từ điển.'),
(591, 3, 291, '自己', 'zìjǐ', 'bản thân', '这是我自己的问题。', 'Zhè shì wǒ zìjǐ de wèntí.', 'Đây là vấn đề của chính tôi.'),
(592, 3, 292, '总是', 'zǒngshì', 'luôn luôn', '他总是很忙。', 'Tā zǒngshì hěn máng.', 'Anh ấy luôn luôn bận rộn.'),
(593, 3, 293, '最近', 'zuìjìn', 'gần đây', '最近我很忙。', 'Zuìjìn wǒ hěn máng.', 'Gần đây tôi rất bận.'),
(594, 3, 294, '作业', 'zuòyè', 'bài tập về nhà', '我已经做完作业了。', 'Wǒ yǐjīng zuò wán zuòyè le.', 'Tôi đã làm xong bài tập.'),
(595, 3, 295, '作用', 'zuòyòng', 'tác dụng', '这个词的作用是什么？', 'Zhège cí de zuòyòng shì shénme?', 'Tác dụng của từ này là gì?'),
