(968, 4, 373, '深', 'shēn', 'sâu', '湖水很深。', 'Húshuǐ hěn shēn.', 'Nước hồ rất sâu.'),
(969, 4, 374, '甚至', 'shèn zhì', 'thậm chí', '他甚至不知道我的名字。', 'Tā shènzhì bù zhīdào wǒ de míngzì.', 'Anh ấy thậm chí không biết tên tôi.'),
(970, 4, 375, '生活', 'shēng huó', 'cuộc sống', '我们的生活很幸福。', 'Wǒmen de shēnghuó hěn xìngfú.', 'Cuộc sống của chúng tôi rất hạnh phúc.'),
(971, 4, 376, '生命', 'shēng mìng', 'tính mạng', '生命很宝贵。', 'Shēngmìng hěn bǎoguì.', 'Sinh mệnh rất quý giá.'),
(972, 4, 377, '生意', 'shēng yì', 'kinh doanh', '他的生意做得很好。', 'Tā de shēngyì zuò de hěn hǎo.', 'Việc kinh doanh của anh ấy rất tốt.'),
(973, 4, 378, '省', 'shěng', 'tỉnh thành', '我们住在北江省。', 'Wǒmen zhù zài běijiāng shěng.', 'Chúng tôi sống ở tỉnh Bắc Giang'),
(974, 4, 379, '剩', 'shèng', 'thừa', '剩下的路程只能靠我们自己了。', 'Shèng xià de lùchéng zhǐ néng kào wǒmen zìjǐ le.', 'Phần còn lại của hành trình chỉ có thể dựa vào bản thân chúng ta.'),
(975, 4, 380, '失败', 'shī bài', 'thất bại', '他没有失败过。', 'Tā méiyǒu shībài guò.', 'Anh ấy chưa từng thất bại.'),
(976, 4, 381, '失望', 'shī wàng', 'thất vọng', '结果让我很失望。', 'Jiéguǒ ràng wǒ hěn shīwàng.', 'Kết quả làm tôi rất thất vọng.'),
(977, 4, 382, '师傅', 'shī fù', 'sư phụ', '师傅，请教我开车。', 'Shīfù, qǐng jiāo wǒ kāichē.', 'Thầy, xin dạy tôi lái xe.'),
(978, 4, 383, '十分', 'shí fēn', 'vô cùng', '他十分聪明。', 'Tā shífēn cōngmíng.', 'Anh ấy rất thông minh.'),
(979, 4, 384, '实际', 'shí jì', 'thực tế', '他的建议很实际。', 'Tā de jiànyì hěn shíjì.', 'Lời khuyên của anh ấy rất thực tế.'),
(980, 4, 385, '实在', 'shí zài', 'thật sự', '这个故事实在太感人了。', 'Zhège gùshì shízài tài gǎnrén le.', 'Câu chuyện này thật sự rất cảm động.'),
(981, 4, 386, '使', 'shǐ', 'khiến cho', '她的表现使观众们非常兴奋。', 'Tā de biǎoxiàn shǐ guānzhòngmen fēicháng xīngfèn.', 'Màn trình diễn của cô khiến khán giả vô cùng hưng phấn.'),
(982, 4, 387, '使用', 'shǐ yòng', 'sử dụng', '请不要随便使用别人的东西。', 'Qǐng bùyào suíbiàn shǐyòng biérén de dōngxī.', 'Xin đừng tùy tiện sử dụng đồ của người khác.'),
(983, 4, 388, '世纪', 'shì jì', 'thế kỉ', '这是二十一世纪的科技。', 'Zhè shì èrshíyī shìjì de kējì.', 'Đây là công nghệ của thế kỷ 21.'),
(984, 4, 389, '是否', 'shì fǒu', 'liệu có phải', '他是否同意还不确定。', 'Tā shìfǒu tóngyì hái bù quèdìng.', 'Anh ấy có đồng ý hay không còn chưa chắc chắn.'),
(985, 4, 390, '适合', 'shì hé', 'thích hợp', '这件衣服适合你。', 'Zhè jiàn yīfú shìhé nǐ.', 'Cái áo này hợp với bạn.'),
(986, 4, 391, '适应', 'shì yìng', 'thích nghi', '他适应了新的环境。', 'Tā shìyìng le xīn de huánjìng.', 'Anh ấy đã thích nghi với môi trường mới.'),
(987, 4, 392, '收', 'shōu', 'nhận', '请收这个包裹。', 'Qǐng shōu zhège bāoguǒ.', 'Xin nhận cái gói hàng này.'),
(988, 4, 393, '收入', 'shōu rù', 'thu nhập', '他的收入很高。', 'Tā de shōurù hěn gāo.', 'Thu nhập của anh ấy rất cao.'),
(989, 4, 394, '收拾', 'shōushi', 'dọn dẹp', '请把房间收拾干净。', 'Qǐng bǎ fángjiān shōushi gānjìng.', 'Xin dọn phòng sạch sẽ.'),
(990, 4, 395, '首都', 'shǒu dū', 'thủ đô', '北京是中国的首都。', 'Běijīng shì Zhōngguó de shǒudū.', 'Bắc Kinh là thủ đô của Trung Quốc.'),
(991, 4, 396, '首先', 'shǒu xiān', 'đầu tiên', '首先要学习，其次要实践。', 'Shǒuxiān yào xuéxí, qícì yào shíjiàn.', 'Trước tiên phải học, sau đó phải thực hành.'),
(992, 4, 397, '受不了', 'shòu bù liǎo', 'không chịu nổi', '我受不了这么热的天气。', 'Wǒ shòubùliǎo zhème rè de tiānqì.', 'Tôi không chịu nổi thời tiết nóng như thế này.'),
(993, 4, 398, '受到', 'shòu dào', 'nhận được', '我受到了一封信。', 'Wǒ shòudào le yī fēng xìn.', 'Tôi nhận được một lá thư.'),
(994, 4, 399, '售货员', 'shòu huò yuán', 'nhân viên bán vé', '售货员向我介绍了这款手机。', 'Shòuhuòyuán xiàng wǒ jièshào le zhè kuǎn shǒujī.', 'Người bán hàng giới thiệu cho tôi mẫu điện thoại này.'),
(995, 4, 400, '输', 'shū', 'thua', '我们输了比赛。', 'Wǒmen shū le bǐsài.', 'Chúng tôi thua trận đấu.'),
(996, 4, 401, '熟悉', 'shú xī', 'quen thuộc', '我对这儿很熟悉。', 'Wǒ duì zhèr hěn shúxī.', 'Tôi rất quen thuộc với nơi này.'),
(997, 4, 402, '数量', 'shù liàng', 'số lượng', '这里的学生数量很多。', 'Zhèlǐ de xuéshēng shùliàng hěn duō.', 'Số lượng học sinh ở đây rất nhiều.'),
(998, 4, 403, '数字', 'shùzì', 'con số', '这个数字很大。', 'Zhège shùzì hěn dà.', 'Con số này rất lớn.'),
(999, 4, 404, '帅', 'shuài', 'đẹp trai', '他很帅。', 'Tā hěn shuài.', 'Anh ấy rất đẹp trai.'),
(1000, 4, 405, '顺便', 'shùn biàn', 'nhân tiện', '我顺便买了些水果。', 'Wǒ shùnbiàn mǎi le xiē shuǐguǒ.', 'Tôi tiện thể mua một ít hoa quả.');
INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(1001, 4, 406, '顺利', 'shùn lì', 'thuận lợi', '事情进行得很顺利。', 'Shìqíng jìnxíng de hěn shùnlì.', 'Mọi việc tiến hành rất thuận lợi.'),
(1002, 4, 407, '顺序', 'shùn xù', 'thứ tự', '请按顺序排队。', 'Qǐng àn shùnxù páiduì.', 'Vui lòng xếp hàng theo thứ tự.'),
(1003, 4, 408, '说明', 'shuō míng', 'nói rõ', '请说明一下原因。', 'Qǐng shuōmíng yīxià yuányīn.', 'Xin hãy giải thích lý do.'),
(1004, 4, 409, '硕士', 'shuò shì', 'thạc sĩ', '他是硕士毕业。', 'Tā shì shuòshì bìyè.', 'Anh ấy tốt nghiệp thạc sĩ.'),
(1005, 4, 410, '死', 'sǐ', 'chết', '他突然死了。', 'Tā tūrán sǐ le.', 'Anh ấy đột nhiên qua đời.'),
(1006, 4, 411, '速度', 'sù dù', 'tốc độ', '请提高速度。', 'Qǐng tígāo sùdù.', 'Xin hãy tăng tốc độ.'),
(1007, 4, 412, '塑料袋', 'sù liào dài', 'túi ni lông', '请不要使用塑料袋。', 'Qǐng bùyào shǐyòng sùliào dài.', 'Xin đừng sử dụng túi nhựa.'),
(1008, 4, 413, '酸', 'suān', 'chua', '这道菜有点酸。', 'Zhè dào cài yǒudiǎn suān.', 'Món này hơi chua.'),
(1009, 4, 414, '随便', 'suí biàn', 'tùy tiện, tự nhiên', '请随便坐。', 'Qǐng suíbiàn zuò.', 'Xin cứ ngồi tự nhiên.'),
(1010, 4, 415, '随着', 'suí zhe', 'cùng với', '随着时间的流逝，他变得成熟了。', 'Suízhe shíjiān de liúshì, tā biàn dé chéngshú le.', 'Theo thời gian trôi qua, anh ấy trở nên chín chắn.'),
(1011, 4, 416, '孙子', 'sūn zi', 'cháu trai', '我有两个孙子。', 'Wǒ yǒu liǎng gè sūnzi.', 'Tôi có hai cháu trai.'),
(1012, 4, 417, '所有', 'suǒ yǒu', 'tất cả', '所有的人都来了。', 'Suǒyǒu de rén dōu lái le.', 'Mọi người đều đã đến.'),
(1013, 4, 418, '台', 'tái', 'cái, chiếc', '他站在台上。', 'Tā zhàn zài tái shàng.', 'Anh ấy đứng trên sân khấu.'),
(1014, 4, 419, '抬', 'tái', 'ngẩng', '请抬一下这个箱子。', 'Qǐng tái yīxià zhège xiāngzi.', 'Xin hãy nâng cái hộp này lên một chút.'),
(1015, 4, 420, '态度', 'tài dù', 'thái độ', '他的态度很不好。', 'Tā de tàidù hěn bù hǎo.', 'Thái độ của anh ấy rất tệ.'),
(1016, 4, 421, '谈', 'tán', 'nói chuyện', '我们谈了很多事情。', 'Wǒmen tán le hěn duō shìqíng.', 'Chúng tôi đã nói về rất nhiều chuyện.'),
(1017, 4, 422, '弹钢琴', 'tán gāng qín', 'chơi piano', '她会弹钢琴。', 'Tā huì tán gāngqín.', 'Cô ấy biết chơi piano.'),
(1018, 4, 423, '汤', 'tāng', 'canh', '我喜欢喝鸡汤。', 'Wǒ xǐhuān hē jītāng.', 'Tôi thích uống súp gà.'),
(1019, 4, 424, '糖', 'táng', 'đường', '我不喜欢吃太多糖。', 'Wǒ bù xǐhuān chī tài duō táng.', 'Tôi không thích ăn quá nhiều đường.'),
(1020, 4, 425, '躺', 'tǎng', 'nằm', '我喜欢躺在沙发上看书。', 'Wǒ xǐhuān tǎng zài shāfā shàng kàn shū.', 'Tôi thích nằm trên ghế sofa đọc sách.'),
(1021, 4, 426, '趟', 'tàng', 'chuyến', '我刚刚去了一趟商店。', 'Wǒ gānggāng qù le yī tàng shāngdiàn.', 'Tôi vừa đi một chuyến đến cửa hàng.'),
(1022, 4, 427, '讨论', 'tǎo lùn', 'thảo luận', '我们在会议上讨论了这个问题。', 'Wǒmen zài huìyì shàng tǎolùn le zhège wèntí.', 'Chúng tôi đã thảo luận về vấn đề này trong cuộc họp.'),
(1023, 4, 428, '讨厌', 'tǎo yàn', 'ghét', '我讨厌吃苦瓜。', 'Wǒ tǎoyàn chī kǔguā.', 'Tôi ghét ăn mướp đắng.'),
(1024, 4, 429, '特点', 'tè diǎn', 'đặc điểm', '这个产品的特点是什么？', 'Zhège chǎnpǐn de tèdiǎn shì shénme?', 'Đặc điểm của sản phẩm này là gì?'),
(1025, 4, 430, '提', 'tí', 'đề ra', '请提一些建议。', 'Qǐng tí yīxiē jiànyì.', 'Xin hãy đưa ra một vài gợi ý.'),
(1026, 4, 431, '提供', 'tí gōng', 'cung cấp', '我们提供免费早餐。', 'Wǒmen tígōng miǎnfèi zǎocān.', 'Chúng tôi cung cấp bữa sáng miễn phí.'),
(1027, 4, 432, '提前', 'tí qián', 'trước thời hạn', '请提前告诉我。', 'Qǐng tíqián gàosù wǒ.', 'Xin hãy cho tôi biết trước.'),
(1028, 4, 433, '提醒', 'tí xǐng', 'nhắc nhở', '他提醒我明天开会。', 'Tā tíxǐng wǒ míngtiān kāihuì.', 'Anh ấy nhắc tôi rằng ngày mai họp.'),
(1029, 4, 434, '填空', 'tián kòng', 'điền trống', '请在填空处写上答案。', 'Qǐng zài tiánkòng chù xiě shàng dá''àn.', 'Xin hãy điền câu trả lời vào chỗ trống.'),
(1030, 4, 435, '条件', 'tiáo jiàn', 'điều kiện', '这个工作条件很好。', 'Zhège gōngzuò tiáojiàn hěn hǎo.', 'Điều kiện công việc này rất tốt.'),
(1031, 4, 436, '停', 'tíng', 'dừng', '请停车。', 'Qǐng tíng chē.', 'Xin dừng xe.'),
(1032, 4, 437, '挺', 'tǐng', 'rất', '他挺高的。', 'Tā tǐng gāo de.', 'Anh ấy khá cao.'),
(1033, 4, 438, '通过', 'tōng guò', 'thông qua', '我通过了考试。', 'Wǒ tōngguò le kǎoshì.', 'Tôi đã qua kỳ thi.'),
(1034, 4, 439, '通知', 'tōng zhī', 'thông báo', '请通知大家明天的会议。', 'Qǐng tōngzhī dàjiā míngtiān de huìyì.', 'Xin thông báo với mọi người về cuộc họp ngày mai.'),
(1035, 4, 440, '同情', 'tóng qíng', 'đồng tình', '我们都很同情他。', 'Wǒmen dōu hěn tóngqíng tā.', 'Chúng tôi đều rất đồng cảm với anh ấy.'),
(1036, 4, 441, '同时', 'tóng shí', 'đồng thời', '他同时做两份工作。', 'Tā tóngshí zuò liǎng fèn gōngzuò.', 'Anh ấy làm hai công việc cùng một lúc.'),
(1037, 4, 442, '推', 'tuī', 'đẩy', '请帮我推一下门。', 'Qǐng bāng wǒ tuī yīxià mén.', 'Xin hãy giúp tôi đẩy cửa.'),
(1038, 4, 443, '推迟', 'tuī chí', 'kéo dài thời gian', '会议推迟到明天。', 'Huìyì tuīchí dào míngtiān.', 'Cuộc họp bị hoãn đến ngày mai.'),
(1039, 4, 444, '脱', 'tuō', 'cởi', '请脱下你的外套。', 'Qǐng tuō xià nǐ de wàitào.', 'Xin cởi áo khoác ra.'),
(1040, 4, 445, '袜子', 'wà zi', 'tất chân', '我需要一双新的袜子。', 'Wǒ xūyào yī shuāng xīn de wàzi.', 'Tôi cần một đôi tất mới.'),
(1041, 4, 446, '完全', 'wán quán', 'hoàn toàn', '我完全同意你的看法。', 'Wǒ wánquán tóngyì nǐ de kànfǎ.', 'Tôi hoàn toàn đồng ý với quan điểm của bạn.'),
(1042, 4, 447, '网球', 'wǎng qiú', 'tennis', '我喜欢打网球。', 'Wǒ xǐhuān dǎ wǎngqiú.', 'Tôi thích chơi tennis.'),
(1043, 4, 448, '网站', 'wǎng zhàn', 'trang mạng', '这个网站很好用。', 'Zhège wǎngzhàn hěn hǎo yòng.', 'Trang web này rất hữu ích.'),
(1044, 4, 449, '往往', 'wǎng wǎng', 'thường (quá khứ)', '他往往迟到。', 'Tā wǎngwǎng chídào.', 'Anh ấy thường xuyên đến muộn.'),
(1045, 4, 450, '危险', 'wēi xiǎn', 'nguy hiểm', '小心，这里很危险。', 'Xiǎoxīn, zhèlǐ hěn wēixiǎn.', 'Cẩn thận, chỗ này rất nguy hiểm.'),
(1046, 4, 451, '卫生间', 'wèi shēng jiān', 'phòng vệ sinh', '卫生间在哪里？', 'Wèishēngjiān zài nǎlǐ?', 'Nhà vệ sinh ở đâu?'),
(1047, 4, 452, '味道', 'wèi dào', 'mùi vị', '这个菜的味道很好。', 'Zhège cài de wèidào hěn hǎo.', 'Món này có hương vị rất ngon.'),
(1048, 4, 453, '温度', 'wēn dù', 'nhiệt độ', '今天的温度很高。', 'Jīntiān de wēndù hěn gāo.', 'Nhiệt độ hôm nay rất cao.'),
(1049, 4, 454, '文章', 'wén zhāng', 'bài văn', '这篇文章写得很好。', 'Zhè piān wénzhāng xiě de hěn hǎo.', 'Bài viết này được viết rất hay.'),
(1050, 4, 455, '污染', 'wū rǎn', 'ô nhiễm', '这里的污染很严重。', 'Zhèlǐ de wūrǎn hěn yánzhòng.', 'Ô nhiễm ở đây rất nghiêm trọng.'),
(1051, 4, 456, '无', 'wú', 'không', '他无话可说。', 'Tā wú huà kě shuō.', 'Anh ấy không biết nói gì.'),
(1052, 4, 457, '无聊', 'wú liáo', 'nhàm chán', '这本书很无聊。', 'Zhè běn shū hěn wúliáo.', 'Cuốn sách này rất nhàm chán.'),
(1053, 4, 458, '无论', 'wú lùn', 'bất luận', '无论天气如何，我们都去。', 'Wúlùn tiānqì rúhé, wǒmen dōu qù.', 'Bất kể thời tiết thế nào, chúng tôi đều đi.'),
(1054, 4, 459, '误会', 'wù huì', 'hiểu lầm', '我误会了他的意思。', 'Wǒ wùhuì le tā de yìsi.', 'Tôi đã hiểu lầm ý của anh ấy.'),
(1055, 4, 460, '西红柿', 'xī hóng shì', 'cà chua', '我喜欢吃西红柿。', 'Wǒ xǐhuān chī xīhóngshì.', 'Tôi thích ăn cà chua.'),
(1056, 4, 461, '吸引', 'xī yǐn', 'thu hút', '他的表演吸引了很多人。', 'Tā de biǎoyǎn xīyǐn le hěn duō rén.', 'Màn biểu diễn của anh ấy thu hút rất nhiều người.'),
(1057, 4, 462, '咸', 'xián', 'mặn', '这个菜有点咸。', 'Zhège cài yǒudiǎn xián.', 'Món này hơi mặn.'),
