(1479, 5, 284, '否定', 'fǒu dìng', 'phủ định', '他否定了所有的指责。', 'Tā fǒudìngle suǒyǒu de zhǐzé.', 'Anh ấy đã phủ nhận tất cả các chỉ trích.'),
(1480, 5, 285, '否认', 'fǒu rèn', 'phủ nhận', '她完全否认了这个事实。', 'Tā wánquán fǒurènle zhège shìshí.', 'Cô ấy hoàn toàn phủ nhận thực tế này.'),
(1481, 5, 286, '扶', 'fú', 'vịn', '他在路上扶着我。', 'Tā zài lù shàng fúzhe wǒ.', 'Anh ấy hỗ trợ tôi trên đường.'),
(1482, 5, 287, '服装', 'fú zhuāng', 'phục trang, quần áo', '我们需要买新的服装。', 'Wǒmen xūyào mǎi xīn de fúzhuāng.', 'Chúng ta cần mua sắm quần áo mới.'),
(1483, 5, 288, '幅', 'fú', 'bức (lượng từ cho tranh)', '这幅画儿很漂亮。', 'Zhè fú huàr hěn piàoliang.', 'Bức tranh này rất đẹp.'),
(1484, 5, 289, '辅导', 'fǔ dǎo', 'phụ đạo, bổ trợ', '她需要额外的辅导。', 'Tā xūyào éwài de fǔdǎo.', 'Cô ấy cần thêm sự hướng dẫn.'),
(1485, 5, 290, '妇女', 'fù nǚ', 'phụ nữ', '妇女在社会中扮演重要的角色。', 'Fùnǚ zài shèhuì zhōng bànyǎn zhòngyào de juésè.', 'Phụ nữ đóng vai trò quan trọng trong xã hội.'),
(1486, 5, 291, '复制', 'fù zhì', 'copy', '请复制这个文件。', 'Qǐng fùzhì zhège wénjiàn.', 'Hãy sao chép tài liệu này.'),
(1487, 5, 292, '改革', 'gǎi gé', 'cải cách', '我们需要进行改革。', 'Wǒmen xūyào jìnxíng gǎigé.', 'Chúng ta cần thực hiện cải cách.'),
(1488, 5, 293, '改进', 'gǎi jìn', 'cải tiến', '他希望能改进工作流程。', 'Tā xīwàng néng gǎijìn gōngzuò liúchéng.', 'Anh ấy hy vọng có thể cải tiến quy trình làm việc.'),
(1489, 5, 294, '改善', 'gǎi shàn', 'cải thiện', '他们正在改善居住条件。', 'Tāmen zhèngzài gǎishàn jūzhù tiáojiàn.', 'Họ đang cải thiện điều kiện sống.'),
(1490, 5, 295, '改正', 'gǎi zhèng', 'đính chính', '我们需要改正错误。', 'Wǒmen xūyào gǎizhèng cuòwù.', 'Chúng ta cần sửa chữa lỗi.'),
(1491, 5, 296, '盖', 'gài', 'đậy, bao phủ', '这一片区域都被盖上了高楼大厦。', 'Zhè yīpiàn qūyù dōu bèi gài shàngle gāolóu dàshà.', 'Khu vực này được bao phủ bởi các tòa nhà cao tầng.'),
(1492, 5, 297, '概括', 'gài kuò', 'khái quát', '文章的概括很简洁。', 'Wénzhāng de gàikuò hěn jiǎnjié.', 'Tóm tắt của bài viết rất ngắn gọn.'),
(1493, 5, 298, '概念', 'gài niàn', 'khái niệm', '这个概念很重要。', 'Zhège gàiniàn hěn zhòngyào.', 'Khái niệm này rất quan trọng.'),
(1494, 5, 299, '干脆', 'gān cuì', 'dứt khoát', '他的发言非常干脆，没有一句多余的话。', 'Tā de fǎ yán fēicháng gāncuì, méiyǒu yījù duōyú dehuà.', 'Bài phát biểu của anh ấy rất ngắn gọn dứt khoát, không có bất kỳ từ nào dư thừa.'),
(1495, 5, 300, '干燥', 'gān zào', 'khô ráo, khô hanh', '干燥的空气使得火势很容易蔓延。', 'Gānzào de kōngqì shǐdé huǒshì hěn róngyì mànyán.', 'Không khí khô khiến lửa dễ lan rộng.'),
(1496, 5, 301, '赶紧', 'gǎn jǐn', 'mau chóng', '赶紧做完作业吧。', 'Gǎnjǐn zuò wán zuòyè ba.', 'Hãy nhanh chóng làm xong bài tập.'),
(1497, 5, 302, '赶快', 'gǎn kuài', 'mau chóng', '他赶快去看医生。', 'Tā gǎnkuài qù kàn yīshēng.', 'Anh ấy nhanh chóng đi gặp bác sĩ.'),
(1498, 5, 303, '感激', 'gǎn jī', 'cảm kích, biết ơn', '我非常感激你的帮助。', 'Wǒ fēicháng gǎnjī nǐ de bāngzhù.', 'Tôi rất cảm kích sự giúp đỡ của bạn.'),
(1499, 5, 304, '感受', 'gǎn shòu', 'cảm nhận', '我能感受你的情绪。', 'Wǒ néng gǎnshòu nǐ de qíngxù.', 'Tôi có thể cảm nhận được cảm xúc của bạn.'),
(1500, 5, 305, '感想', 'gǎn xiǎng', 'cảm tưởng, suy nghĩ', '他的感想很有趣。', 'Tā de gǎnxiǎng hěn yǒuqù.', 'Những cảm nghĩ của anh ấy rất thú vị.');
INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(1501, 5, 306, '干活儿', 'gànhuór', 'lao động', '我们一起干活儿吧。', 'Wǒmen yīqǐ gàn huór ba.', 'Chúng ta cùng làm việc nhé.'),
(1502, 5, 307, '钢铁', 'gāng tiě', 'sắt thép', '钢铁是工业化进程中不可或缺的力量。', 'Gāngtiě shì gōngyèhuà jìnchéng zhōng bùkě huò quē de lìliàng。', 'Sắt thép là lực lượng không thể thiếu trong quá trình công nghiệp hóa.'),
(1503, 5, 308, '高档', 'gāo dàng', 'cao cấp, đẳng cấp', '这件礼服的设计显示出一种高档次的感觉。', 'Zhè jiàn lǐfú de shèjì xiǎnshì chū yī zhǒng gāo dàngcì de gǎnjué', 'Thiết kế của chiếc váy này mang lại cảm giác cao cấp.'),
(1504, 5, 309, '高级', 'gāo jí', 'cao cấp', 'HSK6 级是高级水平。', 'HSK6 jí shì gāojí shuǐpíng.', 'HSK6 là trình độ nâng cao.'),
(1505, 5, 310, '搞', 'gǎo', 'làm', '我们要搞好这个项目。', 'Wǒmen yào gǎo hǎo zhège xiàngmù.', 'Chúng ta phải làm tốt dự án này.'),
(1506, 5, 311, '告别', 'gào bié', 'từ biệt', '我们要告别这座城市。', 'Wǒmen yào gàobié zhè zuò chéngshì.', 'Chúng ta phải nói lời tạm biệt với thành phố này.'),
(1507, 5, 312, '格外', 'gé wài', 'đặc biệt', '这个地方格外安静。', 'Zhège dìfāng géwài ānjìng.', 'Nơi này đặc biệt yên tĩnh.'),
(1508, 5, 313, '隔壁', 'gé bì', 'sát vách, ngay cạnh', '我们住在隔壁的房子。', 'Wǒmen zhù zài gébì de fángzi.', 'Chúng tôi sống trong ngôi nhà kế bên.'),
(1509, 5, 314, '个别', 'gè bié', 'cá biệt', '个别情况可能会有所不同。', 'Gèbié qíngkuàng kěnéng huì yǒu suǒ bùtóng.', 'Một số trường hợp cụ thể có thể khác nhau.'),
(1510, 5, 315, '个人', 'gè rén', 'cá nhân', '每个人都有自己的个人喜好和兴趣。', 'Měi gèrén dōu yǒu zìjǐ de gèrén xǐhào hé xìngqù.', 'Mỗi người đều có sở thích và mối quan tâm riêng của mình.'),
(1511, 5, 316, '个性', 'gè xìng', 'cá tính', '他是一个非常有个性的人。', 'Tā shì yīgè fēicháng yǒu gèxìng de rén.', 'Anh ấy là một người rất cá tính.'),
(1512, 5, 317, '各自', 'gè zì', 'tự, mỗi', '各自负责自己的任务。', 'Gèzì fùzé zìjǐ de rènwù.', 'Mỗi người chịu trách nhiệm về nhiệm vụ của mình.'),
(1513, 5, 318, '根', 'gēn', 'lượng từ: sợi, cành, khúc, ngón', '你记得帮我买几根葱哦。', 'Nǐ jìdé bāng wǒ mǎi jǐ gēn cōng ó.', 'Nhớ mua cho tôi ít hành lá nhé.'),
(1514, 5, 319, '根本', 'gēn běn', 'vốn', '这个问题根本解决不了。', 'Zhège wèntí gēnběn jiějué bùliǎo.', 'Vấn đề này căn bản không thể giải quyết được.'),
(1515, 5, 320, '工厂', 'gōng chǎng', 'xưởng, xí nghiệp', '工厂正在扩大生产规模。', 'Gōngchǎng zhèngzài kuòdà shēngchǎn guīmó.', 'Nhà máy đang mở rộng quy mô sản xuất.'),
(1516, 5, 321, '工程师', 'gōng chéng shī', 'kỹ sư', '他是一名工程师。', 'Tā shì yī míng gōngchéngshī.', 'Anh ấy là một kỹ sư.'),
(1517, 5, 322, '工具', 'gōng jù', 'công cụ', '我们需要一些工具来修理。', 'Wǒmen xūyào yīxiē gōngjù lái xiūlǐ.', 'Chúng ta cần một số công cụ để sửa chữa.'),
(1518, 5, 323, '工人', 'gōng rén', 'công nhân', '工人们正在加班。', 'Gōngrénmen zhèngzài jiābān.', 'Các công nhân đang làm thêm giờ.'),
(1519, 5, 324, '工业', 'gōng yè', 'công nghiệp', '这个产品是我们工业的代表。', 'Zhège chǎnpǐn shì wǒmen gōngyè de dàibiǎo.', 'Sản phẩm này đại diện cho ngành công nghiệp của chúng tôi.'),
(1520, 5, 325, '公布', 'gōng bù', 'công bố', '公司公布了新的政策。', 'Gōngsī gōngbùle xīn de zhèngcè.', 'Công ty đã công bố chính sách mới.'),
(1521, 5, 326, '公开', 'gōng kāi', 'công khai', '这个信息已经公开了。', 'Zhège xìnxī yǐjīng gōngkāile.', 'Thông tin này đã được công khai.'),
(1522, 5, 327, '公平', 'gōng píng', 'công bằng', '我们需要公平对待每个人。', 'Wǒmen xūyào gōngpíng duìdài měi gè rén.', 'Chúng ta cần đối xử công bằng với mọi người.'),
(1523, 5, 328, '公寓', 'gōng yù', 'chung cư', '她住在一个公寓里。', 'Tā zhù zài yīgè gōngyù lǐ.', 'Cô ấy sống trong một căn hộ.'),
(1524, 5, 329, '公元', 'gōng yuán', 'công nguyên', '公元前五世纪的历史很有趣。', 'Gōngyuán qián wǔ shìjì de lìshǐ hěn yǒuqù.', 'Lịch sử của thế kỷ thứ năm trước Công nguyên rất thú vị.'),
(1525, 5, 330, '公主', 'gōng zhǔ', 'công chúa', '她是一个美丽的公主。', 'Tā shì yīgè měilì de gōngzhǔ.', 'Cô ấy là một công chúa xinh đẹp.'),
(1526, 5, 331, '功能', 'gōng néng', 'công năng', '这个软件的功能很强大。', 'Zhège ruǎnjiàn de gōngnéng hěn qiángdà.', 'Chức năng của phần mềm này rất mạnh mẽ.'),
(1527, 5, 332, '恭喜', 'gōng xǐ', 'chúc mừng', '恭喜你获得了奖项。', 'Gōngxǐ nǐ huòdéle jiǎngxiàng.', 'Chúc mừng bạn đã nhận được giải thưởng.'),
(1528, 5, 333, '贡献', 'gòng xiàn', 'cống hiến', '他的贡献很大。', 'Tā de gòngxiàn hěn dà.', 'Đóng góp của anh ấy rất lớn.'),
(1529, 5, 334, '沟通', 'gōu tōng', 'trao đổi, thấu hiểu', '我们需要有效沟通。', 'Wǒmen xūyào yǒuxiào gōutōng.', 'Chúng ta cần giao tiếp hiệu quả.'),
(1530, 5, 335, '构成', 'gòu chéng', 'tạo thành, cấu thành', '这些部分构成了整个项目。', 'Zhèxiē bùfen gòuchéngle zhěnggè xiàngmù.', 'Những phần này cấu thành toàn bộ dự án.'),
(1531, 5, 336, '姑姑', 'gū gu', 'cô', '我去姑姑家玩。', 'Wǒ qù gūgū jiā wán.', 'Tôi đến nhà dì chơi.'),
(1532, 5, 337, '姑娘', 'gū niang', 'cô gái', '这位姑娘很友好。', 'Zhè wèi gūniáng hěn yǒuhǎo.', 'Cô gái này rất thân thiện.'),
(1533, 5, 338, '古代', 'gǔ dài', 'cổ đại', '古代的建筑风格很有特色。', 'Gǔdài de jiànzhú fēnggé hěn yǒu tèsè.', 'Phong cách kiến trúc cổ đại rất đặc sắc.'),
(1534, 5, 339, '古典', 'gǔ diǎn', 'cổ điển', '他喜欢古典音乐。', 'Tā xǐhuān gǔdiǎn yīnyuè.', 'Anh ấy thích nhạc cổ điển.'),
(1535, 5, 340, '股票', 'gǔ piào', 'cổ phiếu', '我们需要研究股票市场。', 'Wǒmen xūyào yánjiū gǔpiào shìchǎng.', 'Chúng ta cần nghiên cứu thị trường chứng khoán.'),
(1536, 5, 341, '骨头', 'gǔ tou', 'xương', '这个骨头很硬。', 'Zhège gǔtóu hěn yìng.', 'Xương này rất cứng.'),
(1537, 5, 342, '鼓舞', 'gǔ wǔ', 'cổ vũ', '他的演讲鼓舞了大家。', 'Tā de yǎnjiǎng gǔwǔle dàjiā.', 'Bài phát biểu của anh ấy đã khích lệ mọi người.'),
(1538, 5, 343, '鼓掌', 'gǔ zhǎng', 'vỗ tay', '大家为他鼓掌。', 'Dàjiā wèi tā gǔzhǎng.', 'Mọi người vỗ tay cho anh ấy.'),
(1539, 5, 344, '固定', 'gù dìng', 'cố định', '这张桌子是固定的。', 'Zhè zhāng zhuōzi shì gùdìng de.', 'Cái bàn này là cố định.'),
(1540, 5, 345, '挂号', 'guà hào', 'xếp số', '请挂号后再进入。', 'Qǐng guàhào hòu zài jìnrù.', 'Xin hãy đăng ký trước khi vào.'),
(1541, 5, 346, '乖', 'guāi', 'ngoan', '她的行为很乖。', 'Tā de xíngwéi hěn guāi.', 'Hành vi của cô ấy rất ngoan.'),
(1542, 5, 347, '拐弯', 'guǎi wān', 'rẽ', '车子在路上拐弯了。', 'Chēzi zài lù shàng guǎiwānle.', 'Xe đã rẽ ở trên đường.'),
(1543, 5, 348, '怪不得', 'guài bù dé', 'chẳng trách', '怪不得她这么高兴。', 'Guàibùdé tā zhème gāoxìng.', 'Không ngạc nhiên khi cô ấy vui như vậy.'),
(1544, 5, 349, '关闭', 'guān bì', 'đóng', '他们决定关闭公司。', 'Tāmen juédìng guānbì gōngsī.', 'Họ quyết định đóng cửa công ty.'),
(1545, 5, 350, '观察', 'guān chá', 'quan sát', '我们需要观察市场趋势。', 'Wǒmen xūyào guānchá shìchǎng qūshì.', 'Chúng ta cần quan sát xu hướng thị trường.'),
(1546, 5, 351, '观点', 'guān diǎn', 'quan điểm', '他有自己独特的观点。', 'Tā yǒu zìjǐ dútè de guāndiǎn.', 'Anh ấy có quan điểm riêng biệt của mình.'),
(1547, 5, 352, '观念', 'guān niàn', 'quan niệm', '这是一个新的观念。', 'Zhè shì yīgè xīn de guānniàn.', 'Đây là một khái niệm mới.'),
(1548, 5, 353, '官', 'guān', 'quan', '他是一位官员。', 'Tā shì yī wèi guānyuán.', 'Anh ấy là một quan chức.'),
(1549, 5, 354, '管子', 'guǎn zi', 'cái ống', '我们需要买一些管子。', 'Wǒmen xūyào mǎi yīxiē guǎnzi.', 'Chúng ta cần mua một số ống.'),
(1550, 5, 355, '冠军', 'guàn jūn', 'quán quân', '他赢得了冠军。', 'Tā yíngdéle guànjūn.', 'Anh ấy đã giành được chức vô địch.'),
(1551, 5, 356, '光滑', 'guāng huá', 'bóng mượt', '这条地毯很光滑。', 'Zhè tiáo dìtǎn hěn guānghuá.', 'Tấm thảm này rất mượt mà.'),
(1552, 5, 357, '光临', 'guāng lín', 'đến, có mặt', '欢迎光临我们的商店。', 'Huānyíng guānglín wǒmen de shāngdiàn.', 'Chào mừng bạn đến với cửa hàng của chúng tôi.'),
(1553, 5, 358, '光明', 'guāng míng', 'quang minh, sáng sủa', '早晨的阳光照亮了大地，给予我们光明的希望。', 'Zǎochén de yángguāng zhào liàngle dàdì, jǐyǔ wǒmen guāngmíng de xīwàng.', 'Mặt trời buổi sáng chiếu sáng trái đất và mang lại cho chúng ta niềm hy vọng tươi sáng.'),
(1554, 5, 359, '光盘', 'guāng pán', 'đĩa CD, VCD,DVD', '我们买了一张光盘。', 'Wǒmen mǎile yī zhāng guāngpán.', 'Chúng tôi đã mua một đĩa CD.'),
(1555, 5, 360, '广场', 'guǎng chǎng', 'quảng trường', '广场上有很多人。', 'Guǎngchǎng shàng yǒu hěn duō rén.', 'Có nhiều người ở quảng trường.'),
(1556, 5, 361, '广大', 'guǎng dà', 'quảng đại, rộng lớn', '这个地区很广大。', 'Zhège dìqū hěn guǎngdà.', 'Khu vực này rất rộng lớn.'),
(1557, 5, 362, '广泛', 'guǎng fàn', 'rộng khắp', '这本书的内容很广泛。', 'Zhè běn shū de nèiróng hěn guǎngfàn.', 'Nội dung của cuốn sách này rất rộng rãi.'),
(1558, 5, 363, '归纳', 'guī nà', 'tóm tắt', '我们需要归纳总结信息。', 'Wǒmen xūyào guīnà zǒngjié xìnxī.', 'Chúng ta cần tổng hợp và tóm tắt thông tin.'),
(1559, 5, 364, '规矩', 'guī ju', 'qui tắc', '他遵守了所有的规矩。', 'Tā zūnshǒule suǒyǒu de guījǔ.', 'Anh ấy đã tuân theo tất cả các quy tắc.'),
(1560, 5, 365, '规律', 'guī lǜ', 'qui luật', '这个问题的规律很复杂。', 'Zhège wèntí de guīlǜ hěn fùzá.', 'Quy luật của vấn đề này rất phức tạp.'),
(1561, 5, 366, '规模', 'guī mó', 'qui mô', '公司的规模不断扩大。', 'Gōngsī de guīmó bùduàn kuòdà.', 'Quy mô của công ty đang không ngừng mở rộng.'),
