(1655, 5, 460, '驾驶', 'jià shǐ', 'lái xe', '他正在学习驾驶。', 'Tā zhèngzài xuéxí jiàshǐ.', 'Anh ấy đang học lái xe.'),
(1656, 5, 461, '嫁', 'jià', 'gả chồng', '她打算嫁给他。', 'Tā dǎsuàn jià gěi tā.', 'Cô ấy dự định kết hôn với anh ấy.'),
(1657, 5, 462, '坚决', 'jiān jué', 'kiên quyết', '他坚决拒绝了这个提议。', 'Tā jiānjué jùjuéle zhège tíyì.', 'Anh ấy kiên quyết từ chối đề nghị này.'),
(1658, 5, 463, '坚强', 'jiān qiáng', 'kiên cường', '她非常坚强。', 'Tā fēicháng jiānqiáng.', 'Cô ấy rất mạnh mẽ.'),
(1659, 5, 464, '肩膀', 'jiān bǎng', 'bờ vai', '他肩膀上有一个伤口。', 'Tā jiānbǎng shàng yǒu yīgè shāngkǒu.', 'Anh ấy có một vết thương trên vai.'),
