(1670, 5, 475, '健身', 'jiàn shēn', 'tập thể dục', '他每天去健身房锻炼。', 'Tā měitiān qù jiànshēn fáng duànliàn.', 'Anh ấy đến phòng tập thể dục mỗi ngày.'),
(1671, 5, 476, '键盘', 'jiàn pán', 'bàn phím', '我买了一台新键盘。', 'Wǒ mǎile yī tái xīn jiànpán.', 'Tôi đã mua một bàn phím mới.'),
(1672, 5, 477, '讲究', 'jiǎngjiu', 'coi trọng', '这篇文章讲究细节。', 'Zhè piān wénzhāng jiǎngjiu xìjié.', 'Bài viết này chú trọng đến chi tiết.'),
