(1976, 5, 781, '人员', 'rén yuán', 'nhân viên', '我们的人员配置已经完成。', 'Wǒmen de rényuán pèizhì yǐjīng wánchéng.', 'Việc phân bổ nhân sự của chúng tôi đã hoàn tất.'),
(1977, 5, 782, '忍不住', 'rěn bù zhù', 'không nhịn được', '他忍不住笑了出来。', 'Tā rěn bù zhù xiàole chūlái.', 'Anh ấy không thể nhịn cười.'),
