(1992, 5, 797, '杀', 'shā', 'giết', '他杀了一个害虫。', 'Tā shāle yīgè hàichóng.', 'Anh ấy đã giết một con sâu.'),
(1993, 5, 798, '沙漠', 'shā mò', 'sa mạc', '沙漠里很少有植物。', 'Shāmò lǐ hěn shǎo yǒu zhíwù.', 'Ở sa mạc, rất ít có thực vật.'),
(1994, 5, 799, '沙滩', 'shā tān', 'bãi cát', '我们在沙滩上散步。', 'Wǒmen zài shātān shàng sànbù.', 'Chúng tôi đi dạo trên bãi biển.'),
(1995, 5, 800, '傻', 'shǎ', 'ngốc nghếch', '他总是做些傻事。', 'Tā zǒng shì zuò xiē shǎ shì.', 'Anh ấy luôn làm những việc ngớ ngẩn.'),
(1996, 5, 801, '晒', 'shài', 'phơi, tắm nắng', '我喜欢在阳光下晒太阳。', 'Wǒ xǐhuān zài yángguāng xià shài tàiyáng.', 'Tôi thích tắm nắng dưới ánh mặt trời.'),
(1997, 5, 802, '删除', 'shān chú', 'xóa bỏ', '请删除这个错误的文件。', 'Qǐng shānchú zhège cuòwù de wénjiàn.', 'Xin hãy xóa tài liệu sai này.'),
(1998, 5, 803, '闪电', 'shǎn diàn', 'chớp', '昨晚的闪电很亮。', 'Zuówǎn de shǎndiàn hěn liàng.', 'Sấm sét tối qua rất sáng.'),
(1999, 5, 804, '扇子', 'shàn zi', 'cái quạt', '她用扇子给大家扇风。', 'Tā yòng shànzi gěi dàjiā shàn fēng.', 'Cô ấy dùng quạt để làm mát cho mọi người.'),
(2000, 5, 805, '善良', 'shàn liáng', 'lương thiện, hiền lành', '他是一个非常善良的人。', 'Tā shì yīgè fēicháng shànliáng de rén.', 'Anh ấy là một người rất tốt bụng.');
