(2439, 5, 1244, '煮', 'zhǔ', 'luộc, đun', '我们需要煮一些水。', 'Wǒmen xūyào zhǔ yīxiē shuǐ.', 'Chúng ta cần đun sôi một ít nước.'),
(2440, 5, 1245, '注册', 'zhù cè', 'đăng kí', '请注册你的账户。', 'Qǐng zhùcè nǐ de zhànghù.', 'Xin hãy đăng ký tài khoản của bạn.'),
(2441, 5, 1246, '祝福', 'zhù fú', 'chúc phúc', '我祝福你们幸福快乐。', 'Wǒ zhùfú nǐmen xìngfú kuàilè.', 'Tôi chúc các bạn hạnh phúc và vui vẻ.'),
(2442, 5, 1247, '抓', 'zhuā', 'bắt, véo', '他用力抓住了绳子。', 'Tā yòng lì zhuāzhùle shéngzi.', 'Anh ấy nắm chặt sợi dây.'),
(2443, 5, 1248, '抓紧', 'zhuā jǐn', '(tay) nắm chắc, tranh thủ (thời gian)', '请抓紧时间完成任务。', 'Qǐng zhuā jǐn shíjiān wánchéng rènwù.', 'Xin hãy tranh thủ thời gian để hoàn thành nhiệm vụ.'),
(2444, 5, 1249, '专家', 'zhuān jiā', 'chuyên gia', '他是一位专家。', 'Tā shì yī wèi zhuānjiā.', 'Anh ấy là một chuyên gia.'),
(2445, 5, 1250, '专心', 'zhuān xīn', 'chuyên tâm', '你要专心听讲。', 'Nǐ yào zhuānxīn tīng jiǎng.', 'Bạn cần tập trung nghe giảng.'),
(2446, 5, 1251, '转变', 'zhuǎn biàn', 'chuyển biến', '这次转变对公司很重要。', 'Zhè cì zhuǎnbiàn duì gōngsī hěn zhòngyào.', 'Sự thay đổi lần này rất quan trọng đối với công ty.'),
(2447, 5, 1252, '转告', 'zhuǎn gào', 'chuyển lời', '我会把这个消息转告给你。', 'Wǒ huì bǎ zhège xiāoxī zhuǎngào gěi nǐ.', 'Tôi sẽ chuyển thông tin này cho bạn.'),
(2448, 5, 1253, '装', 'zhuāng', 'đựng, chứa', '她正在装行李。', 'Tā zhèngzài zhuāng xínglǐ.', 'Cô ấy đang đóng gói hành lý.'),
(2449, 5, 1254, '装饰', 'zhuāng shì', 'trang hoàng, trang trí', '她在房间里做了很多装饰。', 'Tā zài fángjiān lǐ zuòle hěn duō zhuāngshì.', 'Cô ấy đã làm rất nhiều trang trí trong phòng.'),
(2450, 5, 1255, '装修', 'zhuāng xiū', 'sửa nội thất', '我们正在装修房子。', 'Wǒmen zhèngzài zhuāngxiū fángzi.', 'Chúng tôi đang sửa sang căn nhà.'),
(2451, 5, 1256, '状况', 'zhuàng kuàng', 'tình trạng', '他的健康状况很好。', 'Tā de jiànkāng zhuàngkuàng hěn hǎo.', 'Tình trạng sức khỏe của anh ấy rất tốt.'),
(2452, 5, 1257, '状态', 'zhuàng tài', 'trạng thái', '目前的状态不是很理想。', 'Mùqián de zhuàngtài bù shì hěn lǐxiǎng.', 'Tình trạng hiện tại không được lý tưởng lắm.'),
(2453, 5, 1258, '撞', 'zhuàng', 'va vào, đâm vào', '他不小心撞到了墙。', 'Tā bù xiǎoxīn zhuàng dào le qiáng.', 'Anh ấy vô tình đâm vào tường.'),
(2454, 5, 1259, '追', 'zhuī', 'đuổi theo', '他在追一辆公共汽车。', 'Tā zài zhuī yī liàng gōnggòng qìchē.', 'Anh ấy đang đuổi theo một chiếc xe buýt.'),
(2455, 5, 1260, '追求', 'zhuī qiú', 'theo đuổi', '她一直在追求自己的梦想。', 'Tā yīzhí zài zhuīqiú zìjǐ de mèngxiǎng.', 'Cô ấy luôn theo đuổi ước mơ của mình.'),
(2456, 5, 1261, '咨询', 'zī xún', 'tư vấn', '我们需要咨询专家的意见。', 'Wǒmen xūyào zīxún zhuānjiā de yìjiàn.', 'Chúng ta cần tham khảo ý kiến của chuyên gia.'),
(2457, 5, 1262, '姿势', 'zī shì', 'tư thế', '你的姿势很优雅。', 'Nǐ de zīshì hěn yōuyǎ.', 'Tư thế của bạn rất duyên dáng.'),
(2458, 5, 1263, '资格', 'zī gé', 'tư cách', '这个职位需要一定的资格。', 'Zhège zhíwèi xūyào yīdìng de zīgé.', 'Vị trí này yêu cầu một số bằng cấp nhất định.'),
(2459, 5, 1264, '资金', 'zī jīn', 'vốn (tiền)', '我们需要更多的资金。', 'Wǒmen xūyào gèng duō de zījīn.', 'Chúng ta cần nhiều vốn hơn.'),
(2460, 5, 1265, '资料', 'zī liào', 'tư liệu', '这些资料非常重要。', 'Zhèxiē zīliào fēicháng zhòngyào.', 'Những tài liệu này rất quan trọng.'),
(2461, 5, 1266, '资源', 'zī yuán', 'nguồn tài nguyên', '这个国家资源丰富。', 'Zhège guójiā zīyuán fēngfù.', 'Quốc gia này có tài nguyên phong phú.'),
(2462, 5, 1267, '紫', 'zǐ', 'màu tím', '她穿了一件紫色的裙子。', 'Tā chuānle yī jiàn zǐsè de qúnzi.', 'Cô ấy mặc một chiếc váy màu tím.'),
(2463, 5, 1268, '自从', 'zì cóng', 'từ khi….', '自从那次事故以后，她变得很小心。', 'Zìcóng nà cì shìgù yǐhòu, tā biàn dé hěn xiǎoxīn.', 'Kể từ sau vụ tai nạn đó, cô ấy trở nên rất cẩn thận.'),
(2464, 5, 1269, '自动', 'zì dòng', 'tự động', '这个机器是自动的。', 'Zhège jīqì shì zìdòng de.', 'Cái máy này là tự động.'),
(2465, 5, 1270, '自豪', 'zì háo', 'tự hào, kiêu ngạo', '他为自己的成功感到自豪。', 'Tā wèi zìjǐ de chénggōng gǎndào zìháo.', 'Anh ấy cảm thấy tự hào về thành công của mình.'),
(2466, 5, 1271, '自觉', 'zì jué', 'tự giác', '你应该自觉遵守规定。', 'Nǐ yīnggāi zìjué zūnshǒu guīdìng.', 'Bạn nên tự giác tuân thủ các quy định.'),
(2467, 5, 1272, '自私', 'zì sī', 'ích kỉ', '他有点儿自私。', 'Tā yǒudiǎn er zìsī.', 'Anh ấy hơi ích kỷ.'),
(2468, 5, 1273, '自由', 'zì yóu', 'tự do', '在这个国家，人们享有自由。', 'Zài zhège guójiā, rénmen xiǎngyǒu zìyóu.', 'Ở quốc gia này, người dân có quyền tự do.'),
(2469, 5, 1274, '自愿', 'zì yuàn', 'tình nguyện, tự nguyện', '她自愿参加志愿者活动。', 'Tā zìyuàn cānjiā zhìyuàn zhě huódòng.', 'Cô ấy tình nguyện tham gia các hoạt động tình nguyện.'),
(2470, 5, 1275, '字母', 'zì mǔ', 'chữ cái', '英文的字母有二十六个。', 'Yīngwén de zìmǔ yǒu èrshíliù gè.', 'Bảng chữ cái tiếng Anh có 26 chữ cái.'),
(2471, 5, 1276, '字幕', 'zì mù', 'phụ đề', '电影有中文字幕。', 'Diànyǐng yǒu zhōngwén zìmù.', 'Bộ phim có phụ đề tiếng Trung.'),
(2472, 5, 1277, '综合', 'zōng hé', 'tổng hợp', '这次考试的内容是综合的。', 'Zhè cì kǎoshì de nèiróng shì zōnghé de.', 'Nội dung của kỳ thi này là tổng hợp.'),
(2473, 5, 1278, '总裁', 'zǒng cái', 'giám đốc', '他是公司的总裁。', 'Tā shì gōngsī de zǒngcái.', 'Anh ấy là tổng giám đốc của công ty.'),
(2474, 5, 1279, '总共', 'zǒng gòng', 'tổng cộng', '总共需要三天完成这个任务。', 'Zǒnggòng xūyào sān tiān wánchéng zhège rènwù.', 'Tổng cộng cần ba ngày để hoàn thành nhiệm vụ này.'),
(2475, 5, 1280, '总理', 'zǒng lǐ', 'thủ tướng', '总理发表了讲话。', 'Zǒnglǐ fābiǎole jiǎnghuà.', 'Thủ tướng đã phát biểu.'),
(2476, 5, 1281, '总算', 'zǒng suàn', 'rốt cuộc', '他总算找到了工作。', 'Tā zǒngsuàn zhǎodàole gōngzuò.', 'Cuối cùng anh ấy đã tìm được công việc.'),
(2477, 5, 1282, '总统', 'zǒng tǒng', 'tổng thống', '总统今天将发表演讲。', 'Zǒngtǒng jīntiān jiāng fābiǎo yǎnjiǎng.', 'Tổng thống sẽ phát biểu hôm nay.'),
(2478, 5, 1283, '总之', 'zǒng zhī', 'tóm lại', '总之，我们要好好努力。', 'Zǒngzhī, wǒmen yào hǎohǎo nǔlì.', 'Nói chung, chúng ta phải nỗ lực làm việc tốt.'),
(2479, 5, 1284, '阻止', 'zǔzhǐ', 'ngăn chặn, ngăn cản', '他们试图阻止这项计划。', 'Tāmen shìtú zǔzhǐ zhè xiàng jìhuà.', 'Họ đã cố gắng ngăn chặn kế hoạch này.'),
(2480, 5, 1285, '组', 'zǔ', 'tổ, cụm, nhóm', '我们组成了一个团队。', 'Wǒmen zǔchéngle yī gè tuánduì.', 'Chúng tôi đã thành lập một đội.'),
(2481, 5, 1286, '组成', 'zǔ chéng', 'tổ thành', '这两个部分组成了一个整体。', 'Zhè liǎng gè bùfen zǔchéngle yīgè zhěngtǐ.', 'Hai phần này tạo thành một tổng thể.'),
(2482, 5, 1287, '组合', 'zǔ hé', 'tổ hợp, tổ hợp thành, nhóm', '我们需要一个合理的组合。', 'Wǒmen xūyào yīgè hélǐ de zǔhé.', 'Chúng ta cần một sự kết hợp hợp lý.'),
(2483, 5, 1288, '组织', 'zǔ zhī', 'tổ chức', '他们组织了一个大型活动。', 'Tāmen zǔzhīle yīgè dàxíng huódòng.', 'Họ đã tổ chức một sự kiện lớn.'),
(2484, 5, 1289, '最初', 'zuì chū', 'ban đầu', '这是最初的设计方案。', 'Zhè shì zuìchū de shèjì fāng''àn.', 'Đây là kế hoạch thiết kế ban đầu.'),
(2485, 5, 1290, '醉', 'zuì', 'say, say đắm', '他喝酒后会很容易醉。', 'Tā hējiǔ hòu huì hěn róngyì zuì.', 'Anh ấy dễ say sau khi uống rượu.'),
(2486, 5, 1291, '尊敬', 'zūn jìng', 'tôn kính, kính trọng', '我们应该尊敬每一个人。', 'Wǒmen yīnggāi zūnjìng měi yīgè rén.', 'Chúng ta nên tôn trọng mỗi người.'),
(2487, 5, 1292, '遵守', 'zūn shǒu', 'tuân thủ', '请遵守交通规则。', 'Qǐng zūnshǒu jiāotōng guīzé.', 'Xin hãy tuân thủ các quy tắc giao thông.'),
(2488, 5, 1293, '作品', 'zuò pǐn', 'tác phẩm', '这部小说是他的最新作品。', 'Zhè bù xiǎoshuō shì tā de zuìxīn zuòpǐn.', 'Cuốn tiểu thuyết này là tác phẩm mới nhất của anh ấy.'),
(2489, 5, 1294, '作为', 'zuò wéi', 'coi là, làm, là', '作为老师，他很有责任心。', 'Zuòwéi lǎoshī, tā hěn yǒu zérèn xīn.', 'Với tư cách là giáo viên, anh ấy rất có trách nhiệm.'),
(2490, 5, 1295, '作文', 'zuò wén', 'bài viết', '我们需要写一篇作文。', 'Wǒmen xūyào xiě yī piān zuòwén.', 'Chúng ta cần viết một bài văn.'),
(2491, 6, 1, '哎哟', 'āiyō', 'ái chà', '哎哟，这个问题真是让人头疼。', 'āiyō, zhè gè wèntí zhēn shì ràng rén tóuténg.', 'Ôi chao, vấn đề này thật là nhức đầu.'),
(2492, 6, 2, '挨', 'ái', 'chịu đựng, bị', '他每天都要挨饿。', 'Tā měitiān dōu yào ái è.', 'Anh ấy phải chịu đói mỗi ngày.'),
(2493, 6, 3, '癌症', 'ái zhèng', 'ung thư', '她不幸患上了癌症。', 'tā bùxìng huàn shàng le áizhèng.', 'Cô ấy không may mắc bệnh ung thư.'),
(2494, 6, 4, '爱不释手', 'ài bù shì shǒu', 'yêu không rời tay', '这本书让他爱不释手。', 'zhè běn shū ràng tā àibùshìshǒu.', 'Cuốn sách này làm anh ấy không thể rời tay.'),
(2495, 6, 5, '爱戴', 'ài dài', 'yêu mến, kính trọng', '他深受大家的爱戴。', 'tā shēn shòu dàjiā de àidài.', 'Anh ấy được mọi người yêu mến.'),
(2496, 6, 6, '暧昧', 'ài mèi', 'mập mờ, không rõ ràng', '他们之间的关系有点暧昧。', 'tāmen zhījiān de guānxì yǒu diǎn àimèi.', 'Mối quan hệ giữa họ có chút mờ ám.'),
(2497, 6, 7, '安居乐业', 'ān jū lè yè', 'an cư lạc nghiệp', '他们在这里安居乐业。', 'tāmen zài zhèlǐ ānjūlèyè.', 'Họ sống an cư lạc nghiệp ở đây.'),
(2498, 6, 8, '安宁', 'ān níng', 'yên bình', '她喜欢安宁的生活。', 'tā xǐhuān ānníng de shēnghuó.', 'Cô ấy thích cuộc sống yên bình.'),
(2499, 6, 9, '安详', 'ān xiáng', 'bình thản, điềm tĩnh', '他总是表现得很安详。', 'tā zǒng shì biǎoxiàn de hěn ānxiáng.', 'Anh ấy luôn tỏ ra rất điềm tĩnh.'),
(2500, 6, 10, '安置', 'ān zhì', 'sắp xếp, bố trí', '我们需要为他们安置住房。', 'wǒmen xūyào wèi tāmen ānzhì zhùfáng.', 'Chúng ta cần sắp xếp chỗ ở cho họ.');
INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(2501, 6, 11, '案件', 'àn jiàn', 'vụ án', '这个案件非常复杂。', 'zhè gè ànjiàn fēicháng fùzá.', 'Vụ án này rất phức tạp.'),
(2502, 6, 12, '案例', 'àn lì', 'trường hợp, ví dụ', '这个案例很有参考价值。', 'zhè gè ànlì hěn yǒu cānkǎo jiàzhí.', 'Trường hợp này rất có giá trị tham khảo.'),
(2503, 6, 13, '按摩', 'àn mó', 'mát xa', '她每周都会去按摩。', 'tā měi zhōu dū huì qù ànmó.', 'Cô ấy đi mát-xa mỗi tuần.'),
(2504, 6, 14, '暗示', 'àn shì', 'ám hiệu, gợi ý', '他暗示我应该努力工作。', 'tā ànshì wǒ yīnggāi nǔlì gōngzuò.', 'Anh ấy gợi ý tôi nên làm việc chăm chỉ.'),
(2505, 6, 15, '昂贵', 'áng guì', 'đắt đỏ', '这块手表非常昂贵。', 'zhè kuài shǒubiǎo fēicháng ángguì.', 'Chiếc đồng hồ này rất đắt tiền.'),
(2506, 6, 16, '凹凸', 'āo tū', 'lồi lõm', '这条路很凹凸不平。', 'zhè tiáo lù hěn āotū bù píng.', 'Con đường này rất gồ ghề.'),
(2507, 6, 17, '熬', 'áo', 'nấu, chịu đựng', '她在厨房里熬了整夜。', 'tā zài chúfáng lǐ áo le zhěng yè.', 'Cô ấy đã nấu nướng cả đêm trong bếp.'),
(2508, 6, 18, '奥秘', 'ào mì', 'bí mật, huyền bí', '这个问题充满了奥秘。', 'zhè gè wèntí chōngmǎn le àomì.', 'Vấn đề này đầy bí ẩn.'),
(2509, 6, 19, '扒', 'bā', 'cào, móc, kéo', '他用力扒开了门。', 'tā yònglì bā kāi le mén.', 'Anh ấy đã cố gắng mở cửa.'),
(2510, 6, 20, '疤', 'bā', 'vết sẹo', '他脸上的疤很明显。', 'tā liǎn shàng de bā hěn míngxiǎn.', 'Vết sẹo trên mặt anh ấy rất rõ.'),
(2511, 6, 21, '巴不得', 'bā bu de', 'nóng lòng, mong mỏi', '我巴不得快点放假。', 'wǒ bābudé kuài diǎn fàngjià.', 'Tôi mong muốn nhanh chóng được nghỉ.'),
(2512, 6, 22, '巴结', 'bā jié', 'nịnh nọt, xu nịnh', '他总是喜欢巴结老板。', 'tā zǒng shì xǐhuān bājié lǎobǎn.', 'Anh ấy luôn thích nịnh nọt sếp.'),
(2513, 6, 23, '拔苗助长', 'bá miáo zhù zhǎng', 'đốt cháy giai đoạn', '这样做只会拔苗助长。', 'zhèyàng zuò zhǐ huì bámiáozhùzhǎng.', 'Làm như vậy chỉ là hại nhiều hơn lợi.'),
(2514, 6, 24, '把关', 'bǎ guān', 'trông coi, bảo vệ', '我们要严格把关质量。', 'wǒmen yào yángé bǎguān zhìliàng.', 'Chúng ta phải kiểm soát chất lượng nghiêm ngặt.'),
(2515, 6, 25, '把手', 'bǎ shǒu', 'tay cầm, tay nắm', '这个杯子的把手坏了。', 'zhè gè bēizi de bǎshǒu huài le.', 'Tay cầm của cái cốc này bị hỏng rồi.'),
(2516, 6, 26, '把戏', 'bǎ xì', 'trò biểu diễn, trò ảo thuật', '他总是喜欢耍把戏。', 'tā zǒng shì xǐhuān shuǎ bǎxì.', 'Anh ấy luôn thích biểu diễn trò ảo thuật.'),
(2517, 6, 27, '霸道', 'bà dào', 'bá đạo, hung hăng', '他的性格有点霸道。', 'tā de xìnggé yǒu diǎn bàdào.', 'Tính cách của anh ấy hơi độc đoán.'),
(2518, 6, 28, '罢工', 'bà gōng', 'đình công', '工人们决定罢工。', 'gōngrénmen juédìng bàgōng.', 'Công nhân quyết định đình công.'),
