INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(3001, 6, 511, '发财', 'fā cái', 'phát tài, làm giàu', '他梦想着有一天能够发财。', 'tā mèngxiǎng zhe yǒu yī tiān nénggòu fācái.', 'Anh ấy mơ ước một ngày nào đó sẽ phát tài.'),
(3002, 6, 512, '发呆', 'fā dāi', 'ngẩn ngơ, ngây dại', '他在课堂上发呆。', 'tā zài kètáng shàng fādāi.', 'Anh ấy thẫn thờ trong lớp học.'),
(3003, 6, 513, '发动', 'fā dòng', 'khởi động, phát động', '他发动了汽车。', 'tā fādòng le qìchē.', 'Anh ấy khởi động xe ô tô.'),
(3004, 6, 514, '发火', 'fā huǒ', 'nổi giận, bốc cháy', '她因为生气而发火。', 'tā yīnwèi shēngqì ér fāhuǒ.', 'Cô ấy tức giận nên nổi nóng.'),
(3005, 6, 515, '发觉', 'fā jué', 'phát hiện, nhận ra', '我发觉他有点奇怪。', 'wǒ fājué tā yǒudiǎn qíguài.', 'Tôi nhận thấy anh ấy có chút kỳ lạ.'),
(3006, 6, 516, '发射', 'fā shè', 'phóng, bắn ra', '火箭成功地发射了。', 'huǒjiàn chénggōng de fāshè le.', 'Tên lửa đã phóng thành công.'),
(3007, 6, 517, '发誓', 'fā shì', 'thề, tuyên thệ', '他发誓永远不会撒谎。', 'tā fāshì yǒngyuǎn bù huì sāhuǎng.', 'Anh ấy thề rằng sẽ không bao giờ nói dối.'),
(3008, 6, 518, '发行', 'fā xíng', 'phát hành', '新书即将发行。', 'xīn shū jíjiāng fāxíng.', 'Cuốn sách mới sắp được phát hành.'),
(3009, 6, 519, '发炎', 'fā yán', 'viêm, sưng tấy', '他的喉咙发炎了。', 'tā de hóulóng fāyán le.', 'Cổ họng của anh ấy bị viêm.'),
(3010, 6, 520, '发扬', 'fā yáng', 'phát huy', '我们应该发扬传统文化。', 'wǒmen yīnggāi fāyáng chuántǒng wénhuà.', 'Chúng ta nên phát huy văn hóa truyền thống.'),
(3011, 6, 521, '发育', 'fā yù', 'phát triển, trưởng thành', '婴儿在健康地发育。', 'yīng''ér zài jiànkāng de fāyù.', 'Em bé đang phát triển khỏe mạnh.'),
(3012, 6, 522, '法人', 'fǎ rén', 'pháp nhân', '公司是一个法人实体。', 'gōngsī shì yī gè fǎrén shítǐ.', 'Công ty là một pháp nhân.'),
(3013, 6, 523, '番', 'fān', 'lượt, đợt', '他经历了好几番挑战。', 'tā jīnglì le hǎo jǐ fān tiǎozhàn.', 'Anh ấy đã trải qua nhiều thử thách.'),
(3014, 6, 524, '翻', 'fān', 'lật, đảo', '请把书翻到第十页。', 'qǐng bǎ shū fān dào dì shí yè.', 'Vui lòng lật sách đến trang 10.'),
(3015, 6, 525, '繁华', 'fán huá', 'phồn hoa, sầm uất', '这座城市非常繁华。', 'zhè zuò chéngshì fēicháng fánhuá.', 'Thành phố này rất phồn hoa.'),
(3016, 6, 526, '繁忙', 'fán máng', 'bận rộn', '他每天的工作都很繁忙。', 'tā měitiān de gōngzuò dōu hěn fánmáng.', 'Công việc hàng ngày của anh ấy rất bận rộn.'),
(3017, 6, 527, '繁体字', 'fán tǐ zì', 'chữ phồn thể', '繁体字在台湾仍然使用。', 'fántǐzì zài Táiwān réngrán shǐyòng.', 'Chữ phồn thể vẫn được sử dụng ở Đài Loan.'),
(3018, 6, 528, '繁殖', 'fán zhí', 'sinh sản, nhân giống', '细菌在适宜的条件下繁殖。', 'xìjūn zài shìyí de tiáojiàn xià fánzhí.', 'Vi khuẩn sinh sản trong điều kiện thích hợp.'),
(3019, 6, 529, '反驳', 'fǎn bó', 'phản bác, bác bỏ', '他反驳了对方的观点。', 'tā fǎnbó le duìfāng de guāndiǎn.', 'Anh ấy phản bác quan điểm của đối phương.'),
(3020, 6, 530, '反常', 'fǎn cháng', 'bất thường', '今天天气反常地热。', 'jīntiān tiānqì fǎncháng de rè.', 'Thời tiết hôm nay nóng bất thường.'),
(3021, 6, 531, '反倒', 'fǎn dào', 'ngược lại, trái lại', '事情反倒变得更糟了。', 'shìqíng fǎndào biàn de gèng zāo le.', 'Sự việc ngược lại trở nên tồi tệ hơn.'),
(3022, 6, 532, '反动', 'fǎn dòng', 'phản động', '他们是反动组织。', 'tāmen shì fǎndòng zǔzhī.', 'Họ là tổ chức phản động.'),
(3023, 6, 533, '反感', 'fǎn gǎn', 'phản cảm, ghét', '他的行为让人反感。', 'tā de xíngwéi ràng rén fǎngǎn.', 'Hành vi của anh ấy khiến người ta ghét.'),
(3024, 6, 534, '反抗', 'fǎn kàng', 'phản kháng, chống cự', '人民反抗了独裁政权。', 'rénmín fǎnkàng le dúcái zhèngquán.', 'Người dân đã chống lại chế độ độc tài.'),
(3025, 6, 535, '反馈', 'fǎn kuì', 'phản hồi', '这个产品收到了很多反馈。', 'zhège chǎnpǐn shōudào le hěn duō fǎnkuì.', 'Sản phẩm này đã nhận được nhiều phản hồi.'),
(3026, 6, 536, '反面', 'fǎn miàn', 'mặt trái, mặt khác', '事情总有反面。', 'shìqíng zǒng yǒu fǎnmiàn.', 'Mọi chuyện đều có mặt trái.'),
(3027, 6, 537, '反射', 'fǎn shè', 'phản xạ, phản chiếu', '镜子能反射光线。', 'jìngzi néng fǎnshè guāngxiàn.', 'Gương có thể phản xạ ánh sáng.'),
(3028, 6, 538, '反思', 'fǎn sī', 'suy nghĩ lại, ngẫm lại', '我们需要反思自己的错误。', 'wǒmen xūyào fǎnsī zìjǐ de cuòwù.', 'Chúng ta cần suy ngẫm về lỗi lầm của mình.'),
(3029, 6, 539, '反问', 'fǎn wèn', 'hỏi ngược lại', '他反问道：“你为什么不试试？”', 'tā fǎnwèn dào: "nǐ wèishéme bù shìshi?"', 'Anh ấy hỏi ngược lại: "Tại sao bạn không thử?"'),
(3030, 6, 540, '反之', 'fǎn zhī', 'ngược lại', '反之，结果可能会不同。', 'fǎnzhī, jiéguǒ kěnéng huì bùtóng.', 'Ngược lại, kết quả có thể sẽ khác.'),
(3031, 6, 541, '范畴', 'fàn chóu', 'phạm trù, lĩnh vực', '这属于哲学的范畴。', 'zhè shǔyú zhéxué de fànchóu.', 'Điều này thuộc phạm trù triết học.'),
(3032, 6, 542, '泛滥', 'fàn làn', 'lan tràn, tràn lan', '洪水泛滥成灾。', 'hóngshuǐ fànlàn chéng zāi.', 'Lũ lụt lan tràn gây ra thảm họa.'),
(3033, 6, 543, '贩卖', 'fàn mài', 'buôn bán, buôn lậu', '他被指控贩卖毒品。', 'tā bèi zhǐkòng fànmài dúpǐn.', 'Anh ấy bị buộc tội buôn bán ma túy.'),
(3034, 6, 544, '方位', 'fāng wèi', 'phương vị, vị trí', '请告诉我这个建筑的方位。', 'qǐng gàosù wǒ zhège jiànzhù de fāngwèi.', 'Vui lòng cho tôi biết vị trí của tòa nhà này.'),
(3035, 6, 545, '方言', 'fāng yán', 'phương ngữ', '他说的方言我听不懂。', 'tā shuō de fāngyán wǒ tīng bù dǒng.', 'Tôi không hiểu phương ngữ mà anh ấy nói.'),
(3036, 6, 546, '方针', 'fāng zhēn', 'phương châm, chính sách', '公司已经制定了新的方针。', 'gōngsī yǐjīng zhìdìng le xīn de fāngzhēn.', 'Công ty đã thiết lập phương châm mới.'),
(3037, 6, 547, '防守', 'fáng shǒu', 'phòng thủ', '守门员负责防守球门。', 'shǒuményuán fùzé fángshǒu qiúmén.', 'Thủ môn chịu trách nhiệm bảo vệ khung thành.'),
(3038, 6, 548, '防疫', 'fáng yì', 'phòng dịch', '我们应该加强防疫措施。', 'wǒmen yīnggāi jiāqiáng fángyì cuòshī.', 'Chúng ta nên tăng cường các biện pháp phòng dịch.'),
(3039, 6, 549, '防御', 'fáng yù', 'phòng ngự, phòng vệ', '城墙用来防御敌人。', 'chéngqiáng yòng lái fángyù dírén.', 'Thành trì được dùng để phòng ngự kẻ thù.'),
(3040, 6, 550, '防止', 'fáng zhǐ', 'ngăn ngừa, phòng chống', '请防止这种情况发生。', 'qǐng fángzhǐ zhè zhǒng qíngkuàng fāshēng.', 'Vui lòng ngăn chặn tình huống này xảy ra.'),
(3041, 6, 551, '防治', 'fáng zhì', 'phòng trị', '我们需要防治这种疾病。', 'wǒmen xūyào fángzhì zhè zhǒng jíbìng.', 'Chúng ta cần phòng và chữa căn bệnh này.'),
(3042, 6, 552, '纺织', 'fǎng zhī', 'dệt, dệt may', '这个地区的纺织业非常发达。', 'zhège dìqū de fǎngzhī yè fēicháng fādá.', 'Ngành dệt may ở khu vực này rất phát triển.'),
(3043, 6, 553, '放大', 'fàng dà', 'phóng to', '科学家放大了细菌的图像。', 'kēxuéjiā fàngdà le xìjūn de túxiàng.', 'Các nhà khoa học đã phóng to hình ảnh của vi khuẩn.'),
(3044, 6, 554, '放射', 'fàng shè', 'phát xạ, bức xạ', '这种物质能放射出有害的辐射。', 'zhè zhǒng wùzhì néng fàngshè chū yǒuhài de fúshè.', 'Chất này có thể phát ra bức xạ có hại.'),
(3045, 6, 555, '放手', 'fàng shǒu', 'buông tay, thả tay', '请放手，我自己能行。', 'qǐng fàngshǒu, wǒ zìjǐ néng xíng.', 'Vui lòng buông tay, tôi có thể tự làm được.'),
(3046, 6, 556, '非法', 'fēi fǎ', 'phi pháp, bất hợp pháp', '贩卖毒品是非法的。', 'fànmài dúpǐn shì fēifǎ de.', 'Buôn bán ma túy là bất hợp pháp.'),
(3047, 6, 557, '飞禽走兽', 'fēi qín zǒu shòu', 'chim bay thú chạy', '这个地方有很多飞禽走兽。', 'zhège dìfāng yǒu hěn duō fēiqín zǒushòu.', 'Nơi này có nhiều chim bay và thú chạy.'),
(3048, 6, 558, '飞翔', 'fēi xiáng', 'bay lượn', '鹰在空中自由飞翔。', 'yīng zài kōngzhōng zìyóu fēixiáng.', 'Đại bàng bay lượn tự do trên không trung.'),
(3049, 6, 559, '飞跃', 'fēi yuè', 'bay vọt, nhảy vọt', '这项技术的发展飞跃。', 'zhè xiàng jìshù de fāzhǎn fēiyuè.', 'Sự phát triển của công nghệ này tiến bộ vượt bậc.'),
(3050, 6, 560, '肥沃', 'féi wò', 'màu mỡ, phì nhiêu', '这片土地非常肥沃。', 'zhè piàn tǔdì fēicháng féiwò.', 'Mảnh đất này rất màu mỡ.'),
(3051, 6, 561, '诽谤', 'fěi bàng', 'phỉ báng, vu khống', '他因为诽谤被起诉了。', 'tā yīnwèi fěibàng bèi qǐsù le.', 'Anh ấy bị kiện vì tội phỉ báng.'),
(3052, 6, 562, '匪徒', 'fěi tú', 'kẻ cướp, kẻ xấu', '匪徒抢劫了银行。', 'fěitú qiǎngjié le yínháng.', 'Bọn cướp đã cướp ngân hàng.'),
(3053, 6, 563, '废除', 'fèi chú', 'bãi bỏ, hủy bỏ', '政府决定废除这项法律。', 'zhèngfǔ juédìng fèichú zhè xiàng fǎlǜ.', 'Chính phủ quyết định bãi bỏ luật này.'),
(3054, 6, 564, '沸腾', 'fèi téng', 'sôi, sục sôi', '水在沸腾。', 'shuǐ zài fèiténg.', 'Nước đang sôi.'),
(3055, 6, 565, '废墟', 'fèi xū', 'tàn tích, đống đổ nát', '地震后，城市变成了废墟。', 'dìzhèn hòu, chéngshì biàn chéng le fèixū.', 'Sau trận động đất, thành phố trở thành đống đổ nát.'),
(3056, 6, 566, '分辨', 'fēn biàn', 'phân biệt', '我能分辨出这两种颜色。', 'wǒ néng fēnbiàn chū zhè liǎng zhǒng yánsè.', 'Tôi có thể phân biệt hai màu này.'),
(3057, 6, 567, '分寸', 'fēn cun', 'chừng mực, mức độ', '做事要掌握好分寸。', 'Zuòshì yào zhǎngwò hǎo fēncun.', 'Làm việc phải biết chừng mực.'),
(3058, 6, 568, '吩咐', 'fēn fù', 'dặn dò, căn dặn', '他吩咐我去买些水果。', 'tā fēnfù wǒ qù mǎi xiē shuǐguǒ.', 'Anh ấy bảo tôi đi mua một ít trái cây.'),
(3059, 6, 569, '分红', 'fēn hóng', 'chia lãi, chia lợi tức', '公司分红给每个员工。', 'gōngsī fēnhóng gěi měi gè yuángōng.', 'Công ty chia cổ tức cho từng nhân viên.'),
(3060, 6, 570, '分解', 'fēn jiě', 'phân giải, phân tích', '科学家分解了这个化合物。', 'kēxuéjiā fēnjiě le zhège huàhéwù.', 'Các nhà khoa học đã phân giải hợp chất này.'),
(3061, 6, 571, '分裂', 'fēn liè', 'phân liệt, tách rời', '这个国家面临分裂的危机。', 'zhège guójiā miànlín fēnliè de wēijī.', 'Quốc gia này đang đối mặt với nguy cơ chia rẽ.'),
(3062, 6, 572, '分泌', 'fēn mì', 'tiết ra, bài tiết', '身体会分泌荷尔蒙。', 'shēntǐ huì fēnmì hè''ěrméng.', 'Cơ thể sẽ tiết ra hormone.'),
(3063, 6, 573, '分明', 'fēn míng', 'rõ ràng, phân minh', '事实分明，他说的都是谎言。', 'shìshí fēnmíng, tā shuō de dōu shì huǎngyán.', 'Sự thật rõ ràng, những gì anh ấy nói đều là nói dối.'),
(3064, 6, 574, '分歧', 'fēn qí', 'khác biệt, bất đồng', '我们在这个问题上有分歧。', 'wǒmen zài zhège wèntí shàng yǒu fēnqí.', 'Chúng ta có sự khác biệt về vấn đề này.'),
(3065, 6, 575, '分散', 'fēn sàn', 'phân tán, tản ra', '他因为工作的原因必须分散注意力。', 'tā yīnwèi gōngzuò de yuányīn bìxū fēnsàn zhùyìlì.', 'Anh ấy phải phân tán sự chú ý vì công việc.'),
(3066, 6, 576, '分手', 'fēn shǒu', 'chia tay, chia ly', '他们决定分手了。', 'tāmen juédìng fēnshǒu le.', 'Họ quyết định chia tay.'),
(3067, 6, 577, '坟墓', 'fén mù', 'mộ phần, phần mộ', '这个坟墓已有百年历史。', 'zhège fénmù yǐ yǒu bǎinián lìshǐ.', 'Ngôi mộ này đã có lịch sử trăm năm.'),
(3068, 6, 578, '粉末', 'fěn mò', 'bột, vụn', '这药片可以变成粉末。', 'zhè yàopiàn kěyǐ biàn chéng fěnmò.', 'Viên thuốc này có thể biến thành bột.'),
(3069, 6, 579, '粉色', 'fěn sè', 'màu hồng', '她喜欢粉色的衣服。', 'tā xǐhuan fěnsè de yīfu.', 'Cô ấy thích quần áo màu hồng.'),
(3070, 6, 580, '粉碎', 'fěn suì', 'nghiền nát, phá tan', '这台机器可以粉碎垃圾。', 'zhè tái jīqì kěyǐ fěnsuì lājī.', 'Cỗ máy này có thể nghiền nát rác.'),
(3071, 6, 581, '分量', 'fèn liàng', 'trọng lượng, khối lượng', '这个包装的分量很足。', 'zhège bāozhuāng de fènliàng hěn zú.', 'Bao bì này có trọng lượng rất đủ.'),
(3072, 6, 582, '风暴', 'fēng bào', 'bão táp, cơn bão', '海上风暴即将来临。', 'hǎi shàng fēngbào jíjiāng láilín.', 'Cơn bão trên biển sắp đến.'),
(3073, 6, 583, '封闭', 'fēng bì', 'phong bế, đóng kín', '他把门窗封闭了。', 'tā bǎ ménchuāng fēngbì le.', 'Anh ấy đã đóng cửa sổ lại.'),
(3074, 6, 584, '风度', 'fēng dù', 'phong độ, tư cách', '他的风度非常优雅。', 'tā de fēngdù fēicháng yōuyǎ.', 'Phong cách của anh ấy rất lịch lãm.'),
(3075, 6, 585, '风光', 'fēng guāng', 'phong cảnh, cảnh đẹp', '我们在山顶上欣赏风光。', 'wǒmen zài shāndǐng shàng xīnshǎng fēngguāng.', 'Chúng tôi ngắm cảnh trên đỉnh núi.'),
