(3235, 6, 745, '棍棒', 'gùn bàng', 'gậy, côn', '他用棍棒打破了窗户。', 'Tā yòng gùnbàng dǎpò le chuānghù.', 'Anh ấy dùng gậy đập vỡ cửa sổ.'),
(3236, 6, 746, '国防', 'guó fáng', 'quốc phòng', '国防是国家安全的重要保障。', 'Guófáng shì guójiā ānquán de zhòngyào bǎozhàng.', 'Quốc phòng là đảm bảo quan trọng cho an ninh quốc gia.'),
(3237, 6, 747, '国务院', 'guó wù yuàn', 'quốc vụ viện', '国务院发布了新的政策。', 'Guówùyuàn fābù le xīn de zhèngcè.', 'Quốc vụ viện đã ban hành chính sách mới.'),
