(3246, 6, 756, '过于', 'guò yú', 'quá, hơn', '这件衣服过于紧了。', 'Zhè jiàn yīfú guòyú jǐn le.', 'Chiếc áo này quá chật.'),
(3247, 6, 757, '嗨', 'hāi', 'chào, này', '嗨，大家好！', 'Hāi, dàjiā hǎo!', 'Chào mọi người!'),
