(3763, 6, 1273, '面貌', 'miànmào', 'Diện mạo, dung mạo', '他的面貌变了很多。', 'Tā de miànmào biàn le hěn duō.', 'Diện mạo của anh ấy đã thay đổi nhiều.'),
(3764, 6, 1274, '面子', 'miànzi', 'Thể diện', '他很在意自己的面子。', 'Tā hěn zàiyì zìjǐ de miànzi.', 'Anh ấy rất quan tâm đến thể diện của mình.'),
(3765, 6, 1275, '描绘', 'miáohuì', 'Miêu tả', '他描绘了一幅美丽的画。', 'Tā miáohuì le yī fú měilì de huà.', 'Anh ấy vẽ một bức tranh đẹp.'),
(3766, 6, 1276, '渺小', 'miǎoxiǎo', 'Nhỏ bé', '这个村庄非常渺小。', 'Zhège cūnzhuāng fēicháng miǎoxiǎo.', 'Ngôi làng này rất nhỏ bé.'),
(3767, 6, 1277, '蔑视', 'mièshì', 'Coi thường, khinh miệt', '他蔑视别人的意见。', 'Tā mièshì biérén de yìjiàn.', 'Anh ấy khinh thường ý kiến của người khác.'),
(3768, 6, 1278, '灭亡', 'mièwáng', 'Diệt vong', '这个王朝灭亡了。', 'Zhège wángcháo mièwáng le.', 'Triều đại này đã diệt vong.'),
(3769, 6, 1279, '民间', 'mínjiān', 'Dân gian', '民间故事很有趣。', 'Mínjiān gùshì hěn yǒuqù.', 'Truyện dân gian rất thú vị.'),
(3770, 6, 1280, '民用', 'mínyòng', 'Dân dụng', '这些产品主要是民用的。', 'Zhèxiē chǎnpǐn zhǔyào shì mínyòng de.', 'Những sản phẩm này chủ yếu là dân dụng.'),
(3771, 6, 1281, '敏感', 'mǐngǎn', 'Nhạy cảm', '他对外界非常敏感。', 'Tā duì wàijiè fēicháng mǐngǎn.', 'Anh ấy rất nhạy cảm với thế giới bên ngoài.'),
(3772, 6, 1282, '敏捷', 'mǐnjié', 'Nhanh nhẹn', '她的动作非常敏捷。', 'Tā de dòngzuò fēicháng mǐnjié.', 'Động tác của cô ấy rất nhanh nhẹn.'),
(3773, 6, 1283, '敏锐', 'mǐnruì', 'Nhạy bén', '他的思维非常敏锐。', 'Tā de sīwéi fēicháng mǐnruì.', 'Tư duy của anh ấy rất sắc bén.'),
(3774, 6, 1284, '名次', 'míngcì', 'Thứ hạng', '比赛名次已经公布。', 'Bǐsài míngcì yǐjīng gōngbù.', 'Thứ hạng của cuộc thi đã được công bố.'),
(3775, 6, 1285, '名额', 'míng''é', 'Số người, số lượng quy định', '这个活动有固定的名额。', 'Zhège huódòng yǒu gùdìng de míng''é.', 'Hoạt động này có số lượng chỗ cố định.'),
(3776, 6, 1286, '名副其实', 'míngfùqíshí', 'Danh xứng kỳ thực', '他是名副其实的专家。', 'Tā shì míngfùqíshí de zhuānjiā.', 'Anh ấy là chuyên gia thực thụ.'),
(3777, 6, 1287, '明明', 'míngmíng', 'Rõ ràng', '他明明知道却装作不懂。', 'Tā míngmíng zhīdào què zhuāngzuò bù dǒng.', 'Anh ấy rõ ràng biết nhưng lại giả vờ không biết.'),
(3778, 6, 1288, '名誉', 'míngyù', 'Danh dự', '他的名誉受到了损害。', 'Tā de míngyù shòudào le sǔnhài.', 'Danh tiếng của anh ấy bị tổn hại.'),
(3779, 6, 1289, '命名', 'mìngmíng', 'Đặt tên', '我们需要给这个产品命名。', 'Wǒmen xūyào gěi zhège chǎnpǐn mìngmíng.', 'Chúng ta cần đặt tên cho sản phẩm này.'),
(3780, 6, 1290, '摸索', 'mōsuǒ', 'Mò mẫm', '他在黑暗中摸索前行。', 'Tā zài hēi''àn zhōng mōsuǒ qiánxíng.', 'Anh ấy dò dẫm tiến về phía trước trong bóng tối.'),
(3781, 6, 1291, '膜', 'mó', 'Màng', '显微镜下可以看到膜。', 'Xiǎnwéijìng xià kěyǐ kàn dào mó.', 'Có thể nhìn thấy màng dưới kính hiển vi.'),
(3782, 6, 1292, '摩擦', 'mócā', 'Ma sát, cọ sát', '他们之间摩擦不断。', 'Tāmen zhī jiān mócā bùduàn.', 'Giữa họ không ngừng có xích mích.'),
(3783, 6, 1293, '模范', 'mófàn', 'Gương mẫu', '他是一个模范学生。', 'Tā shì yī gè mófàn xuéshēng.', 'Anh ấy là một học sinh gương mẫu.'),
(3784, 6, 1294, '魔鬼', 'móguǐ', 'Ma quỷ', '电影里的魔鬼吓坏了我。', 'Diànyǐng lǐ de móguǐ xià huài le wǒ.', 'Con quỷ trong phim khiến tôi sợ hãi.'),
(3785, 6, 1295, '磨合', 'móhé', 'Mài giũa, hoà hợp', '他们需要时间磨合。', 'Tāmen xūyào shíjiān móhé.', 'Họ cần thời gian để hòa hợp.'),
(3786, 6, 1296, '模式', 'móshì', 'Mô thức, kiểu mẫu', '这种模式很受欢迎。', 'Zhè zhǒng móshì hěn shòu huānyíng.', 'Mô hình này rất được ưa chuộng.'),
(3787, 6, 1297, '魔术', 'móshù', 'Ảo thuật', '他的魔术表演很精彩。', 'Tā de móshù biǎoyǎn hěn jīngcǎi.', 'Màn biểu diễn ảo thuật của anh ấy rất xuất sắc.'),
(3788, 6, 1298, '模型', 'móxíng', 'Mô hình', '这个模型很逼真。', 'Zhège móxíng hěn bīzhēn.', 'Mô hình này rất chân thực.'),
(3789, 6, 1299, '抹杀', 'mǒshā', 'Phủ nhận, xoá bỏ', '他们试图抹杀证据。', 'Tāmen shìtú mǒshā zhèngjù.', 'Họ cố gắng xóa bỏ chứng cứ.'),
(3790, 6, 1300, '莫名其妙', 'mòmíngqímiào', 'Không thể hiểu nổi', '他突然莫名其妙地笑了起来。', 'Tā tūrán mòmíngqímiào de xiào le qǐlái.', 'Anh ấy đột nhiên cười mà không rõ lý do.'),
(3791, 6, 1301, '默默', 'mòmò', 'Lặng lẽ, âm thầm', '他默默地离开了房间。', 'Tā mòmò de líkāi le fángjiān.', 'Anh ấy lặng lẽ rời khỏi phòng.'),
(3792, 6, 1302, '墨水儿', 'mòshuǐr', 'Mực viết', '这瓶墨水儿很贵。', 'Zhè píng mòshuǐr hěn guì.', 'Lọ mực này rất đắt.'),
(3793, 6, 1303, '谋求', 'móuqiú', 'Mưu cầu', '他正在谋求新的工作机会。', 'Tā zhèngzài móuqiú xīn de gōngzuò jīhuì.', 'Anh ấy đang tìm kiếm cơ hội công việc mới.'),
(3794, 6, 1304, '模样', 'múyàng', 'Hình dáng, dáng vẻ', '她的模样很像她的母亲。', 'Tā de múyàng hěn xiàng tā de mǔqīn.', 'Vẻ ngoài của cô ấy rất giống mẹ cô ấy.'),
(3795, 6, 1305, '母语', 'mǔyǔ', 'Tiếng mẹ đẻ', '他的母语是英语。', 'Tā de mǔyǔ shì yīngyǔ.', 'Tiếng mẹ đẻ của anh ấy là tiếng Anh.'),
(3796, 6, 1306, '目睹', 'mùdǔ', 'Mắt thấy, chứng kiến', '我亲眼目睹了事故发生。', 'Wǒ qīnyǎn mùdǔ le shìgù fāshēng.', 'Tôi đã tận mắt chứng kiến tai nạn xảy ra.'),
(3797, 6, 1307, '目光', 'mùguāng', 'Ánh mắt', '他目光坚定地看着前方。', 'Tā mùguāng jiāndìng de kàn zhe qiánfāng.', 'Anh ấy nhìn chằm chằm về phía trước với ánh mắt kiên định.'),
(3798, 6, 1308, '沐浴', 'mùyù', 'Tắm gội', '他喜欢在早晨沐浴阳光。', 'Tā xǐhuān zài zǎochén mùyù yángguāng.', 'Anh ấy thích tắm nắng vào buổi sáng.'),
(3799, 6, 1309, '拿手', 'náshǒu', 'Giỏi, sở trường', '她很拿手做蛋糕。', 'Tā hěn náshǒu zuò dàngāo.', 'Cô ấy rất giỏi làm bánh.'),
(3800, 6, 1310, '纳闷儿', 'nàmènr', 'Bồn chồn, khó hiểu', '他感到有点纳闷儿。', 'Tā gǎndào yǒudiǎn nàmènr.', 'Anh ấy cảm thấy hơi thắc mắc.'),
(3801, 6, 1311, '耐用', 'nàiyòng', 'Bền, dùng lâu', '这种材料非常耐用。', 'Zhè zhǒng cáiliào fēicháng nàiyòng.', 'Loại vật liệu này rất bền.'),
(3802, 6, 1312, '难得', 'nándé', 'Khó có được, hiếm có', '他难得回家一次。', 'Tā nándé huíjiā yī cì.', 'Anh ấy hiếm khi về nhà một lần.'),
(3803, 6, 1313, '难堪', 'nánkān', 'Khó chịu, khó xử', '他的表现让人难堪。', 'Tā de biǎoxiàn ràng rén nánkān.', 'Biểu hiện của anh ấy khiến người ta khó xử.'),
(3804, 6, 1314, '难免', 'nánmiǎn', 'Khó tránh, khó khỏi', '犯错误是难免的。', 'Fàn cuòwù shì nánmiǎn de.', 'Sai lầm là điều khó tránh khỏi.'),
