(3808, 6, 1318, '内幕', 'nèimù', 'Bên trong, nội tình', '我不知道这件事的内幕。', 'Wǒ bù zhīdào zhè jiàn shì de nèimù.', 'Tôi không biết nội tình của chuyện này.'),
(3809, 6, 1319, '内在', 'nèizài', 'Nội tại, bên trong', '她有丰富的内在美。', 'Tā yǒu fēngfù de nèizài měi.', 'Cô ấy có vẻ đẹp nội tâm phong phú.'),
(3810, 6, 1320, '能量', 'néngliàng', 'Năng lượng', '阳光给我们带来了能量。', 'Yángguāng gěi wǒmen dàilái le néngliàng.', 'Ánh sáng mặt trời mang lại năng lượng cho chúng ta.'),
(3811, 6, 1321, '嗯', 'ń', 'Ừ, ừm', '嗯，我明白了。', 'Ń, wǒ míngbái le.', 'Ừm, tôi hiểu rồi.'),
(3812, 6, 1322, '拟定', 'nǐdìng', 'Đề ra, vạch ra', '他们正在拟定新计划。', 'Tāmen zhèngzài nǐdìng xīn jìhuà.', 'Họ đang lập kế hoạch mới.'),
