(3817, 6, 1327, '凝聚', 'níngjù', 'Ngưng tụ', '团队需要凝聚力。', 'Tuánduì xūyào níngjùlì.', 'Đội cần sự gắn kết.'),
(3818, 6, 1328, '凝视', 'níngshì', 'Nhìn chằm chằm', '她凝视着远方的山脉。', 'Tā níngshì zhe yuǎnfāng de shānmài.', 'Cô ấy nhìn chăm chú vào dãy núi ở xa.'),
