(3835, 6, 1345, '排放', 'páifàng', 'Thải ra, xả thải', '这家工厂排放大量废气。', 'Zhè jiā gōngchǎng páifàng dàliàng fèiqì.', 'Nhà máy này thải ra một lượng lớn khí thải.'),
(3836, 6, 1346, '徘徊', 'páihuái', 'Đi loanh quanh, lưỡng lự', '他在街上徘徊。', 'Tā zài jiē shàng páihuái.', 'Anh ấy đi lại lững thững trên phố.'),
(3837, 6, 1347, '派别', 'pàibié', 'Phái, bè phái', '他们是不同的派别。', 'Tāmen shì bùtóng de pàibié.', 'Họ thuộc các phe phái khác nhau.'),
(3838, 6, 1348, '派遣', 'pàiqiǎn', 'Phái đi, cử đi', '公司派遣他去国外出差。', 'Gōngsī pàiqiǎn tā qù guówài chūchāi.', 'Công ty cử anh ấy đi công tác nước ngoài.'),
(3839, 6, 1349, '攀登', 'pāndēng', 'Leo, trèo', '他喜欢攀登高山。', 'Tā xǐhuān pāndēng gāoshān.', 'Anh ấy thích leo núi.'),
(3840, 6, 1350, '盘旋', 'pánxuán', 'Lượn quanh', '直升机在空中盘旋。', 'Zhíshēngjī zài kōngzhōng pánxuán.', 'Trực thăng bay vòng trên không.'),
