(3924, 6, 1434, '器材', 'qìcái', 'Thiết bị, dụng cụ', '运动器材已经准备好了。', 'Yùndòng qìcái yǐjīng zhǔnbèi hǎo le.', 'Thiết bị thể thao đã sẵn sàng.'),
(3925, 6, 1435, '气概', 'qìgài', 'Khí phách', '他有很大的气概。', 'Tā yǒu hěn dà de qìgài.', 'Anh ấy có khí chất rất mạnh mẽ.'),
(3926, 6, 1436, '气功', 'qìgōng', 'Khí công', '他在练气功。', 'Tā zài liàn qìgōng.', 'Anh ấy đang tập khí công.'),
(3927, 6, 1437, '器官', 'qìguān', 'Cơ quan (cơ thể)', '人体的器官很复杂。', 'Réntǐ de qìguān hěn fùzá.', 'Cơ quan của cơ thể người rất phức tạp.'),
(3928, 6, 1438, '迄今为止', 'qìjīnwéizhǐ', 'Cho đến nay', '迄今为止，一切顺利。', 'Qìjīn wéizhǐ, yīqiè shùnlì.', 'Cho đến nay, mọi thứ đều suôn sẻ.'),
(3929, 6, 1439, '气魄', 'qìpò', 'Khí phách, dũng khí', '他的气魄令人敬佩。', 'Tā de qìpò lìng rén jìngpèi.', 'Khí phách của anh ấy làm mọi người khâm phục.'),
(3930, 6, 1440, '气色', 'qìsè', 'Thần sắc', '他的气色很好。', 'Tā de qìsè hěn hǎo.', 'Sắc mặt của anh ấy rất tốt.'),
(3931, 6, 1441, '气势', 'qìshì', 'Khí thế', '他的气势很强。', 'Tā de qìshì hěn qiáng.', 'Khí thế của anh ấy rất mạnh.'),
(3932, 6, 1442, '气味', 'qìwèi', 'Mùi hương, mùi vị', '这花闻起来有特殊的气味。', 'Zhè huā wén qǐlái yǒu tèshū de qìwèi.', 'Hoa này có mùi đặc biệt khi ngửi.'),
(3933, 6, 1443, '气象', 'qìxiàng', 'Khí tượng', '气象预报说今天有雨。', 'Qìxiàng yùbào shuō jīntiān yǒu yǔ.', 'Dự báo thời tiết nói hôm nay có mưa.'),
(3934, 6, 1444, '气压', 'qìyā', 'Áp suất không khí', '我们要考虑气压变化。', 'Wǒmen yào kǎolǜ qìyā biànhuà.', 'Chúng ta phải cân nhắc sự thay đổi áp suất không khí.'),
(3935, 6, 1445, '掐', 'qiā', 'Véo, ngắt', '她掐了一朵花。', 'Tā qiā le yī duǒ huā.', 'Cô ấy ngắt một bông hoa.'),
(3936, 6, 1446, '恰当', 'qiàdàng', 'Thích hợp, hợp lý', '这次会议的安排非常恰当。', 'Zhè cì huìyì de ānpái fēicháng qiàdàng.', 'Sắp xếp của cuộc họp lần này rất hợp lý.'),
(3937, 6, 1447, '恰到好处', 'qiàdàohǎochù', 'Vừa vặn, đúng chỗ', '他做事总是恰到好处。', 'Tā zuò shì zǒng shì qià dào hǎochù.', 'Anh ấy luôn làm mọi việc rất khéo léo.'),
(3938, 6, 1448, '恰巧', 'qiàqiǎo', 'Đúng lúc, khéo léo', '恰巧我们有相同的兴趣爱好。', 'Qiàqiǎo wǒmen yǒu xiāngtóng de xìngqù àihào.', 'Tình cờ chúng ta có cùng sở thích.'),
(3939, 6, 1449, '洽谈', 'qiàtán', 'Thảo luận, bàn bạc', '他们在洽谈合作事宜。', 'Tāmen zài qiàtán hézuò shìyí.', 'Họ đang thảo luận về hợp tác.'),
(3940, 6, 1450, '牵扯', 'qiānchě', 'Dính líu, liên lụy', '这个问题牵扯到很多人。', 'Zhège wèntí qiānchě dào hěn duō rén.', 'Vấn đề này liên quan đến nhiều người.'),
(3941, 6, 1451, '签订', 'qiāndìng', 'Ký kết', '他们签订了合同。', 'Tāmen qiāndìng le hétóng.', 'Họ đã ký hợp đồng.'),
(3942, 6, 1452, '千方百计', 'qiānfāngbǎijì', 'Trăm phương ngàn kế', '我们千方百计地解决问题。', 'Wǒmen qiānfāng-bǎijì de jiějué wèntí.', 'Chúng tôi cố gắng hết sức để giải quyết vấn đề.'),
(3943, 6, 1453, '迁就', 'qiānjiù', 'Nhường nhịn, nhún nhường', '他总是迁就别人。', 'Tā zǒng shì qiānjiù biérén.', 'Anh ấy luôn nhường nhịn người khác.'),
(3944, 6, 1454, '签署', 'qiānshǔ', 'Ký, phê chuẩn', '双方签署了协议。', 'Shuāngfāng qiānshǔ le xiéyì.', 'Hai bên đã ký thỏa thuận.'),
(3945, 6, 1455, '迁徙', 'qiānxǐ', 'Di cư, chuyển chỗ ở', '动物在季节变化时会迁徙。', 'Dòngwù zài jìjié biànhuà shí huì qiānxǐ.', 'Động vật sẽ di cư khi thay đổi mùa.'),
(3946, 6, 1456, '谦逊', 'qiānxùn', 'Khiêm tốn', '他很谦逊，从不夸耀。', 'Tā hěn qiānxùn, cóng bù kuāyào.', 'Anh ấy rất khiêm tốn, không bao giờ khoe khoang.'),
(3947, 6, 1457, '牵制', 'qiānzhì', 'Kìm chế, ràng buộc', '她的发言起到了牵制作用。', 'Tā de fāyán qǐ dào le qiānzhì zuòyòng.', 'Phát biểu của cô ấy có tác dụng kiềm chế.'),
(3948, 6, 1458, '前景', 'qiánjǐng', 'Triển vọng', '公司的前景很光明。', 'Gōngsī de qiánjǐng hěn guāngmíng.', 'Triển vọng của công ty rất tươi sáng.'),
(3949, 6, 1459, '潜力', 'qiánlì', 'Tiềm năng', '他有很大的潜力。', 'Tā yǒu hěn dà de qiánlì.', 'Anh ấy có tiềm năng lớn.'),
(3950, 6, 1460, '潜水', 'qiánshuǐ', 'Lặn', '他喜欢潜水。', 'Tā xǐhuān qiánshuǐ.', 'Anh ấy thích lặn.'),
(3951, 6, 1461, '前提', 'qiántí', 'Tiền đề', '这是合作的前提。', 'Zhè shì hézuò de qiántí.', 'Đây là điều kiện tiên quyết để hợp tác.'),
(3952, 6, 1462, '潜移默化', 'qiányímòhuà', 'Thay đổi ngầm', '这种影响是潜移默化的。', 'Zhè zhǒng yǐngxiǎng shì qiányímòhuà de.', 'Loại ảnh hưởng này là thầm lặng và từ từ.'),
(3953, 6, 1463, '谴责', 'qiǎnzé', 'Khiển trách, lên án', '他们谴责了这种行为。', 'Tāmen qiǎnzé le zhè zhǒng xíngwéi.', 'Họ đã lên án hành động này.'),
(3954, 6, 1464, '抢劫', 'qiǎngjié', 'Cướp bóc', '警察阻止了抢劫。', 'Jǐngchá zǔzhǐ le qiǎngjié.', 'Cảnh sát đã ngăn chặn vụ cướp.'),
(3955, 6, 1465, '强制', 'qiángzhì', 'Ép buộc, cưỡng chế', '法律强制执行。', 'Fǎlǜ qiángzhì zhíxíng.', 'Luật pháp được thi hành bắt buộc.'),
(3956, 6, 1466, '抢救', 'qiǎngjiù', 'Cứu trợ, cấp cứu', '他因心脏病被紧急抢救。', 'Tā yīn xīnzàngbìng bèi jǐnjí qiǎngjiù.', 'Anh ấy được cấp cứu khẩn cấp vì bệnh tim.'),
(3957, 6, 1467, '强迫', 'qiǎngpò', 'Ép buộc, cưỡng ép', '不要强迫孩子做不喜欢的事。', 'Bùyào qiǎngpò háizi zuò bù xǐhuan de shì.', 'Đừng ép buộc trẻ làm việc chúng không thích.'),
(3958, 6, 1468, '桥梁', 'qiáoliáng', 'Cầu, cầu nối', '这座桥梁连接了两地。', 'Zhè zuò qiáoliáng liánjiē le liǎngdì.', 'Cây cầu này nối liền hai nơi.'),
(3959, 6, 1469, '翘', 'qiào', 'Vểnh, nhô lên', '她的睫毛很翘。', 'Tā de jiémáo hěn qiào.', 'Lông mi của cô ấy rất cong.'),
(3960, 6, 1470, '锲而不舍', 'qiè''érbùshě', 'Kiên trì không bỏ cuộc', '我们要锲而不舍地追求梦想。', 'Wǒmen yào qiè''érbùshě de zhuīqiú mèngxiǎng.', 'Chúng ta phải kiên trì theo đuổi ước mơ.'),
(3961, 6, 1471, '切实', 'qièshí', 'Thiết thực, cụ thể', '我们要采取切实的措施。', 'Wǒmen yào cǎiqǔ qièshí de cuòshī.', 'Chúng ta phải thực hiện các biện pháp thiết thực.'),
(3962, 6, 1472, '侵犯', 'qīnfàn', 'Xâm phạm, xâm lấn', '侵犯他人的权利是不对的。', 'Qīnfàn tārén de quánlì shì bù duì de.', 'Xâm phạm quyền lợi của người khác là sai trái.'),
(3963, 6, 1473, '钦佩', 'qīnpèi', 'Kính phục, thán phục', '我钦佩他的勇气。', 'Wǒ qīnpèi tā de yǒngqì.', 'Tôi khâm phục sự dũng cảm của anh ấy.'),
(3964, 6, 1474, '亲热', 'qīnrè', 'Thân mật, nồng nhiệt', '他们关系很亲热。', 'Tāmen guānxì hěn qīnrè.', 'Họ có mối quan hệ rất thân thiết.'),
(3965, 6, 1475, '亲身', 'qīnshēn', 'Tự mình, bản thân', '他亲身经历了这件事。', 'Tā qīnshēn jīnglì le zhè jiàn shì.', 'Anh ấy đã trực tiếp trải qua chuyện này.'),
(3966, 6, 1476, '勤俭', 'qínjiǎn', 'Cần kiệm', '我们要勤俭节约。', 'Wǒmen yào qínjiǎn jiéyuē.', 'Chúng ta phải cần kiệm tiết kiệm.'),
(3967, 6, 1477, '勤恳', 'qínkěn', 'Chăm chỉ, cần cù', '她做事非常勤恳。', 'Tā zuò shì fēicháng qínkěn.', 'Cô ấy làm việc rất chăm chỉ.'),
(3968, 6, 1478, '氢', 'qīng', 'Khinh, khí hiếm', '氢是一种轻气体。', 'Qīng shì yī zhǒng qīng qìtǐ.', 'Hydro là một loại khí nhẹ.'),
(3969, 6, 1479, '清澈', 'qīngchè', 'Trong suốt', '湖水清澈见底。', 'Húshuǐ qīngchè jiàn dǐ.', 'Nước hồ trong veo đến đáy.'),
(3970, 6, 1480, '清晨', 'qīngchén', 'Sáng sớm', '清晨的空气很新鲜。', 'Qīngchén de kōngqì hěn xīnxiān.', 'Không khí buổi sáng sớm rất trong lành.'),
(3971, 6, 1481, '清除', 'qīngchú', 'Dọn sạch, loại bỏ', '我们需要清除杂草。', 'Wǒmen xūyào qīngchú zácǎo.', 'Chúng ta cần làm sạch cỏ dại.'),
(3972, 6, 1482, '轻而易举', 'qīng''éryìjǔ', 'Dễ dàng, dễ như trở bàn tay', '这个任务轻而易举。', 'Zhège rènwù qīng''éryìjǔ.', 'Nhiệm vụ này dễ dàng.'),
(3973, 6, 1483, '清洁', 'qīngjié', 'Sạch sẽ, vệ sinh', '房间需要清洁。', 'Fángjiān xūyào qīngjié.', 'Căn phòng cần được dọn dẹp.'),
(3974, 6, 1484, '清理', 'qīnglǐ', 'Dọn dẹp, sắp xếp', '请清理桌子上的书。', 'Qǐng qīnglǐ zhuōzi shàng de shū.', 'Hãy dọn sách trên bàn.'),
(3975, 6, 1485, '倾听', 'qīngtīng', 'Lắng nghe', '他静静地倾听大家的意见。', 'Tā jìngjìng de qīngtīng dàjiā de yìjiàn.', 'Anh ấy lắng nghe ý kiến của mọi người một cách yên lặng.'),
(3976, 6, 1486, '清晰', 'qīngxī', 'Rõ ràng, rõ nét', '图片非常清晰。', 'Túpiàn fēicháng qīngxī.', 'Hình ảnh rất rõ ràng.'),
(3977, 6, 1487, '倾向', 'qīngxiàng', 'Khuynh hướng, xu hướng', '他倾向于支持这个提案。', 'Tā qīngxiàng yú zhīchí zhège tí''àn.', 'Anh ấy có xu hướng ủng hộ đề xuất này.'),
(3978, 6, 1488, '倾斜', 'qīngxié', 'Nghiêng, lệch', '这栋房子有点倾斜。', 'Zhè dòng fángzi yǒudiǎn qīngxié.', 'Ngôi nhà này hơi nghiêng.'),
(3979, 6, 1489, '清醒', 'qīngxǐng', 'Tỉnh táo, sáng suốt', '他终于清醒了过来。', 'Tā zhōngyú qīngxǐng le guòlái.', 'Anh ấy cuối cùng đã tỉnh lại.'),
(3980, 6, 1490, '清真', 'qīngzhēn', 'Hồi giáo, chính giáo', '他是一位清真厨师。', 'Tā shì yī wèi qīngzhēn chúshī.', 'Anh ấy là một đầu bếp Halal.'),
(3981, 6, 1491, '情报', 'qíngbào', 'Tình báo, thông tin', '情报显示敌人正在接近。', 'Qíngbào xiǎnshì dírén zhèngzài jiējìn.', 'Thông tin tình báo cho thấy kẻ địch đang tiến gần.'),
(3982, 6, 1492, '情节', 'qíngjié', 'Tình tiết, chi tiết', '这本小说的情节很紧张。', 'Zhè běn xiǎoshuō de qíngjié hěn jǐnzhāng.', 'Cốt truyện của cuốn tiểu thuyết này rất căng thẳng.'),
(3983, 6, 1493, '晴朗', 'qínglǎng', 'Trời quang, trời trong', '天气晴朗，非常适合出游。', 'Tiānqì qínglǎng, fēicháng shìhé chūyóu.', 'Thời tiết trong lành, rất thích hợp để đi chơi.'),
(3984, 6, 1494, '情理', 'qínglǐ', 'Lý lẽ, đạo lý', '这种行为不符合情理。', 'Zhè zhǒng xíngwéi bù fúhé qínglǐ.', 'Hành vi này không hợp lý.'),
(3985, 6, 1495, '情形', 'qíngxíng', 'Tình hình, hoàn cảnh', '目前的情形非常复杂。', 'Mùqián de qíngxíng fēicháng fùzá.', 'Tình hình hiện tại rất phức tạp.'),
(3986, 6, 1496, '请柬', 'qǐngjiǎn', 'Thiệp mời', '我们收到了你的请柬。', 'Wǒmen shōudào le nǐ de qǐngjiǎn.', 'Chúng tôi đã nhận được thiệp mời của bạn.'),
(3987, 6, 1497, '请教', 'qǐngjiào', 'Thỉnh giáo, xin ý kiến', '请教我如何使用这个软件。', 'Qǐngjiào wǒ rúhé shǐyòng zhège ruǎnjiàn.', 'Hãy chỉ tôi cách sử dụng phần mềm này.'),
(3988, 6, 1498, '请示', 'qǐngshì', 'Xin chỉ thị, xin ý kiến', '他向上级请示了这件事。', 'Tā xiàng shàngjí qǐngshì le zhè jiàn shì.', 'Anh ấy đã xin phép cấp trên về việc này.'),
(3989, 6, 1499, '请帖', 'qǐngtiě', 'Thiệp mời', '我们收到了结婚请帖。', 'Wǒmen shōudào le jiéhūn qǐngtiě.', 'Chúng tôi đã nhận được thiệp cưới.'),
(3990, 6, 1500, '丘陵', 'qiūlíng', 'Đồi núi, đồi cỏ', '丘陵地区非常适合种植葡萄。', 'Qiūlíng dìqū fēicháng shìhé zhòngzhí pútáo.', 'Khu vực đồi núi rất thích hợp trồng nho.'),
(3991, 6, 1501, '区分', 'qūfēn', 'Phân biệt, chia tách', '我们需要区分事实和观点。', 'Wǒmen xūyào qūfēn shìshí hé guāndiǎn.', 'Chúng ta cần phân biệt giữa sự thật và quan điểm.'),
(3992, 6, 1502, '屈服', 'qūfú', 'Khuất phục, đầu hàng', '面对强大的对手，他不得不屈服。', 'Miànduì qiángdà de duìshǒu, tā bùdé bù qūfú.', 'Đối mặt với đối thủ mạnh, anh ta buộc phải khuất phục.'),
(3993, 6, 1503, '区域', 'qūyù', 'Khu vực, vùng', '这个区域禁止吸烟。', 'Zhège qūyù jìnzhǐ xīyān.', 'Khu vực này cấm hút thuốc.'),
(3994, 6, 1504, '曲折', 'qūzhé', 'Quanh co, khúc khuỷu', '这条路非常曲折。', 'Zhè tiáo lù fēicháng qūzhé.', 'Con đường này rất quanh co.'),
(3995, 6, 1505, '驱逐', 'qūzhú', 'Trục xuất, xua đuổi', '他被驱逐出境了。', 'Tā bèi qūzhú chūjìng le.', 'Anh ấy đã bị trục xuất ra khỏi đất nước.'),
(3996, 6, 1506, '渠道', 'qúdào', 'Kênh rạch, kênh', '他们正在挖掘新的渠道。', 'Tāmen zhèngzài wājué xīn de qúdào.', 'Họ đang đào kênh mới.'),
(3997, 6, 1507, '取缔', 'qǔdì', 'Cấm đoán, cấm chỉ', '政府取缔了非法活动。', 'Zhèngfǔ qǔdì le fēifǎ huódòng.', 'Chính phủ đã cấm các hoạt động bất hợp pháp.'),
(3998, 6, 1508, '曲子', 'qǔzi', 'Bài hát, bản nhạc', '这首曲子很动听。', 'Zhè shǒu qǔzi hěn dòngtīng.', 'Bài hát này rất hay.'),
(3999, 6, 1509, '趣味', 'qùwèi', 'Hứng thú, thú vị', '他对生活充满了趣味。', 'Tā duì shēnghuó chōngmǎn le qùwèi.', 'Anh ấy rất thú vị trong cuộc sống.'),
(4000, 6, 1510, '圈套', 'quāntào', 'Cái bẫy, cạm bẫy', '他掉进了对手设的圈套。', 'Tā diào jìn le duìshǒu shè de quāntào.', 'Anh ấy đã rơi vào bẫy của đối thủ.');
INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(4001, 6, 1511, '权衡', 'quánhéng', 'Cân nhắc, xem xét', '我们需要权衡利弊。', 'Wǒmen xūyào quánhéng lìbì.', 'Chúng ta cần cân nhắc lợi và hại.'),
(4002, 6, 1512, '全局', 'quánjú', 'Toàn bộ cục diện', '公司的全局策略非常成功。', 'Gōngsī de quánjú cèlüè fēicháng chénggōng.', 'Chiến lược tổng thể của công ty rất thành công.'),
(4003, 6, 1513, '全力以赴', 'quánlìyǐfù', 'Dốc toàn lực, toàn tâm toàn ý', '我们将全力以赴完成任务。', 'Wǒmen jiāng quánlì yǐ fù wánchéng rènwù.', 'Chúng ta sẽ dốc hết sức hoàn thành nhiệm vụ.'),
(4004, 6, 1514, '拳头', 'quántou', 'Nắm đấm, quyền lực', '他的拳头很有力。', 'Tā de quántou hěn yǒulì.', 'Nắm đấm của anh ấy rất mạnh.'),
(4005, 6, 1515, '权威', 'quánwēi', 'Quyền uy, uy tín', '他是一位权威的学者。', 'Tā shì yī wèi quánwēi de xuézhě.', 'Anh ấy là một học giả có uy tín.'),
(4006, 6, 1516, '权益', 'quányì', 'Quyền lợi và lợi ích', '我们必须维护自己的权益。', 'Wǒmen bìxū wéihù zìjǐ de quányì.', 'Chúng ta phải bảo vệ quyền lợi của mình.'),
(4007, 6, 1517, '犬', 'quǎn', 'Chó, cẩu', '他养了一只可爱的犬。', 'Tā yǎng le yī zhǐ kě''ài de quǎn.', 'Anh ấy nuôi một con chó dễ thương.'),
(4008, 6, 1518, '缺口', 'quēkǒu', 'Chỗ hổng, khe hở', '墙上有一个缺口。', 'Qiáng shàng yǒu yī gè quēkǒu.', 'Trên tường có một lỗ hổng.'),
(4009, 6, 1519, '缺席', 'quēxí', 'Vắng mặt, không tham dự', '他因病缺席了会议。', 'Tā yīn bìng quēxí le huìyì.', 'Anh ấy vắng mặt trong cuộc họp vì bệnh.'),
(4010, 6, 1520, '缺陷', 'quēxiàn', 'Khiếm khuyết, khuyết điểm', '这个机器有一些缺陷。', 'Zhège jīqì yǒu yīxiē quēxiàn.', 'Cái máy này có một số khuyết điểm.'),
(4011, 6, 1521, '瘸', 'qué', 'Khập khiễng, què', '他摔倒了，腿瘸了。', 'Tā shuāidǎo le, tuǐ qué le.', 'Anh ấy bị ngã, và chân bị què.'),
(4012, 6, 1522, '确保', 'quèbǎo', 'Đảm bảo, bảo đảm', '我们必须确保安全。', 'Wǒmen bìxū quèbǎo ānquán.', 'Chúng ta phải đảm bảo an toàn.'),
(4013, 6, 1523, '确立', 'quèlì', 'Xác lập, thiết lập', '我们确立了新的目标。', 'Wǒmen quèlì le xīn de mùbiāo.', 'Chúng ta đã thiết lập mục tiêu mới.'),
(4014, 6, 1524, '确切', 'quèqiè', 'Chính xác, xác thực', '他的话很确切。', 'Tā de huà hěn quèqiè.', 'Lời của anh ấy rất chính xác.'),
(4015, 6, 1525, '确信', 'quèxìn', 'Tin chắc, tin tưởng', '我确信他会成功。', 'Wǒ quèxìn tā huì chénggōng.', 'Tôi tin chắc rằng anh ấy sẽ thành công.'),
(4016, 6, 1526, '群众', 'qúnzhòng', 'Quần chúng, nhân dân', '群众对这个政策表示支持。', 'Qúnzhòng duì zhège zhèngcè biǎoshì zhīchí.', 'Quần chúng ủng hộ chính sách này.'),
(4017, 6, 1527, '染', 'rǎn', 'Nhuộm, tô điểm', '他染上了坏习惯。', 'Tā rǎn shàng le huài xíguàn.', 'Anh ấy mắc phải thói quen xấu.'),
(4018, 6, 1528, '让步', 'ràngbù', 'Nhượng bộ, lùi bước', '他最终做出了让步。', 'Tā zuìzhōng zuò chū le ràngbù.', 'Cuối cùng, anh ấy đã nhượng bộ.'),
(4019, 6, 1529, '饶恕', 'ráoshù', 'Tha thứ, tha lỗi', '请你饶恕我的错误。', 'Qǐng nǐ ráoshù wǒ de cuòwù.', 'Xin hãy tha thứ cho lỗi lầm của tôi.'),
(4020, 6, 1530, '扰乱', 'rǎoluàn', 'Quấy rối, làm loạn', '这个消息扰乱了秩序。', 'Zhège xiāoxi rǎoluàn le zhìxù.', 'Tin tức này đã làm rối loạn trật tự.'),
(4021, 6, 1531, '惹祸', 'rěhuò', 'Gây họa, gây rắc rối', '他的行为惹祸了。', 'Tā de xíngwéi rěhuò le.', 'Hành động của anh ấy đã gây ra rắc rối.'),
(4022, 6, 1532, '热泪盈眶', 'rèlèiyíngkuàng', 'Nước mắt đầm đìa', '听到这个消息，她热泪盈眶。', 'Tīngdào zhège xiāoxi, tā rèlèi yíngkuàng.', 'Nghe tin này, cô ấy rơi nước mắt xúc động.'),
(4023, 6, 1533, '热门', 'rèmén', 'Phổ biến, thịnh hành', '这个话题非常热门。', 'Zhège huàtí fēicháng rèmén.', 'Chủ đề này rất hot.'),
(4024, 6, 1534, '仁慈', 'réncí', 'Nhân từ, nhân hậu', '他是一个仁慈的人。', 'Tā shì yī gè réncí de rén.', 'Anh ấy là một người nhân từ.'),
(4025, 6, 1535, '人道', 'réndào', 'Nhân đạo', '他们提倡人道待遇。', 'Tāmen tíchàng réndào dàiyù.', 'Họ khuyến khích đối xử nhân đạo.'),
(4026, 6, 1536, '人格', 'réngé', 'Nhân cách, phẩm cách', '他是一个有人格魅力的领导。', 'Tā shì yī gè yǒu réngé mèilì de lǐngdǎo.', 'Ông ấy là một nhà lãnh đạo có sức hút nhân cách.'),
(4027, 6, 1537, '人工', 'réngōng', 'Nhân công, lao động', '这种技术需要人工操作。', 'Zhè zhǒng jìshù xūyào réngōng cāozuò.', 'Công nghệ này cần thao tác bằng tay.'),
(4028, 6, 1538, '人家', 'rénjiā', 'Nhà cửa, gia đình', '人家都说他很聪明。', 'Rénjiā dōu shuō tā hěn cōngmíng.', 'Người ta đều nói anh ấy rất thông minh.'),
(4029, 6, 1539, '人间', 'rénjiān', 'Nhân gian, thế gian', '这是人间的天堂。', 'Zhè shì rénjiān de tiāntáng.', 'Đây là thiên đường trên trần gian.'),
(4030, 6, 1540, '人士', 'rénshì', 'Nhân sĩ, người', '许多知名人士出席了慈善晚会。', 'Xǔduō zhīmíng rénshì chūxí le císhàn wǎnhuì.', 'Nhiều nhân sĩ nổi tiếng đã tham dự đêm tiệc từ thiện.'),
(4031, 6, 1541, '人为', 'rénwéi', 'Do con người làm', '他的成功不是偶然的，而是人为的。', 'Tā de chénggōng bù shì ǒurán de, ér shì rénwéi de.', 'Thành công của anh ấy không phải là ngẫu nhiên mà là do con người tạo ra.'),
(4032, 6, 1542, '人性', 'rénxìng', 'Nhân tính, bản tính', '人性有时是复杂的。', 'Rénxìng yǒushí shì fùzá de.', 'Tính cách con người đôi khi rất phức tạp.'),
(4033, 6, 1543, '人质', 'rénzhì', 'Con tin, người bị bắt', '绑架者要求人质的家人支付赎金。', 'Bǎngjià zhě yāoqiú rénzhì de jiārén zhīfù shújīn.', 'Những kẻ bắt cóc yêu cầu gia đình con tin trả tiền chuộc.'),
(4034, 6, 1544, '忍耐', 'rěnnài', 'Nhẫn nại, chịu đựng', '你必须学会忍耐。', 'Nǐ bìxū xuéhuì rěnnài.', 'Bạn phải học cách kiên nhẫn.'),
(4035, 6, 1545, '忍受', 'rěnshòu', 'Chịu đựng, cam chịu', '我无法忍受这种痛苦。', 'Wǒ wúfǎ rěnshòu zhè zhǒng tòngkǔ.', 'Tôi không thể chịu đựng được nỗi đau này.'),
(4036, 6, 1546, '认定', 'rèndìng', 'Nhận định, xác định', '他认定这个计划是可行的。', 'Tā rèndìng zhège jìhuà shì kěxíng de.', 'Anh ấy xác định kế hoạch này là khả thi.'),
(4037, 6, 1547, '认可', 'rènkě', 'Công nhận, phê duyệt', '他的工作得到了认可。', 'Tā de gōngzuò dédào le rènkě.', 'Công việc của anh ấy đã được công nhận.'),
(4038, 6, 1548, '任命', 'rènmìng', 'Bổ nhiệm, cử nhiệm', '他被任命为公司经理。', 'Tā bèi rènmìng wèi gōngsī jīnglǐ.', 'Anh ấy được bổ nhiệm làm giám đốc công ty.'),
(4039, 6, 1549, '任性', 'rènxìng', 'Tùy hứng, bướng bỉnh', '她有点任性。', 'Tā yǒudiǎn rènxìng.', 'Cô ấy hơi bướng bỉnh.'),
(4040, 6, 1550, '任意', 'rènyì', 'Tùy ý, tự do', '你可以任意选择。', 'Nǐ kěyǐ rènyì xuǎnzé.', 'Bạn có thể chọn bất kỳ cái gì.'),
(4041, 6, 1551, '任重道远', 'rènzhòngdàoyuǎn', 'Trách nhiệm nặng nề và đường dài', '我们的任务任重道远。', 'Wǒmen de rènwù rènzhòngdàoyuǎn.', 'Nhiệm vụ của chúng ta còn rất nặng nề và xa xôi.'),
(4042, 6, 1552, '仍旧', 'réngjiù', 'Vẫn như cũ', '他仍旧没有改变他的计划。', 'Tā réngjiù méiyǒu gǎibiàn tā de jìhuà.', 'Anh ấy vẫn không thay đổi kế hoạch của mình.'),
(4043, 6, 1553, '日新月异', 'rìxīnyuèyì', 'Thay đổi từng ngày', '现代科技日新月异。', 'Xiàndài kējì rì xīn yuè yì.', 'Khoa học kỹ thuật hiện đại thay đổi từng ngày.'),
(4044, 6, 1554, '日益', 'rìyì', 'Ngày càng', '他的英语水平日益提高。', 'Tā de yīngyǔ shuǐpíng rìyì tígāo.', 'Trình độ tiếng Anh của anh ấy ngày càng tiến bộ.'),
(4045, 6, 1555, '溶解', 'róngjiě', 'Hòa tan', '这种物质可以溶解在水中。', 'Zhè zhǒng wùzhì kěyǐ róngjiě zài shuǐ zhōng.', 'Chất này có thể tan trong nước.'),
(4046, 6, 1556, '容貌', 'róngmào', 'Dung mạo', '她的容貌非常美丽。', 'Tā de róngmào fēicháng měilì.', 'Vẻ ngoài của cô ấy rất đẹp.'),
(4047, 6, 1557, '容纳', 'róngnà', 'Chứa đựng', '这个房间可以容纳50人。', 'Zhège fángjiān kěyǐ róngnà 50 rén.', 'Phòng này có thể chứa được 50 người.'),
(4048, 6, 1558, '容器', 'róngqì', 'Đồ đựng, dụng cụ chứa', '请把液体倒入这个容器中。', 'Qǐng bǎ yètǐ dàorù zhège róngqì zhōng.', 'Xin hãy đổ chất lỏng vào trong vật chứa này.'),
(4049, 6, 1559, '融洽', 'róngqià', 'Hòa hợp, êm thấm', '他们的关系非常融洽。', 'Tāmen de guānxì fēicháng róngqià.', 'Mối quan hệ của họ rất hòa hợp.'),
(4050, 6, 1560, '容忍', 'róngrěn', 'Chịu đựng, nhẫn nhịn', '我们必须学会容忍不同的意见。', 'Wǒmen bìxū xuéhuì róngrěn bùtóng de yìjiàn.', 'Chúng ta phải học cách chịu đựng những ý kiến khác nhau.'),
(4051, 6, 1561, '揉', 'róu', 'Xoa, bóp', '她轻轻地揉了揉眼睛。', 'Tā qīngqīng de róu le róu yǎnjīng.', 'Cô ấy nhẹ nhàng xoa mắt.'),
(4052, 6, 1562, '柔和', 'róuhé', 'Dịu dàng, mềm mại', '他的声音非常柔和。', 'Tā de shēngyīn fēicháng róuhé.', 'Giọng nói của anh ấy rất dịu dàng.'),
(4053, 6, 1563, '弱点', 'ruòdiǎn', 'Điểm yếu', '每个人都有弱点。', 'Měi gèrén dōu yǒu ruòdiǎn.', 'Mỗi người đều có điểm yếu.'),
(4054, 6, 1564, '若干', 'ruògān', 'Một vài, bao nhiêu', '你可以问我若干问题。', 'Nǐ kěyǐ wèn wǒ ruògān wèntí.', 'Bạn có thể hỏi tôi một vài câu hỏi.'),
(4055, 6, 1565, '撒谎', 'sāhuǎng', 'Nói dối', '他撒谎了。', 'Tā sāhuǎng le.', 'Anh ấy đã nói dối.'),
(4056, 6, 1566, '腮', 'sāi', 'Má, cằm', '她的腮很红。', 'Tā de sāi hěn hóng.', 'Má của cô ấy rất đỏ.'),
(4057, 6, 1567, '三角', 'sānjiǎo', 'Tam giác', '这个三角形有三个角。', 'Zhège sānjiǎoxíng yǒu sān gè jiǎo.', 'Hình tam giác này có ba góc.'),
(4058, 6, 1568, '散文', 'sǎnwén', 'Tản văn', '他写了一篇散文。', 'Tā xiě le yī piān sǎnwén.', 'Anh ấy đã viết một bài tản văn.'),
(4059, 6, 1569, '散发', 'sànfā', 'Tỏa ra, phát tán', '这个房间散发着香气。', 'Zhège fángjiān sànfā zhe xiāngqì.', 'Phòng này tỏa ra mùi thơm.'),
(4060, 6, 1570, '丧失', 'sàngshī', 'Mất mát', '他丧失了信心。', 'Tā sàngshī le xìnxīn.', 'Anh ấy đã mất niềm tin.'),
(4061, 6, 1571, '嫂子', 'sǎozi', 'Chị dâu', '她是我的嫂子。', 'Tā shì wǒ de sǎozi.', 'Cô ấy là chị dâu của tôi.'),
(4062, 6, 1572, '色彩', 'sècǎi', 'Màu sắc', '这个画作的色彩非常鲜艳。', 'Zhège huàzuò de sècǎi fēicháng xiānyàn.', 'Màu sắc của bức tranh này rất tươi sáng.'),
(4063, 6, 1573, '刹车', 'shāchē', 'Phanh, thắng', '刹车系统需要检查。', 'Shāchē xìtǒng xūyào jiǎnchá.', 'Hệ thống phanh cần được kiểm tra.'),
(4064, 6, 1574, '啥', 'shá', 'Gì (dạng khẩu ngữ của "什么")', '你在干啥呢？', 'Nǐ zài gàn shá ne?', 'Bạn đang làm gì vậy?'),
(4065, 6, 1575, '筛选', 'shāixuǎn', 'Sàng lọc, tuyển chọn', '我们需要筛选最好的候选人。', 'Wǒmen xūyào shāixuǎn zuì hǎo de hòuxuǎnrén.', 'Chúng ta cần chọn lọc ứng viên tốt nhất.'),
(4066, 6, 1576, '山脉', 'shānmài', 'Dãy núi', '这座山脉很壮观。', 'Zhè zuò shānmài hěn zhuàngguān.', 'Dãy núi này rất hùng vĩ.'),
(4067, 6, 1577, '闪烁', 'shǎnshuò', 'Lấp lánh, lung linh', '星星在天空中闪烁。', 'Xīngxīng zài tiānkōng zhōng shǎnshuò.', 'Những ngôi sao lấp lánh trên bầu trời.'),
(4068, 6, 1578, '擅长', 'shàncháng', 'Giỏi về, sở trường', '他擅长绘画。', 'Tā shàncháng huìhuà.', 'Anh ấy giỏi vẽ tranh.'),
(4069, 6, 1579, '擅自', 'shànzì', 'Tự ý, tự tiện', '不要擅自行动。', 'Bùyào shànzì xíngdòng.', 'Đừng hành động tùy tiện.'),
(4070, 6, 1580, '扇子', 'shànzi', 'Quạt', '她给我买了一把扇子。', 'Tā gěi wǒ mǎi le yī bǎ shànzi.', 'Cô ấy đã mua cho tôi một chiếc quạt.'),
(4071, 6, 1581, '商标', 'shāngbiāo', 'Thương hiệu', '这个商标很有名。', 'Zhège shāngbiāo hěn yǒumíng.', 'Thương hiệu này rất nổi tiếng.'),
(4072, 6, 1582, '伤脑筋', 'shāng nǎojīn', 'Đau đầu, khó khăn', '这个问题真是伤脑筋。', 'Zhège wèntí zhēn shì shāng nǎojīn.', 'Vấn đề này thật đau đầu.'),
(4073, 6, 1583, '上级', 'shàngjí', 'Cấp trên', '你需要向上级汇报。', 'Nǐ xūyào xiàng shàngjí huìbào.', 'Bạn cần báo cáo với cấp trên.'),
(4074, 6, 1584, '上进心', 'shàngjìnxīn', 'Tinh thần cầu tiến', '他有很强的上进心。', 'Tā yǒu hěn qiáng de shàngjìn xīn.', 'Anh ấy có động lực tiến bộ rất mạnh.'),
(4075, 6, 1585, '上任', 'shàngrèn', 'Nhậm chức', '新上任的经理很有能力。', 'Xīn shàngrèn de jīnglǐ hěn yǒu nénglì.', 'Giám đốc mới nhậm chức rất có năng lực.'),
(4076, 6, 1586, '上瘾', 'shàngyǐn', 'Nghiện', '他对咖啡上瘾了。', 'Tā duì kāfēi shàngyǐn le.', 'Anh ấy nghiện cà phê.'),
(4077, 6, 1587, '上游', 'shàngyóu', 'Thượng nguồn, phần tiên tiến', '这条河的上游很清澈。', 'Zhè tiáo hé de shàngyóu hěn qīngchè.', 'Thượng nguồn của con sông này rất trong sạch.'),
(4078, 6, 1588, '梢', 'shāo', 'Ngọn, chóp', '树梢上有一只鸟。', 'Shùshāo shàng yǒu yī zhǐ niǎo.', 'Trên ngọn cây có một con chim.'),
(4079, 6, 1589, '捎', 'shāo', 'Mang theo, đưa cho', '请把这封信捎给他。', 'Qǐng bǎ zhè fēng xìn shāo gěi tā.', 'Hãy mang lá thư này cho anh ấy.'),
(4080, 6, 1590, '哨', 'shào', 'Còi, kèn', '哨声响起，比赛开始了。', 'Shào shēng xiǎng qǐ, bǐsài kāishǐ le.', 'Tiếng còi vang lên, trận đấu bắt đầu.'),
(4081, 6, 1591, '奢侈', 'shēchǐ', 'Xa xỉ', '她喜欢奢侈品。', 'Tā xǐhuān shēchǐ pǐn.', 'Cô ấy thích hàng xa xỉ.'),
