(4962, 6, 2472, '资深', 'zīshēn', 'Kinh nghiệm', '他是一位资深工程师。', 'Tā shì yī wèi zīshēn gōngchéngshī.', 'Anh ấy là một kỹ sư có kinh nghiệm lâu năm.'),
(4963, 6, 2473, '姿态', 'zītài', 'Tư thế', '她的姿态非常优雅。', 'Tā de zītài fēicháng yōuyǎ.', 'Tư thế của cô ấy rất thanh lịch.'),
(4964, 6, 2474, '滋味', 'zīwèi', 'Mùi vị', '这道菜的滋味很好。', 'Zhè dào cài de zīwèi hěn hǎo.', 'Hương vị của món ăn này rất ngon.'),
(4965, 6, 2475, '滋长', 'zīzhǎng', 'Tăng trưởng', '小树苗在春天滋长。', 'Xiǎo shùmiáo zài chūntiān zīzhǎng.', 'Cây non lớn lên vào mùa xuân.'),
(4966, 6, 2476, '资助', 'zīzhù', 'Tài trợ', '他资助了很多贫困学生。', 'Tā zīzhù le hěn duō pínkùn xuéshēng.', 'Anh ấy tài trợ cho nhiều học sinh nghèo.'),
(4967, 6, 2477, '子弹', 'zǐdàn', 'Đạn', '他用子弹击中了目标。', 'Tā yòng zǐdàn jīzhòng le mùbiāo.', 'Anh ấy bắn trúng mục tiêu bằng đạn.'),
(4968, 6, 2478, '自卑', 'zìbēi', 'Tự ti', '他有时感到自卑。', 'Tā yǒushí gǎndào zìbēi.', 'Đôi khi anh ấy cảm thấy tự ti.'),
(4969, 6, 2479, '自发', 'zìfā', 'Tự phát', '这是一个自发的活动。', 'Zhè shì yī gè zìfā de huódòng.', 'Đây là một hoạt động tự phát.'),
(4970, 6, 2480, '自力更生', 'zìlì gēngshēng', 'Tự lực cánh sinh', '我们应该自力更生。', 'Wǒmen yīnggāi zìlìgēngshēng.', 'Chúng ta nên tự lực cánh sinh.'),
(4971, 6, 2481, '自满', 'zìmǎn', 'Tự mãn', '自满是成功的敌人。', 'Zìmǎn shì chénggōng de dírén.', 'Tự mãn là kẻ thù của thành công.'),
(4972, 6, 2482, '字母', 'zìmǔ', 'Chữ cái', '请按照字母顺序排列。', 'Qǐng ànzhào zìmǔ shùnxù páiliè.', 'Hãy sắp xếp theo thứ tự bảng chữ cái.'),
(4973, 6, 2483, '自主', 'zìzhǔ', 'Tự chủ', '我们要自主完成任务。', 'Wǒmen yào zìzhǔ wánchéng rènwù.', 'Chúng ta phải tự chủ hoàn thành nhiệm vụ.'),
(4974, 6, 2484, '踪迹', 'zōngjì', 'Dấu vết', '这个地方没有任何踪迹。', 'Zhège dìfāng méiyǒu rènhé zōngjì.', 'Không có bất kỳ dấu vết nào ở nơi này.'),
(4975, 6, 2485, '棕色', 'zōngsè', 'Màu nâu', '他的头发是棕色的。', 'Tā de tóufà shì zōngsè de.', 'Tóc của anh ấy có màu nâu.'),
(4976, 6, 2486, '宗旨', 'zōngzhǐ', 'Tôn chỉ', '公司的宗旨是客户至上。', 'Gōngsī de zōngzhǐ shì kèhù zhì shàng.', 'Tôn chỉ của công ty là khách hàng trên hết.'),
(4977, 6, 2487, '总而言之', 'zǒng''éryánzhī', 'Tóm lại', '总而言之，我们需要努力。', 'Zǒng''éryánzhī, wǒmen xūyào nǔlì.', 'Nói chung, chúng ta cần phải nỗ lực.'),
(4978, 6, 2488, '总和', 'zǒnghé', 'Tổng hợp', '这两项数值的总和是100。', 'Zhè liǎng xiàng shùzhí de zǒnghé shì 100.', 'Tổng của hai giá trị này là 100.'),
(4979, 6, 2489, '纵横', 'zònghéng', 'Ngang dọc', '他在世界各地纵横驰骋。', 'Tā zài shìjiè gèdì zònghéng chíchěng.', 'Anh ấy tung hoành khắp nơi trên thế giới.'),
(4980, 6, 2490, '走廊', 'zǒuláng', 'Hành lang', '学校的走廊很宽敞。', 'Xuéxiào de zǒuláng hěn kuānchǎng.', 'Hành lang của trường rất rộng rãi.'),
(4981, 6, 2491, '走漏', 'zǒulòu', 'Rò rỉ', '他不小心走漏了消息。', 'Tā bù xiǎoxīn zǒulòu le xiāoxi.', 'Anh ấy đã vô tình để lộ tin tức.'),
(4982, 6, 2492, '走私', 'zǒusī', 'Buôn lậu', '警察在打击走私活动。', 'Jǐngchá zài dǎjí zǒusī huódòng.', 'Cảnh sát đang trấn áp các hoạt động buôn lậu.'),
(4983, 6, 2493, '揍', 'zòu', 'Đánh', '他被人揍了一顿。', 'Tā bèi rén zòu le yī dùn.', 'Anh ấy bị người ta đánh một trận.'),
(4984, 6, 2494, '租赁', 'zūlìn', 'Thuê', '我们需要租赁一些设备。', 'Wǒmen xūyào zūlìn yīxiē shèbèi.', 'Chúng ta cần thuê một số thiết bị.'),
(4985, 6, 2495, '足以', 'zúyǐ', 'Đủ để', '这个方法足以解决问题。', 'Zhège fāngfǎ zúyǐ jiějué wèntí.', 'Cách này đủ để giải quyết vấn đề.'),
(4986, 6, 2496, '组', 'zǔ', 'Nhóm', '我加入了一个学习组。', 'Wǒ jiārù le yī gè xuéxí zǔ.', 'Tôi đã tham gia một nhóm học tập.'),
(4987, 6, 2497, '阻碍', 'zǔ''ài', 'Cản trở', '雪阻碍了交通。', 'Xuě zǔ''ài le jiāotōng.', 'Tuyết cản trở giao thông.'),
(4988, 6, 2498, '祖父', 'zǔfù', 'Ông nội', '我的祖父很喜欢下棋。', 'Wǒ de zǔfù hěn xǐhuān xiàqí.', 'Ông tôi rất thích chơi cờ.'),
(4989, 6, 2499, '阻拦', 'zǔlán', 'Ngăn cản', '我们需要找到阻拦他的方法。', 'Wǒmen xūyào zhǎodào zǔlán tā de fāngfǎ.', 'Chúng ta cần tìm cách ngăn chặn anh ấy.'),
(4990, 6, 2500, '阻挠', 'zǔnáo', 'Cản trở', '他试图阻挠我们的计划。', 'Tā shìtú zǔnáo wǒmen de jìhuà.', 'Anh ấy cố gắng cản trở kế hoạch của chúng tôi.'),
(4991, 6, 2501, '钻研', 'zuānyán', 'Nghiên cứu kỹ lưỡng', '他钻研了这个课题很多年。', 'Tā zuānyán le zhège kètí hěn duō nián.', 'Anh ấy đã nghiên cứu chủ đề này nhiều năm.'),
(4992, 6, 2502, '钻石', 'zuànshí', 'Kim cương', '她收到了一颗钻石戒指。', 'Tā shōudào le yī kē zuànshí jièzhǐ.', 'Cô ấy đã nhận được một chiếc nhẫn kim cương.'),
(4993, 6, 2503, '嘴唇', 'zuǐchún', 'Môi', '她的嘴唇很红润。', 'Tā de zuǐchún hěn hóngrùn.', 'Môi của cô ấy rất hồng hào.'),
(4994, 6, 2504, '遵循', 'zūnxún', 'Tuân theo', '我们要遵循公司的规定。', 'Wǒmen yào zūnxún gōngsī de guīdìng.', 'Chúng ta phải tuân theo quy định của công ty.'),
(4995, 6, 2505, '尊严', 'zūnyán', 'Nhân phẩm', '他一直保持着自己的尊严。', 'Tā yīzhí bǎochí zhe zìjǐ de zūnyán.', 'Anh ấy luôn giữ gìn lòng tự trọng của mình.'),
(4996, 6, 2506, '左右', 'zuǒyòu', 'Khoảng', '他试图左右我们的决定。', 'Tā shìtú zuǒyòu wǒmen de juédìng.', 'Anh ấy cố gắng ảnh hưởng đến quyết định của chúng tôi.'),
(4997, 6, 2507, '作弊', 'zuòbì', 'Gian lận', '作弊是不道德的行为。', 'Zuòbì shì bù dàodé de xíngwéi.', 'Gian lận là hành vi không đạo đức.'),
(4998, 6, 2508, '做东', 'zuòdōng', 'Làm chủ', '今天他是做东的。', 'Jīntiān tā shì zuò dōng de.', 'Hôm nay anh ấy là chủ nhà.'),
(4999, 6, 2509, '作废', 'zuòfèi', 'Vô hiệu', '这些旧文件需要作废。', 'Zhèxiē jiù wénjiàn xūyào zuòfèi.', 'Những tài liệu cũ này cần bị hủy bỏ.'),
(5000, 6, 2510, '作风', 'zuòfēng', 'Phong cách', '公司需要改进作风。', 'Gōngsī xūyào gǎijìn zuòfēng.', 'Công ty cần cải thiện tác phong.');
INSERT INTO `hsk_vocabulary` (`id`, `hsk_level`, `stt`, `word`, `pinyin`, `meaning`, `example_zh`, `example_pinyin`, `example_vi`) VALUES
(5001, 6, 2511, '作息', 'zuòxī', 'Làm việc và nghỉ ngơi', '我们的作息时间要规律。', 'Wǒmen de zuòxī shíjiān yào guīlǜ.', 'Giờ giấc sinh hoạt của chúng ta cần phải có quy củ.'),
(5002, 6, 2512, '座右铭', 'zuòyòumíng', 'Câu nói yêu thích', '他的座右铭是"努力奋斗"。', 'Tā de zuòyòumíng shì "nǔlì fèndòu".', 'Châm ngôn của anh ấy là "cố gắng phấn đấu".'),
(5003, 6, 2513, '做主', 'zuòzhǔ', 'Quyết định', '他愿意为自己做主。', 'Tā yuànyì wèi zìjǐ zuòzhǔ.', 'Anh ấy sẵn sàng tự làm chủ.');
