-- =========================================================
-- HSK 1 - HSK 6 VOCABULARY DATABASE (5,003 WORDS, CLEANED)
-- Compatible with MySQL / MariaDB (UTF8MB4)
-- =========================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `hsk_vocabulary`;
CREATE TABLE `hsk_vocabulary` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `hsk_level` TINYINT UNSIGNED NOT NULL COMMENT 'Cấp độ HSK (1-6)',
  `stt` INT UNSIGNED NOT NULL COMMENT 'Số thứ tự trong cấp HSK',
  `word` VARCHAR(64) NOT NULL COMMENT 'Từ mới (Chữ Hán)',
  `pinyin` VARCHAR(128) NOT NULL COMMENT 'Phiên âm Pinyin',
  `meaning` VARCHAR(512) NOT NULL COMMENT 'Giải thích nghĩa tiếng Việt',
  `example_zh` TEXT NOT NULL COMMENT 'Ví dụ (Chữ Hán)',
  `example_pinyin` TEXT NOT NULL COMMENT 'Phiên âm câu ví dụ',
  `example_vi` TEXT NOT NULL COMMENT 'Dịch câu ví dụ',
  PRIMARY KEY (`id`),
  INDEX `idx_hsk_level` (`hsk_level`, `stt`),
  INDEX `idx_word` (`word`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;












SET FOREIGN_KEY_CHECKS = 1;
